function normalizeImportCountryHint(value = "") {
  const clean = String(value || "").trim().toLowerCase().replace(/[^a-z0-9+]+/g, " ").replace(/\s+/g, " ").trim();
  if (!clean) return null;
  const digits = clean.replace(/\D/g, "");
  return NEXTGEN_IMPORT_PHONE_COUNTRY_RULES.find((rule) => {
    const aliases = [rule.iso2, rule.code, `+${rule.code}`, rule.country, ...(rule.aliases || [])].map((x) => String(x || "").trim().toLowerCase());
    return aliases.includes(clean) || (digits && digits === rule.code);
  }) || null;
}

function getImportDefaultCountryRule({ row = {}, defaults = {} } = {}) {
  return normalizeImportCountryHint(
    row.default_country_code || row.country_code || row.phone_country_code || row.country || row.default_country ||
    defaults.default_country_code || defaults.country_code || defaults.phone_country_code || defaults.selected_country_code || defaults.country || defaults.default_country || ""
  );
}

function truthyImportChoice(value) {
  if (value === true) return true;
  if (value === false || value === null || value === undefined) return false;
  const clean = String(value || "").trim().toLowerCase();
  return ["1", "true", "yes", "y", "on", "enabled", "auto", "apply", "add", "plus_one", "+1"].includes(clean);
}

function shouldApplyDefaultCountryCode({ row = {}, defaults = {} } = {}) {
  return truthyImportChoice(
    row.add_missing_country_code ??
    row.apply_default_country_code ??
    row.auto_apply_default_country_code ??
    row.attach_default_country_code ??
    row.add_plus_one_to_missing ??
    row.attach_plus_one ??
    defaults.add_missing_country_code ??
    defaults.apply_default_country_code ??
    defaults.auto_apply_default_country_code ??
    defaults.attach_default_country_code ??
    defaults.add_plus_one_to_missing ??
    defaults.attach_plus_one ??
    defaults.add_country_code_to_missing
  );
}

function stripPhoneExtension(raw = "") {
  return String(raw || "")
    .replace(/(ext\.?|extension|x)\s*\d+\s*$/i, "")
    .replace(/[#;].*$/, "")
    .trim();
}

function extractPhoneDigitsForImport(rawValue = "") {
  let raw = stripPhoneExtension(rawValue);
  raw = raw.replace(/(?:https?:\/\/)?(?:wa\.me|api\.whatsapp\.com\/send\?phone=)/i, " ");
  const hasLeadingPlus = /^\s*\+/.test(raw);
  const digits = raw.replace(/\D/g, "");
  return { raw, digits, hasLeadingPlus };
}

function findImportCountryByInternationalDigits(digits = "") {
  const clean = String(digits || "").replace(/\D/g, "");
  return [...NEXTGEN_IMPORT_PHONE_COUNTRY_RULES]
    .sort((a, b) => String(b.code).length - String(a.code).length)
    .find((rule) => clean.startsWith(rule.code)) || null;
}

function isPlausibleInternationalPhoneDigits(digits = "", rule = null) {
  const clean = String(digits || "").replace(/\D/g, "");
  if (!clean) return false;
  if (clean.length < 8 || clean.length > 15) return false;
  if (!rule) return true;
  const national = clean.slice(String(rule.code).length);
  if ((rule.international_lengths || []).includes(clean.length)) return true;
  if ((rule.national_lengths || []).includes(national.length)) return true;
  // Keep global tolerance because WhatsApp accepts many country formats and some countries have variable lengths.
  return national.length >= 7 && national.length <= 12;
}

function isLikelyNanpLocalTenDigits(digits = "") {
  const clean = String(digits || "").replace(/\D/g, "");
  if (clean.length !== 10) return false;
  // NANP area code and exchange cannot start with 0/1. If this fails, mark possible issue instead of silently sending.
  return /^[2-9]\d{2}[2-9]\d{6}$/.test(clean);
}

function normalizePhoneForImport(row = {}, defaults = {}) {
  const rawValue = row.whatsapp || row.whatsapp_phone || row.phone || row.mobile || row.contact_number || row.wa_id || "";
  const defaultRule = getImportDefaultCountryRule({ row, defaults });
  const applyDefault = shouldApplyDefaultCountryCode({ row, defaults });
  const selectedCountryLabel = normalizeCrmString(row.country || defaults.country || row.default_country || defaults.default_country || "");
  const { raw, digits: originalDigits, hasLeadingPlus } = extractPhoneDigitsForImport(rawValue);

  const result = {
    raw,
    raw_input: rawValue,
    digits: originalDigits,
    e164: "",
    whatsapp: "",
    phone: "",
    country: "",
    country_code: "",
    iso2: "",
    region: "global",
    language: "english",
    status: "missing_phone",
    category: "missing_phone",
    valid: false,
    can_message: false,
    has_explicit_country_code: false,
    applied_default_country_code: false,
    needs_country_code: false,
    possible_wrong_country_code: false,
    warnings: [],
    errors: [],
  };

  if (!originalDigits) {
    result.errors.push("Missing phone number");
    return result;
  }

  let digits = originalDigits;
  let explicitInternational = hasLeadingPlus;

  // International dialing prefixes commonly pasted from CRMs or sheets.
  if (!explicitInternational && digits.startsWith("00") && digits.length > 8) {
    digits = digits.slice(2);
    explicitInternational = true;
    result.has_explicit_country_code = true;
  } else if (!explicitInternational && digits.startsWith("011") && digits.length > 9) {
    digits = digits.slice(3);
    explicitInternational = true;
    result.has_explicit_country_code = true;
  }

  let detectedRule = findImportCountryByInternationalDigits(digits);

  // Keep explicit country code if it is present, even if the selected/default country says something else.
  if (explicitInternational || (detectedRule && isPlausibleInternationalPhoneDigits(digits, detectedRule) && digits.length !== 10)) {
    result.has_explicit_country_code = true;
    if (!detectedRule) detectedRule = findImportCountryByInternationalDigits(digits);
    if (!isPlausibleInternationalPhoneDigits(digits, detectedRule)) {
      result.status = "invalid_phone";
      result.category = "invalid_phone";
      result.errors.push("Phone has country code but length is not valid for WhatsApp/E.164");
      return result;
    }
  } else if (defaultRule && (applyDefault || Boolean(selectedCountryLabel) || Boolean(row.country_code || row.phone_country_code || row.default_country_code))) {
    // v117: If the CSV row itself says USA/India/Pakistan/UAE/etc., apply that country code automatically.
    // Admin toggle is still honored, but explicit row country no longer blocks import as "needs_country_code".
    let national = digits;
    if (defaultRule.code === "1") {
      if (digits.length === 11 && digits.startsWith("1")) national = digits.slice(1);
      if (digits.length !== 10 && !(digits.length === 11 && digits.startsWith("1"))) {
        result.status = "invalid_phone";
        result.category = "invalid_phone";
        result.errors.push("US/Canada numbers must be 10 digits, or 11 digits starting with 1");
        return result;
      }
      if (!isLikelyNanpLocalTenDigits(national)) {
        result.warnings.push("US/Canada number format looks unusual; check area code/exchange before sending");
        result.possible_wrong_country_code = true;
      }
      digits = `1${national}`;
    } else if (defaultRule.code === "92") {
      if (digits.startsWith("92") && digits.length >= 11) {
        // Already has Pakistan country code without plus. Keep it.
      } else if (digits.startsWith("0") && digits.length >= 10) {
        digits = `92${digits.slice(1)}`;
      } else if (digits.startsWith("3") && digits.length === 10) {
        digits = `92${digits}`;
      } else {
        digits = `${defaultRule.code}${digits.replace(/^0+/, "")}`;
      }
    } else {
      const national = digits.startsWith("0") && digits.length > 8 ? digits.replace(/^0+/, "") : digits;
      digits = `${defaultRule.code}${national}`;
    }
    detectedRule = defaultRule;
    result.applied_default_country_code = true;
  } else if (defaultRule && !applyDefault && digits.length <= 11 && !detectedRule) {
    result.status = "needs_country_code";
    result.category = "needs_country_code";
    result.needs_country_code = true;
    result.errors.push(`Missing country code. Select ${defaultRule.country} and enable Add country code, or upload with +${defaultRule.code}.`);
    return result;
  } else if (!detectedRule) {
    if (digits.length === 10) {
      result.status = "needs_country_code";
      result.category = "needs_country_code";
      result.needs_country_code = true;
      result.errors.push("Missing country code. Choose Add +1 / selected country code, or upload in international format.");
      return result;
    }
    result.status = digits.length < 8 || digits.length > 15 ? "invalid_phone" : "possible_wrong_country_code";
    result.category = result.status;
    result.possible_wrong_country_code = result.status === "possible_wrong_country_code";
    result.errors.push(result.status === "invalid_phone" ? "Phone length is invalid" : "Could not confidently detect country code");
    return result;
  }

  detectedRule = findImportCountryByInternationalDigits(digits) || detectedRule || defaultRule;

  if (!isPlausibleInternationalPhoneDigits(digits, detectedRule)) {
    result.status = "invalid_phone";
    result.category = "invalid_phone";
    result.errors.push("Phone length is invalid for WhatsApp/E.164");
    return result;
  }

  if (detectedRule?.code === "1" && digits.length !== 11) {
    result.status = "invalid_phone";
    result.category = "invalid_phone";
    result.errors.push("US/Canada WhatsApp number must be +1 followed by 10 digits");
    return result;
  }

  if (detectedRule?.code === "1" && !isLikelyNanpLocalTenDigits(digits.slice(1))) {
    result.warnings.push("US/Canada number may have an invalid area code/exchange; keep in failed/suspect view if provider rejects it");
    result.possible_wrong_country_code = true;
  }

  const explicitRowCountryLabel = normalizeCrmString(row.country || row.country_code || row.phone_country_code || "");
  const explicitRowCountryRule = explicitRowCountryLabel ? normalizeImportCountryHint(explicitRowCountryLabel) : null;
  // Do not warn when the mismatch came only from the page's default country.
  // If the phone already has +92, +91, +44, +1, etc., the explicit phone code wins.
  // Warn only when the pasted row itself explicitly says a different country.
  if (explicitRowCountryRule && detectedRule && explicitRowCountryRule.code !== detectedRule.code) {
    result.warnings.push(`Row country (${explicitRowCountryLabel}) differs from detected phone country (${detectedRule.country}); kept the phone's explicit country code.`);
    result.possible_wrong_country_code = true;
  }

  result.e164 = `+${digits}`;
  result.whatsapp = result.e164;
  result.phone = result.e164;
  result.digits = digits;
  result.country = detectedRule?.country || "";
  result.country_code = detectedRule ? `+${detectedRule.code}` : "";
  result.iso2 = detectedRule?.iso2 || "";
  result.region = detectedRule?.region || "global";
  result.language = detectedRule?.language || "english";
  result.status = result.possible_wrong_country_code ? "possible_wrong_country_code" : "ready";
  result.category = result.status;
  result.valid = true;
  result.can_message = true;
  return result;
}

function detectCountryFromPhone(rawPhone, options = {}) {
  const normalized = normalizePhoneForImport({ phone: rawPhone, whatsapp: rawPhone }, options?.defaults || {});
  const phone = normalized.e164 || String(rawPhone || "").replace(/[^\d+]/g, "");
  return {
    phone,
    country: normalized.country || "",
    country_code: normalized.country_code || "",
    region: normalized.region || "global",
    language: normalized.language || "english",
    status: normalized.status,
    valid: normalized.valid,
  };
}

function parseManualContacts(input) {
  if (Array.isArray(input)) return input;

  const raw = String(input || "");
  return raw
    .split(/\n|,|;/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((value) => {
      if (value.includes("@") && !/\d{7,}/.test(value)) return { email: value };
      return { whatsapp: value, phone: value };
    });
}

function validateCrmContact(row = {}, defaults = {}) {
  const email = normalizeEmail(row.email || "");
  const emailValid = !email || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const phoneInfo = normalizePhoneForImport(row, defaults);
  const hasPhoneRaw = Boolean(phoneInfo.raw || phoneInfo.raw_input || phoneInfo.digits);
  const phoneValid = !hasPhoneRaw || phoneInfo.valid;
  const valid = Boolean((email && emailValid) || phoneInfo.valid);

  return {
    email,
    whatsapp: phoneInfo.whatsapp,
    phone: phoneInfo.phone,
    phone_e164: phoneInfo.e164,
    phone_digits: phoneInfo.digits,
    phone_info: phoneInfo,
    valid,
    email_valid: emailValid,
    phone_valid: phoneValid,
    can_message: Boolean(phoneInfo.valid && phoneInfo.can_message),
    errors: [
      emailValid ? null : "Invalid email",
      ...safeArray(phoneInfo.errors),
      valid ? null : "No valid email or phone",
    ].filter(Boolean),
    warnings: safeArray(phoneInfo.warnings),
  };
}

function findCouponForLead(db, { brandId, country, region, language, examType, leadStatus }) {
  const rules = ensureCrmArray(db, "coupon_rules").filter((rule) => {
    if (String(rule.brand_id) !== String(brandId)) return false;
    if (rule.active === false) return false;
    if (rule.country && country && String(rule.country).toLowerCase() !== String(country).toLowerCase()) return false;
    if (rule.region && region && String(rule.region).toLowerCase() !== String(region).toLowerCase()) return false;
    if (rule.language && language && String(rule.language).toLowerCase() !== String(language).toLowerCase()) return false;
    if (rule.exam_type && examType && String(rule.exam_type).toLowerCase() !== String(examType).toLowerCase()) return false;
    if (rule.lead_status && leadStatus && String(rule.lead_status).toLowerCase() !== String(leadStatus).toLowerCase()) return false;
    return true;
  });

  return rules[0] || null;
}


function importMergeEnabled(row = {}, defaults = {}) {
  const raw = row.merge_duplicates ?? row.merge_duplicate ?? row.update_existing ?? defaults.merge_duplicates ?? defaults.merge_duplicate ?? defaults.update_existing;
  if (raw === false) return false;
  if (raw === true || raw === undefined || raw === null || raw === "") return true;
  return !["0", "false", "no", "off", "skip", "block"].includes(String(raw).trim().toLowerCase());
}

function getImportLeadPhoneDigits(lead = {}) {
  return String(
    lead.phone_digits ||
    lead.phone_e164 ||
    lead.whatsapp_phone ||
    lead.whatsapp ||
    lead.phone ||
    lead.mobile ||
    lead.wa_id ||
    ""
  ).replace(/\D/g, "");
}

function findExistingImportLead(leads = [], { email = "", phoneDigits = "", brandId = "" } = {}) {
  const cleanEmail = normalizeEmail(email || "");
  const cleanPhone = String(phoneDigits || "").replace(/\D/g, "");

  return leads.find((lead) => {
    if (brandId && lead.brand_id && String(lead.brand_id) !== String(brandId)) return false;
    const leadEmail = normalizeEmail(lead.email || lead.lead_email || lead.contact_email || "");
    const leadPhone = getImportLeadPhoneDigits(lead);
    return Boolean(
      (cleanEmail && leadEmail && leadEmail === cleanEmail) ||
      (cleanPhone && leadPhone && leadPhone === cleanPhone)
    );
  }) || null;
}

function buildImportPreviewRows({ db, brandId, rows = [], defaults = {} }) {
  const leads = ensureCrmArray(db, "leads");

  return rows.map((rawRow, index) => {
    const row = typeof rawRow === "string" ? (rawRow.includes("@") && !/\d{7,}/.test(rawRow) ? { email: rawRow } : { whatsapp: rawRow, phone: rawRow }) : rawRow || {};
    const mergedDefaults = { ...(defaults || {}), ...(row.defaults || {}) };
    const validation = validateCrmContact(row, mergedDefaults);
    const phoneInfo = validation.phone_info || normalizePhoneForImport(row, mergedDefaults);
    const email = validation.email;
    const whatsapp = validation.whatsapp || phoneInfo.whatsapp || "";
    const phoneDigits = phoneInfo.digits || whatsapp.replace(/\D/g, "");
    const existingLead = findExistingImportLead(leads, { email, phoneDigits, brandId });
    const duplicate = Boolean(existingLead);
    const shouldMergeDuplicate = duplicate && importMergeEnabled(row, mergedDefaults);

    // Explicit phone country code wins over the page default. This prevents +92 phones from
    // showing as USA just because the dropdown/default country was USA/Canada.
    const country = phoneInfo.country || row.country || mergedDefaults.country || "";
    const region = row.region || phoneInfo.region || mergedDefaults.region || "global";
    const language = row.language || phoneInfo.language || mergedDefaults.language || "english";
    const couponRule = findCouponForLead(db, {
      brandId,
      country,
      region,
      language,
      examType: row.exam_type || mergedDefaults.exam_type || "",
      leadStatus: row.status || "imported",
    });

    let importStatus = "ready";
    if (duplicate && !shouldMergeDuplicate) importStatus = "duplicate";
    else if (duplicate && shouldMergeDuplicate) importStatus = "merge_existing";
    else if (!validation.valid) importStatus = phoneInfo.category || "invalid_contact";
    else if (phoneInfo.needs_country_code) importStatus = "needs_country_code";
    else if (phoneInfo.possible_wrong_country_code) importStatus = "possible_wrong_country_code";
    else if (!validation.can_message && email) importStatus = "email_only_no_whatsapp";

    const canMessage = Boolean(validation.can_message && (!duplicate || shouldMergeDuplicate) && !phoneInfo.needs_country_code && phoneInfo.valid);
    const importAction = duplicate
      ? (shouldMergeDuplicate ? "merge_existing" : "skip_duplicate")
      : validation.valid
        ? "create"
        : phoneInfo.needs_country_code
          ? "fix_country_code"
          : "skip_invalid";

    return {
      row_number: index + 1,
      name: normalizeCrmString(row.name || row.full_name || row.first_name || row.student_name || ""),
      email,
      whatsapp,
      phone: validation.phone || whatsapp,
      phone_e164: phoneInfo.e164 || "",
      phone_digits: phoneInfo.digits || "",
      phone_country_code: phoneInfo.country_code || "",
      phone_import_status: phoneInfo.status || importStatus,
      phone_import_category: phoneInfo.category || importStatus,
      missing_country_candidate_priority: phoneInfo.needs_country_code ? ["+1 US/Canada", "+91 India", "+92 Pakistan", "+971 UAE", "+249 Sudan", "+234 Nigeria", "+966 Saudi", "+974 Qatar", "+965 Kuwait", "+968 Oman", "+973 Bahrain", "+44 UK", "+20 Egypt", "+962 Jordan"] : [],
      country,
      region,
      language,
      platform: normalizeCrmLeadSource(row.source_platform || row.platform || mergedDefaults.source_platform || mergedDefaults.platform || mergedDefaults.channel || mergedDefaults.source_type || "manual", { ...mergedDefaults, ...row }),
      source_platform: normalizeCrmLeadSource(row.source_platform || row.platform || mergedDefaults.source_platform || mergedDefaults.platform || mergedDefaults.channel || mergedDefaults.source_type || "manual", { ...mergedDefaults, ...row }),
      channel: normalizeCrmLeadSource(row.channel || row.source_platform || row.platform || mergedDefaults.channel || mergedDefaults.source_platform || mergedDefaults.platform || "manual", { ...mergedDefaults, ...row }),
      origin: normalizeCrmLeadOrigin(row.origin || mergedDefaults.origin || mergedDefaults.source_type || mergedDefaults.lead_source || "", { ...mergedDefaults, ...row }),
      lead_source: row.lead_source || mergedDefaults.lead_source || mergedDefaults.source_type || "manual_import",
      source_type: row.source_type || mergedDefaults.source_type || row.lead_source || mergedDefaults.lead_source || "manual_import",
      campaign_id: row.campaign_id || mergedDefaults.campaign_id || mergedDefaults.campaignId || "",
      campaign_name: row.campaign_name || mergedDefaults.campaign_name || mergedDefaults.source_campaign || "",
      campaign_key: row.campaign_key || mergedDefaults.campaign_key || "",
      ai_mode: normalizeCrmLeadAiMode(row.ai_mode || mergedDefaults.ai_mode || mergedDefaults.default_ai_mode || mergedDefaults.automation_mode || "draft"),
      stage: normalizeCrmLeadStageValue(row.stage || row.lead_stage || mergedDefaults.stage || mergedDefaults.lead_stage || "new_lead", "new_lead"),
      lead_stage: normalizeCrmLeadStageValue(row.stage || row.lead_stage || mergedDefaults.stage || mergedDefaults.lead_stage || "new_lead", "new_lead"),
      status: normalizeCrmLower(row.status || mergedDefaults.status || "new", "new") || "new",
      lead_status: normalizeCrmLower(row.lead_status || row.status || mergedDefaults.lead_status || mergedDefaults.status || "new", "new") || "new",
      source_community: row.source_community || mergedDefaults.source_community || "",
      exam_type: row.exam_type || mergedDefaults.exam_type || mergedDefaults.exam_track || "",
      exam_track: row.exam_track || mergedDefaults.exam_track || row.exam_type || mergedDefaults.exam_type || "",
      exam_timeline: row.exam_timeline || mergedDefaults.exam_timeline || "",
      graduation_year: row.graduation_year || mergedDefaults.graduation_year || "",
      notes: row.notes || row.pain_points || "",
      opt_in_status: row.opt_in_status || mergedDefaults.opt_in_status || (isCrmMetaLeadPayload({ ...mergedDefaults, ...row }) ? "meta_form_opt_in" : "unknown"),
      coupon_rule: couponRule ? { id: couponRule.id, coupon_code: couponRule.coupon_code, discount_percent: couponRule.discount_percent } : null,
      valid: validation.valid,
      can_message: canMessage,
      duplicate,
      duplicate_merge: shouldMergeDuplicate,
      will_merge_duplicate: shouldMergeDuplicate,
      existing_lead_id: existingLead?.id || null,
      import_status: importStatus,
      action: importAction,
      whatsapp_status: canMessage ? "not_checked" : phoneInfo.needs_country_code ? "needs_country_code" : phoneInfo.valid ? "not_checked" : "not_sendable",
      errors: validation.errors || [],
      warnings: validation.warnings || [],
      record: {
        ...(row.record || {}),
        ...row,
        whatsapp,
        phone: validation.phone || whatsapp,
        phone_e164: phoneInfo.e164 || "",
        phone_digits: phoneInfo.digits || "",
        country,
        region,
        language,
      },
    };
  });
}

function summarizeImportPreviewRows(rows = []) {
  const count = (fn) => rows.filter(fn).length;
  const byStatus = rows.reduce((acc, row) => {
    const key = row.import_status || row.phone_import_status || "unknown";
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});

  return {
    total_rows: rows.length,
    valid_rows: count((row) => row.valid && (!row.duplicate || row.duplicate_merge || row.action === "merge_existing")),
    ready_rows: count((row) => (row.import_status === "ready" || row.import_status === "merge_existing") && (!row.duplicate || row.duplicate_merge || row.action === "merge_existing")),
    ready_to_message_rows: count((row) => row.can_message && (!row.duplicate || row.duplicate_merge || row.action === "merge_existing")),
    duplicate_rows: count((row) => row.duplicate),
    invalid_rows: count((row) => !row.valid),
    needs_country_code_rows: count((row) => row.import_status === "needs_country_code" || row.phone_import_status === "needs_country_code"),
    possible_wrong_country_code_rows: count((row) => row.import_status === "possible_wrong_country_code" || row.phone_import_status === "possible_wrong_country_code"),
    email_only_no_whatsapp_rows: count((row) => row.import_status === "email_only_no_whatsapp"),
    invalid_phone_rows: count((row) => row.phone_import_status === "invalid_phone"),
    not_messageable_rows: count((row) => !row.can_message),
    by_status: byStatus,
    requires_country_code_choice: count((row) => row.import_status === "needs_country_code" || row.phone_import_status === "needs_country_code") > 0,
  };
}

function estimateTokensFromText(text) {
  return Math.max(1, Math.ceil(String(text || "").length / 4));
}

function getCrmModelPricing(db, modelName = "gpt-4o-mini") {
  return (
    ensureCrmArray(db, "model_pricing").find((item) => String(item.model_name).toLowerCase() === String(modelName).toLowerCase() && item.active !== false) ||
    DEFAULT_CRM_MODEL_PRICING[0]
  );
}

function estimateCrmAiCost({ db, model, inputTokens, outputTokens }) {
  const pricing = getCrmModelPricing(db, model);
  const input = Number(inputTokens || 0);
  const output = Number(outputTokens || 0);
  const cost =
    (input / 1000000) * Number(pricing.input_cost_per_1m_tokens || 0) +
    (output / 1000000) * Number(pricing.output_cost_per_1m_tokens || 0);

  return Number(cost.toFixed(6));
}

function getBrandCostSettings(db, brandId) {
  const existing = ensureCrmArray(db, "ai_cost_settings").find((item) => String(item.brand_id) === String(brandId));
  return {
    id: existing?.id || `cost_${brandId || "global"}`,
    brand_id: brandId || null,
    daily_cost_limit: Number(existing?.daily_cost_limit ?? 5),
    weekly_cost_limit: Number(existing?.weekly_cost_limit ?? 25),
    monthly_cost_limit: Number(existing?.monthly_cost_limit ?? 100),
    daily_token_limit: Number(existing?.daily_token_limit ?? 500000),
    monthly_token_limit: Number(existing?.monthly_token_limit ?? 5000000),
    max_cost_per_action: Number(existing?.max_cost_per_action ?? 0.25),
    max_tokens_per_action: Number(existing?.max_tokens_per_action ?? 12000),
    budget_mode: existing?.budget_mode || db.settings?.budget_mode || "approval",
    pause_at_limit: existing?.pause_at_limit !== false,
    notify_at_50: existing?.notify_at_50 !== false,
    notify_at_75: existing?.notify_at_75 !== false,
    notify_at_90: existing?.notify_at_90 !== false,
    notify_at_100: existing?.notify_at_100 !== false,
    agent_limits: existing?.agent_limits || {},
    campaign_limits: existing?.campaign_limits || {},
    lead_limits: existing?.lead_limits || {},
    created_at: existing?.created_at || nowIso(),
    updated_at: existing?.updated_at || nowIso(),
  };
}

function usageWithinDate(usage, startDate, endDate) {
  const ts = new Date(usage.created_at || 0).getTime();
  return ts >= startDate.getTime() && ts <= endDate.getTime();
}

function getCrmUsageTotals(db, brandId, { startDate, endDate } = {}) {
  let logs = ensureCrmArray(db, "ai_usage").filter((item) => !brandId || String(item.brand_id) === String(brandId));

  if (startDate && endDate) {
    logs = logs.filter((item) => usageWithinDate(item, startDate, endDate));
  }

  return logs.reduce(
    (acc, item) => {
      acc.calls += 1;
      acc.input_tokens += Number(item.input_tokens || 0);
      acc.output_tokens += Number(item.output_tokens || 0);
      acc.total_tokens += Number(item.total_tokens || 0);
      acc.estimated_cost += Number(item.estimated_cost || 0);
      if (item.status === "failed") acc.failed_calls += 1;
      return acc;
    },
    { calls: 0, input_tokens: 0, output_tokens: 0, total_tokens: 0, estimated_cost: 0, failed_calls: 0 }
  );
}

function todayRange() {
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  const end = new Date();
  end.setHours(23, 59, 59, 999);
  return { start, end };
}

function monthRange() {
  const start = new Date();
  start.setDate(1);
  start.setHours(0, 0, 0, 0);
  const end = new Date();
  end.setMonth(end.getMonth() + 1, 0);
  end.setHours(23, 59, 59, 999);
  return { start, end };
}

function weekRange() {
  const end = new Date();
  const start = new Date();
  start.setDate(start.getDate() - 6);
  start.setHours(0, 0, 0, 0);
  end.setHours(23, 59, 59, 999);
  return { start, end };
}

function evaluateCrmBudget({ db, brandId, estimatedCost = 0, estimatedTokens = 0, agentName = "", campaignId = "", leadId = "" }) {
  const settings = getBrandCostSettings(db, brandId);
  const today = todayRange();
  const month = monthRange();
  const todayTotals = getCrmUsageTotals(db, brandId, { startDate: today.start, endDate: today.end });
  const monthTotals = getCrmUsageTotals(db, brandId, { startDate: month.start, endDate: month.end });

  const reasons = [];

  if (Number(estimatedCost || 0) > settings.max_cost_per_action) reasons.push("max_cost_per_action_exceeded");
  if (Number(estimatedTokens || 0) > settings.max_tokens_per_action) reasons.push("max_tokens_per_action_exceeded");
  if (todayTotals.estimated_cost + Number(estimatedCost || 0) > settings.daily_cost_limit) reasons.push("daily_cost_limit_reached");
  if (monthTotals.estimated_cost + Number(estimatedCost || 0) > settings.monthly_cost_limit) reasons.push("monthly_cost_limit_reached");
  if (todayTotals.total_tokens + Number(estimatedTokens || 0) > settings.daily_token_limit) reasons.push("daily_token_limit_reached");
  if (monthTotals.total_tokens + Number(estimatedTokens || 0) > settings.monthly_token_limit) reasons.push("monthly_token_limit_reached");

  const agentLimit = agentName ? settings.agent_limits?.[agentName] : null;
  if (agentLimit?.daily_cost_limit) {
    const agentToday = ensureCrmArray(db, "ai_usage")
      .filter((item) => String(item.brand_id) === String(brandId) && item.agent_name === agentName)
      .filter((item) => usageWithinDate(item, today.start, today.end))
      .reduce((sum, item) => sum + Number(item.estimated_cost || 0), 0);
    if (agentToday + Number(estimatedCost || 0) > Number(agentLimit.daily_cost_limit)) reasons.push("agent_daily_cost_limit_reached");
  }

  const campaignLimit = campaignId ? settings.campaign_limits?.[campaignId] : null;
  if (campaignLimit?.total_cost_limit) {
    const campaignTotal = ensureCrmArray(db, "ai_usage")
      .filter((item) => String(item.brand_id) === String(brandId) && String(item.campaign_id) === String(campaignId))
      .reduce((sum, item) => sum + Number(item.estimated_cost || 0), 0);
    if (campaignTotal + Number(estimatedCost || 0) > Number(campaignLimit.total_cost_limit)) reasons.push("campaign_cost_limit_reached");
  }

  const leadLimit = leadId ? settings.lead_limits?.[leadId] : null;
  if (leadLimit?.max_cost) {
    const leadTotal = ensureCrmArray(db, "ai_usage")
      .filter((item) => String(item.brand_id) === String(brandId) && String(item.lead_id) === String(leadId))
      .reduce((sum, item) => sum + Number(item.estimated_cost || 0), 0);
    if (leadTotal + Number(estimatedCost || 0) > Number(leadLimit.max_cost)) reasons.push("lead_cost_limit_reached");
  }

  return {
    allowed: reasons.length === 0 || settings.budget_mode === "warning",
    budget_mode: settings.budget_mode,
    requires_approval: reasons.length > 0 && settings.budget_mode === "approval",
    should_pause: reasons.length > 0 && settings.budget_mode === "strict",
    reasons,
    settings,
    todayTotals,
    monthTotals,
  };
}

async function logCrmAiActionAndUsage({
  db,
  brandId,
  agentName = "CRM AI",
  actionType,
  channel = "crm",
  leadId = null,
  campaignId = null,
  strategyId = null,
  inputText = "",
  outputText = "",
  model = "gpt-4o-mini",
  status = "draft",
  approvalStatus = "needs_approval",
}) {
  const inputTokens = estimateTokensFromText(inputText);
  const outputTokens = estimateTokensFromText(outputText);
  const totalTokens = inputTokens + outputTokens;
  const estimatedCost = estimateCrmAiCost({ db, model, inputTokens, outputTokens });

  const now = nowIso();
  const action = {
    id: uuid(),
    brand_id: brandId || null,
    agent_name: agentName,
    action_type: actionType,
    channel,
    lead_id: leadId,
    campaign_id: campaignId,
    strategy_id: strategyId,
    input_text: inputText,
    output_text: outputText,
    status,
    approval_status: approvalStatus,
    approved_by: null,
    executed_at: status === "executed" || status === "sent" ? now : null,
    created_at: now,
  };

  const usage = {
    id: uuid(),
    brand_id: brandId || null,
    agent_name: agentName,
    action_type: actionType,
    lead_id: leadId,
    campaign_id: campaignId,
    strategy_id: strategyId,
    channel,
    model_used: model,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    total_tokens: totalTokens,
    estimated_cost: estimatedCost,
    status,
    created_at: now,
  };

  db.ai_actions.push(action);
  db.ai_usage.push(usage);

  if (approvalStatus === "needs_approval" || status === "draft") {
    db.approval_queue.push({
      id: uuid(),
      brand_id: brandId || null,
      action_id: action.id,
      agent_name: agentName,
      action_type: actionType,
      channel,
      lead_id: leadId,
      campaign_id: campaignId,
      strategy_id: strategyId,
      draft_content: outputText,
      estimated_cost: estimatedCost,
      total_tokens: totalTokens,
      status: "pending",
      created_at: now,
      updated_at: now,
    });
  }

  return { action, usage };
}

function classifyLeadFromMessage(message = "") {
  const text = String(message || "").toLowerCase();
  let score = 30;
  let exam_type = "";
  let exam_timeline = "";
  let recommended_offer = "Free 15-minute consultation";
  const pain = [];

  if (text.includes("step 1")) exam_type = "Step 1";
  if (text.includes("step 2") || text.includes("ck")) exam_type = "Step 2 CK";
  if (text.includes("uworld")) { score += 15; pain.push("Needs UWorld guidance"); }
  if (text.includes("nbme")) { score += 20; pain.push("NBME score concern"); }
  if (text.includes("live")) { score += 15; pain.push("Interested in live classes"); }
  if (text.includes("exam")) score += 10;
  if (text.includes("fail") || text.includes("stuck") || text.includes("low score")) { score += 15; pain.push("Score is stuck or low"); }

  const months = text.match(/(\d+)\s*(month|months)/i);
  const weeks = text.match(/(\d+)\s*(week|weeks)/i);
  if (months) exam_timeline = `${months[1]} months`;
  if (weeks) exam_timeline = `${weeks[1]} weeks`;

  if (weeks && Number(weeks[1]) <= 10) recommended_offer = "60 Days Marathon";
  else if (months && Number(months[1]) >= 3) recommended_offer = "120 Days Marathon";
  else if (text.includes("record") || text.includes("video")) recommended_offer = "UWorld Video Library";

  return {
    exam_type: exam_type || "Unknown",
    exam_timeline: exam_timeline || "Unknown",
    current_resources: [
      text.includes("uworld") ? "UWorld" : null,
      text.includes("first aid") ? "First Aid" : null,
      text.includes("nbme") ? "NBME" : null,
      text.includes("pathoma") ? "Pathoma" : null,
      text.includes("sketchy") ? "Sketchy" : null,
    ].filter(Boolean).join(" + ") || "Unknown",
    pain_points: pain.join(", ") || "Needs study structure guidance",
    interest_level: score >= 75 ? "high" : score >= 50 ? "medium" : "low",
    lead_score: Math.max(0, Math.min(100, score)),
    recommended_offer,
  };
}

function buildMockLeadReply(analysis) {
  return `That makes sense, Doctor. Based on what you shared, your main issue seems to be ${analysis.pain_points}. Are you currently following a fixed daily roadmap, or are you selecting topics randomly?`;
}

function buildMockCommunityPost({ platform, postType, topic, audience, cta, language }) {
  const isArabic = String(language || "").toLowerCase() === "arabic";
  const isUrdu = String(language || "").toLowerCase().includes("urdu");

  if (isArabic) {
    return `نقاش USMLE لليوم:\n\n${topic || "كثير من الطلاب يدرسون UWorld ولكن لا يرون تحسنًا واضحًا في NBME."}\n\nما السبب الأهم برأيك؟\nA) ضعف في الأساسيات\nB) مراجعة غير صحيحة للأخطاء\nC) جدول عشوائي\nD) عدد أسئلة غير كافٍ\n\n${cta || "اكتب إجابتك، وسنشارك طريقة المراجعة الصحيحة بعد النقاش."}`;
  }

  if (isUrdu) {
    return `USMLE Discussion:\n\n${topic || "Bohat se students UWorld karte hain lekin NBME score improve nahi hota."}\n\nAap ke khayal mein sab se bari wajah kya hai?\nA) First Aid weak\nB) Incorrects review theek nahi\nC) Random schedule\nD) Questions kam\n\n${cta || "Apna answer comment karein, phir hum strategy share karenge."}`;
  }

  return `USMLE Discussion of the Day:\n\n${topic || "Many students complete UWorld but still do not see NBME improvement."}\n\nWhat do you think is the biggest reason?\n\nA) Weak First Aid base\nB) Poor incorrect review\nC) Random study schedule\nD) Not enough questions\n\n${cta || "Comment your answer and we’ll share the correct strategy after discussion."}`;
}


