// -----------------------------------------------------------------------------
// Universal Social Integrations: Email, WhatsApp, Meta, Reddit, LinkedIn,
// YouTube, TikTok, X/Twitter, Discord, custom webhooks.
// -----------------------------------------------------------------------------

const SOCIAL_PLATFORM_CONFIG = {
  telegram: {
    label: "Telegram",
    env: ["TELEGRAM_BOT_TOKEN"],
    live: true,
    inbound: true,
    outbound: true,
  },
  email: {
    label: "Email",
    env: ["RESEND_API_KEY or SENDGRID_API_KEY or SMTP_*"],
    live: true,
    inbound: true,
    outbound: true,
  },
  whatsapp: {
    label: "WhatsApp Cloud API",
    env: ["WHATSAPP_ACCESS_TOKEN", "WHATSAPP_PHONE_NUMBER_ID", "WHATSAPP_WEBHOOK_VERIFY_TOKEN"],
    live: true,
    inbound: true,
    outbound: true,
  },
  facebook: {
    label: "Facebook Page",
    env: ["META_PAGE_ACCESS_TOKEN", "FACEBOOK_PAGE_ID", "META_VERIFY_TOKEN"],
    live: true,
    inbound: true,
    outbound: true,
  },
  instagram: {
    label: "Instagram Professional",
    env: ["INSTAGRAM_PAGE_ACCESS_TOKEN", "INSTAGRAM_BUSINESS_ACCOUNT_ID", "META_VERIFY_TOKEN"],
    live: true,
    inbound: true,
    outbound: true,
  },
  reddit: {
    label: "Reddit",
    env: ["REDDIT_CLIENT_ID", "REDDIT_CLIENT_SECRET", "REDDIT_REFRESH_TOKEN"],
    live: false,
    inbound: true,
    outbound: false,
  },
  linkedin: {
    label: "LinkedIn",
    env: ["LINKEDIN_CLIENT_ID", "LINKEDIN_CLIENT_SECRET", "LINKEDIN_ACCESS_TOKEN"],
    live: false,
    inbound: true,
    outbound: false,
  },
  youtube: {
    label: "YouTube",
    env: ["YOUTUBE_API_KEY or GOOGLE_CLIENT_ID/GOOGLE_CLIENT_SECRET"],
    live: false,
    inbound: true,
    outbound: false,
  },
  tiktok: {
    label: "TikTok",
    env: ["TIKTOK_CLIENT_KEY", "TIKTOK_CLIENT_SECRET", "TIKTOK_ACCESS_TOKEN"],
    live: false,
    inbound: true,
    outbound: false,
  },
  twitter: {
    label: "X / Twitter",
    env: ["TWITTER_BEARER_TOKEN", "TWITTER_API_KEY", "TWITTER_API_SECRET"],
    live: false,
    inbound: true,
    outbound: false,
  },
  x: {
    label: "X / Twitter",
    env: ["TWITTER_BEARER_TOKEN", "TWITTER_API_KEY", "TWITTER_API_SECRET"],
    live: false,
    inbound: true,
    outbound: false,
  },
  discord: {
    label: "Discord",
    env: ["DISCORD_BOT_TOKEN or DISCORD_WEBHOOK_URL"],
    live: true,
    inbound: true,
    outbound: true,
  },
  other: {
    label: "Custom Platform",
    env: [],
    live: false,
    inbound: true,
    outbound: false,
  },
};

function normalizeSocialPlatform(platform = "other") {
  const clean = String(platform || "other").trim().toLowerCase();
  if (clean === "x") return "twitter";
  return SOCIAL_PLATFORM_CONFIG[clean] ? clean : "other";
}

function getPlatformConfig(platform) {
  return SOCIAL_PLATFORM_CONFIG[normalizeSocialPlatform(platform)] || SOCIAL_PLATFORM_CONFIG.other;
}

function getIntegrationCredential(integration = {}, key, envKey = null) {
  const value = integration?.[key] || integration?.credentials?.[key] || "";
  const envValue = envKey ? process.env[envKey] : "";
  const clean = String(value || envValue || "").trim();
  if (!clean || clean.includes("***")) return String(envValue || "").trim();
  return clean;
}

function getBackendPublicUrl() {
  return String(process.env.BACKEND_PUBLIC_URL || process.env.RENDER_EXTERNAL_URL || "").replace(/\/$/, "");
}

function getIntegrationByPlatform(db, platform) {
  const clean = normalizeSocialPlatform(platform);
  return ensureCrmArray(db, "integrations").find((item) => normalizeSocialPlatform(item.platform) === clean) || null;
}

function getStableLeadId(lead = {}) {
  return String(lead?.id || lead?._id || lead?.lead_id || lead?.uuid || "").trim();
}

function getLeadByAnyId(db, id) {
  const cleanId = String(id || "").trim();
  if (!cleanId) return null;

  const cleanLower = cleanId.toLowerCase();
  const cleanDigits = cleanId.replace(/\D/g, "");

  return ensureCrmArray(db, "leads").find((lead) => {
    const idFields = [lead.id, lead._id, lead.lead_id, lead.uuid, lead.contact_id, lead.conversation_id]
      .map((x) => String(x || "").trim())
      .filter(Boolean);
    if (idFields.includes(cleanId)) return true;

    const emailFields = [lead.email, lead.student_email, lead.customer_email]
      .map((x) => String(x || "").trim().toLowerCase())
      .filter(Boolean);
    if (cleanLower && emailFields.includes(cleanLower)) return true;

    if (cleanDigits) {
      const phoneFields = [
        lead.phone,
        lead.whatsapp,
        lead.whatsapp_phone,
        lead.whatsapp_number,
        lead.mobile,
        lead.contact_number,
        lead.phone_number,
        lead.wa_id,
        lead.platform_contact_id,
        lead.contact,
      ]
        .map((x) => String(x || "").replace(/\D/g, ""))
        .filter(Boolean);

      if (phoneFields.some((phone) => phone === cleanDigits || phone.endsWith(cleanDigits) || cleanDigits.endsWith(phone))) return true;
    }

    return false;
  }) || null;
}

function normalizeLeadDirection(value, fallback = "inbound") {
  const clean = String(value || fallback || "inbound").trim().toLowerCase();
  if (["outbound", "agent", "agent_outreach", "company", "business"].includes(clean)) return "outbound";
  if (["inbound", "client", "client_reached_out", "student", "lead", "user"].includes(clean)) return "inbound";
  return fallback || "inbound";
}

function normalizeLeadSourcePlatform(lead = {}, fallback = "other") {
  return normalizeSocialPlatform(
    lead.source_platform ||
    lead.platform ||
    lead.channel ||
    lead.source ||
    lead.source_channel ||
    fallback
  );
}

function normalizeLeadForResponse(lead = {}) {
  const id = getStableLeadId(lead) || uuid();
  const platform = normalizeLeadSourcePlatform(lead);
  const direction = normalizeLeadDirection(
    lead.conversation_direction ||
      lead.direction ||
      lead.lead_direction ||
      lead.origin ||
      (lead.agent_initiated ? "outbound" : "inbound"),
    lead.agent_initiated ? "outbound" : "inbound"
  );

  return {
    ...lead,
    id,
    lead_id: lead.lead_id || id,
    source_platform: platform,
    platform,
    source_channel: lead.source_channel || "social_integration",
    conversation_direction: direction,
    client_reached_out: direction === "inbound" ? true : Boolean(lead.client_reached_out),
    agent_initiated: direction === "outbound" ? true : Boolean(lead.agent_initiated),
    status: lead.status || lead.lead_status || "new",
    lead_status: lead.lead_status || lead.status || "new",
    last_message: lead.last_message || lead.last_message_text || lead.source_text || "",
    last_message_at: lead.last_message_at || lead.last_inbound_at || lead.updated_at || lead.created_at || null,
    assigned_agent: lead.assigned_agent || lead.assigned_agent_id || null,
  };
}

function ensureLeadIdentityFields(lead = {}) {
  const normalized = normalizeLeadForResponse(lead);
  Object.assign(lead, normalized);
  return lead;
}

function getPlatformContactIdForLead(platform, payload = {}) {
  const cleanPlatform = normalizeSocialPlatform(platform);
  return (
    payload.platform_contact_id ||
    payload[`${cleanPlatform}_id`] ||
    payload[`${cleanPlatform}_chat_id`] ||
    payload.telegram_chat_id ||
    payload.wa_id ||
    payload.whatsapp_phone ||
    payload.phone ||
    payload.email ||
    payload.username ||
    ""
  );
}

function detectMetaPayloadPlatform(payload = {}) {
  const object = String(payload?.object || "").toLowerCase();

  if (object.includes("instagram")) return "instagram";
  if (object.includes("page")) return "facebook";

  const entry = payload?.entry?.[0] || {};
  const messaging = entry?.messaging?.[0] || {};
  const change = entry?.changes?.[0] || {};
  const field = String(change?.field || "").toLowerCase();

  if (
    field.includes("instagram") ||
    ["comments", "live_comments", "messages", "messaging_postbacks", "message_reactions", "messaging_seen"].includes(field) &&
      (change?.value?.from?.username || change?.value?.media || change?.value?.comment_id)
  ) {
    return "instagram";
  }

  if (messaging?.recipient?.id || messaging?.sender?.id || field) return "facebook";

  return "facebook";
}

function extractMetaText({ platform, payload = {} }) {
  const entry = payload.entry?.[0] || {};
  const messaging = entry.messaging?.[0] || {};
  const change = entry.changes?.[0] || {};
  const value = change.value || {};

  const messageText =
    messaging.message?.text ||
    messaging.postback?.title ||
    messaging.postback?.payload ||
    value.message ||
    value.text ||
    value.comment ||
    value.caption ||
    payload.text ||
    payload.message ||
    "";

  const senderId =
    messaging.sender?.id ||
    value.from?.id ||
    value.sender?.id ||
    payload.sender_id ||
    payload.user_id ||
    payload.from_id ||
    "";

  const recipientId =
    messaging.recipient?.id ||
    value.recipient?.id ||
    entry.id ||
    payload.recipient_id ||
    "";

  const username =
    value.from?.username ||
    value.sender?.username ||
    payload.username ||
    payload.handle ||
    "";

  const displayName =
    value.from?.name ||
    value.sender?.name ||
    payload.name ||
    username ||
    senderId ||
    `${getPlatformConfig(platform).label} Lead`;

  const platformMessageId =
    messaging.message?.mid ||
    messaging.postback?.mid ||
    value.mid ||
    value.message_id ||
    value.comment_id ||
    value.id ||
    payload.message_id ||
    "";

  return { messageText, senderId, recipientId, username, displayName, platformMessageId, field: change.field || "" };
}

function getMetaTokenForPlatform(platform, integration = {}) {
  const cleanPlatform = normalizeSocialPlatform(platform);
  if (cleanPlatform === "instagram") {
    return (
      getIntegrationCredential(integration, "api_key", "INSTAGRAM_PAGE_ACCESS_TOKEN") ||
      process.env.INSTAGRAM_PAGE_ACCESS_TOKEN ||
      process.env.META_PAGE_ACCESS_TOKEN ||
      ""
    );
  }
  return (
    getIntegrationCredential(integration, "api_key", "META_PAGE_ACCESS_TOKEN") ||
    process.env.META_PAGE_ACCESS_TOKEN ||
    process.env.FACEBOOK_PAGE_ACCESS_TOKEN ||
    ""
  );
}

function getMetaAccountIdForPlatform(platform, integration = {}) {
  const cleanPlatform = normalizeSocialPlatform(platform);
  if (cleanPlatform === "instagram") {
    return integration.account_id || process.env.INSTAGRAM_BUSINESS_ACCOUNT_ID || process.env.INSTAGRAM_ACCOUNT_ID || "me";
  }
  return integration.account_id || process.env.FACEBOOK_PAGE_ID || "me";
}


// v117: Inbox unread/read-state must be backend-owned.
// Red dots should count only fresh inbound student messages after the last admin/AI outbound/read.
function ngReadStateMessageTimeMs(message = {}) {
  const value = message.created_at || message.received_at || message.sent_at || message.delivered_at || message.timestamp || message.updated_at || message.time || null;
  const ms = value ? new Date(value).getTime() : 0;
  return Number.isFinite(ms) ? ms : 0;
}

function ngReadStatePhoneDigits(value = "") {
  const digits = String(value || "").replace(/\D/g, "");
  return digits && digits.length >= 7 ? digits : "";
}

function ngReadStateLeadPhones(lead = {}) {
  return [lead.phone, lead.whatsapp, lead.whatsapp_phone, lead.phone_number, lead.mobile, lead.contact, lead.wa_id, lead.platform_contact_id]
    .map(ngReadStatePhoneDigits)
    .filter(Boolean);
}

function ngReadStateLeadEmails(lead = {}) {
  return [lead.email, lead.student_email, lead.customer_email, lead.contact_email]
    .map(normalizeEmail)
    .filter(Boolean);
}

function ngReadStateMessageBelongsToLead(message = {}, lead = {}) {
  if (!lead) return false;
  const leadIds = [lead.id, lead._id, lead.lead_id, lead.uuid].map((x) => String(x || "")).filter(Boolean);
  const messageLeadIds = [message.lead_id, message.leadId, message.lead, message.contact_id, message.contactId, message.crm_lead_id, message.conversation_id, message.thread_lead_id]
    .map((x) => String(x || ""))
    .filter(Boolean);
  if (leadIds.length && messageLeadIds.some((id) => leadIds.includes(id))) return true;

  const leadPhones = ngReadStateLeadPhones(lead);
  const messagePhones = [message.phone, message.whatsapp, message.whatsapp_phone, message.phone_number, message.mobile, message.to, message.from, message.recipient, message.sender, message.wa_id, message.customer_phone, message.lead_phone, message.contact_phone]
    .map(ngReadStatePhoneDigits)
    .filter(Boolean);
  if (leadPhones.length && messagePhones.some((phone) => leadPhones.some((leadPhone) => phone === leadPhone || phone.endsWith(leadPhone) || leadPhone.endsWith(phone)))) return true;

  const leadEmails = ngReadStateLeadEmails(lead);
  const messageEmails = [message.email, message.to, message.from, message.recipient, message.sender, message.customer_email, message.lead_email, message.contact_email]
    .map(normalizeEmail)
    .filter(Boolean);
  return Boolean(leadEmails.length && messageEmails.some((email) => leadEmails.includes(email)));
}

function ngReadStateIsInbound(message = {}) {
  const dir = String(message.direction || message.message_direction || message.type || "").toLowerCase();
  return ["inbound", "received", "incoming", "lead", "student"].includes(dir) || message.inbound === true || message.is_inbound === true;
}

function ngReadStateIsOutbound(message = {}) {
  const dir = String(message.direction || message.message_direction || message.type || "").toLowerCase();
  if (["outbound", "sent", "outgoing", "agent", "assistant"].includes(dir)) return true;
  if (message.outbound === true || message.is_outbound === true || message.agent_initiated === true) return true;
  if (message.to && (message.sent_at || message.agent_id || message.sender_role === "assistant" || message.sender_role === "admin")) return true;
  return false;
}

function ngReadStateMaxTime(values = []) {
  return Math.max(0, ...values.map((value) => {
    const ms = value ? new Date(value).getTime() : 0;
    return Number.isFinite(ms) ? ms : 0;
  }));
}

function ngInboxUnreadCountForLead({ lead = {}, messages = [] } = {}) {
  const safeMessages = safeArray(messages);
  const lastAdminReadMs = ngReadStateMaxTime([
    lead.last_admin_read_at,
    lead.inbox_last_read_at,
    lead.last_read_at,
    lead.conversation_read_at,
    lead.admin_read_at,
  ]);
  const lastOutboundMs = safeMessages.reduce((max, message) => {
    if (!ngReadStateIsOutbound(message)) return max;
    const status = String(message.status || message.provider_status || "").toLowerCase();
    if (["failed", "error", "duplicate_blocked", "skipped", "not_sent"].includes(status)) return max;
    return Math.max(max, ngReadStateMessageTimeMs(message));
  }, 0);
  const cutoffMs = Math.max(lastAdminReadMs, lastOutboundMs);
  return safeMessages.filter((message) => {
    if (!ngReadStateIsInbound(message)) return false;
    if (!ngMessageText(message)) return false;
    if (message.admin_read_at || message.read_by_admin_at || message.inbox_read_at) return false;
    const t = ngReadStateMessageTimeMs(message);
    return t > cutoffMs + 250;
  }).length;
}

function ngMarkConversationRead(db = {}, leadOrId = null, options = {}) {
  const lead = typeof leadOrId === "object" && leadOrId ? leadOrId : getLeadByAnyId(db, leadOrId);
  if (!lead) return { changed: false, reason: "lead_not_found" };
  const now = nowIso();
  let changed = false;
  const collections = ["message_logs", "crm_message_logs", "inbound_messages", "conversations"];
  for (const collection of collections) {
    for (const message of ensureCrmArray(db, collection)) {
      if (!ngReadStateIsInbound(message)) continue;
      if (!ngReadStateMessageBelongsToLead(message, lead)) continue;
      if (!message.admin_read_at) { message.admin_read_at = now; changed = true; }
      if (!message.inbox_read_at) { message.inbox_read_at = now; changed = true; }
      if (!message.read_by_admin_at) { message.read_by_admin_at = now; changed = true; }
      message.read_by = options.actorId || options.actor_id || message.read_by || "admin";
      message.read_reason = options.reason || message.read_reason || "conversation_mark_read";
      message.updated_at = now;
    }
  }
  lead.unread_count = 0;
  lead.inbox_unread_count = 0;
  lead.last_admin_read_at = now;
  lead.inbox_last_read_at = now;
  lead.last_read_at = now;
  lead.updated_at = now;
  changed = true;
  return { changed, lead_id: lead.id || lead.lead_id || null, read_at: now };
}

function ngMarkConversationHandledByOutbound(db = {}, leadOrId = null, options = {}) {
  const result = ngMarkConversationRead(db, leadOrId, { ...options, reason: options.reason || "outbound_message_sent" });
  const lead = typeof leadOrId === "object" && leadOrId ? leadOrId : getLeadByAnyId(db, leadOrId);
  if (lead) {
    const now = result.read_at || nowIso();
    lead.last_handled_at = now;
    lead.needs_reply = false;
    if (String(lead.status || "").toLowerCase() === "needs_reply") lead.status = lead.lead_status || "replied";
    if (String(lead.lead_status || "").toLowerCase() === "needs_reply") lead.lead_status = lead.status || "replied";
    lead.updated_at = now;
  }
  return result;
}

const NEXTGEN_QUICK_ACTION_TEMPLATE_KEYS = {
  first_message: ["meta_ad_first_message", "meta_first_message", "first_message_intro", "greeting_exam_type_question"],
  reminder: ["five_min_live_session_reminder", "five_minute_reminder", "live_session_1pm_reminder"],
  session_link: ["live_session_link_now", "live_session_1pm_reminder", "live_session_invite_broadcast"],
  recording: ["recording_followup_after_session", "post_live_notes_recording_followup"],
  testimonial: ["proof_testimonial_message", "proof_testimonial"],
  uworld_demo: ["uworld_video_library_soft_pitch", "demo_lms_activation_invite", "two_day_lms_demo_access"],
  community: ["community_fallback_invite"],
  mentor: ["mentor_call_offer", "mentor_booking", "mentor_call_followup"],
};

function ngFindTemplateForQuickAction(db = {}, action = "") {
  const keys = (NEXTGEN_QUICK_ACTION_TEMPLATE_KEYS[action] || [action]).map(normalizeTemplateLookupKey);
  const templates = [...ensureCrmArray(db, "message_templates"), ...ensureCrmArray(db, "templates")];
  return templates.find((template) => {
    if (template.active === false || template.is_active === false || template.status === "archived") return false;
    const ids = [template.id, template.template_id, template.key, template.template_key, template.slug, template.name, template.title, template.template_name, template.meta_template_name, template.whatsapp_template_name, template.provider_template_name]
      .map(normalizeTemplateLookupKey)
      .filter(Boolean);
    return keys.some((key) => ids.includes(key));
  }) || null;
}

function ngSalesAssetValue(assets = {}, key = "") {
  return String(assets?.[key] || "").trim();
}

function ngBuildQuickActionPayload(db = {}, lead = {}, action = "", body = {}) {
  const cleanAction = normalizeTemplateLookupKey(action || body.quick_action || body.action || "");
  const assets = typeof ngAylaGetSalesAssets === "function" ? ngAylaGetSalesAssets(db) : {};
  const liveLink = getNextGenConfiguredLiveSessionLink() || ngSalesAssetValue(assets, "liveSessionLink") || lead.live_session_link || lead.session_link || "";
  const sessionTime = body.session_time || ngSalesAssetValue(assets, "sessionTime") || lead.session_time || "1 PM EST";
  const recordingLink = body.recording_link || ngSalesAssetValue(assets, "recordingLink") || lead.recording_link || lead.recording_url || "";
  const demoLink = body.demo_link || ngSalesAssetValue(assets, "uworldLink") || lead.demo_link || "https://live.nextgenusmlelms.com";
  const youtubeLink = body.youtube_link || ngSalesAssetValue(assets, "youtubeLink") || lead.youtube_link || "";
  const communityLink = body.community_link || lead.community_link || lead.telegram_link || "";
  const mentorLink = body.mentor_booking_link || lead.mentor_booking_link || "";
  const name = getLeadVariableValue("student_name", lead, {}, {}) || "Doctor";
  const examType = getLeadVariableValue("exam_type", lead, {}, {}) || "USMLE Step 1";

  const messages = {
    first_message: `Hi ${name}, this is NextGen USMLE. You reached out regarding ${examType} preparation. We have a live guidance session at ${sessionTime}, where you can see Dr. Ahmad's teaching style and understand how the program works.`,
    reminder: `Doctor, quick reminder — our live guidance session starts at ${sessionTime}. Please be ready. ${liveLink ? `Here is the joining link: ${liveLink}` : "I will share the joining link shortly."}\n\nAfter the session, we can arrange a Google Meet with our mentor for proper guidance based on your timeline and weak areas.`,
    session_link: `Doctor, here is today's live session link:\n${liveLink || "Live session link is not configured yet."}\n\nEven if you join for just 5–10 minutes, you will understand Dr. Ahmad's teaching style and how the program works. After that, let's arrange a Google Meet with our mentor so you get personal guidance.`,
    recording: `Doctor, here is a recent session recording so you can see the teaching style:\n${recordingLink || "Recording link is not configured yet."}\n\nAfter you watch even a few minutes, we can arrange a Google Meet with our mentor and guide you based on your exam timeline and weak areas.`,
    testimonial: `Doctor, you can also review NextGen teaching/proof here:${youtubeLink ? `\n${youtubeLink}` : "\nYouTube/proof link is not configured yet."}\n\nThe main idea is structured guidance, accountability, and support instead of preparing alone.`,
    uworld_demo: `Doctor, our LMS is a complete USMLE learning ecosystem in one place: roadmap, live sessions, recordings, UWorld Video Library, notes, tasks, accountability assessments, progress tracking, leaderboard encouragement, Community Q&A, and Study Partner support.\n\nYou can check the LMS/UWorld library here:\n${demoLink}`,
    community: `Doctor, I can also add you to our free ${examType} community where we share guidance, session updates, and study direction.${communityLink ? `\n${communityLink}` : ""}`,
    mentor: `Doctor, I can arrange a Google Meet with our mentor. Before booking, have you attended any Dr. Ahmad / NextGen live session before? If yes, when did you attend and how did you find the teaching style?`,
  };

  const template = ngFindTemplateForQuickAction(db, cleanAction);
  const templateKey = (NEXTGEN_QUICK_ACTION_TEMPLATE_KEYS[cleanAction] || [cleanAction])[0] || cleanAction;
  return {
    action: cleanAction,
    text: body.text || body.message || messages[cleanAction] || messages.first_message,
    template,
    templateId: template?.id || template?.template_id || template?.key || template?.template_key || templateKey,
    stage: {
      first_message: "first_message_sent",
      reminder: "interested_live_session",
      session_link: "interested_live_session",
      recording: "recording_sent",
      community: "sent_to_community",
      mentor: "mentor_call_scheduled",
    }[cleanAction] || null,
    variables: {
      lead,
      lead_name: name,
      student_name: name,
      doctor_name: name,
      exam_type: examType,
      exam_track: examType,
      session_time: sessionTime,
      live_session_link: liveLink,
      session_link: liveLink,
      recording_link: recordingLink,
      demo_link: demoLink,
      lms_link: demoLink,
      youtube_link: youtubeLink,
      proof_link: youtubeLink,
      community_link: communityLink,
      mentor_booking_link: mentorLink,
    },
    links: { live_session_link: liveLink, recording_link: recordingLink, demo_link: demoLink, youtube_link: youtubeLink, community_link: communityLink, mentor_booking_link: mentorLink },
  };
}

function buildConversationInbox(db) {
  const leads = ensureCrmArray(db, "leads").map(normalizeLeadForResponse);

  function inboxPhoneDigits(value = "") {
    const d = String(value || "").replace(/\D/g, "");
    if (!d || d.length < 10) return "";
    return d.slice(-10);
  }

  function inboxContactKey(lead = {}) {
    const phone = inboxPhoneDigits(
      lead.whatsapp ||
      lead.whatsapp_phone ||
      lead.phone ||
      lead.mobile ||
      lead.contact ||
      lead.platform_contact_id ||
      lead.wa_id ||
      ""
    );
    if (phone) return `phone:${phone}`;

    const email = normalizeEmail(lead.email || lead.student_email || lead.customer_email || "");
    if (email) return `email:${email}`;

    const platformContact = normalizeCrmString(
      lead.platform_contact_id ||
      lead.chat_id ||
      lead.telegram_chat_id ||
      lead.instagram_id ||
      lead.facebook_id ||
      ""
    ).toLowerCase();
    if (platformContact) return `platform:${platformContact}`;

    return `lead:${getStableLeadId(lead)}`;
  }

  function genericInboxName(value = "") {
    const text = String(value || "").trim().toLowerCase();
    if (!text) return true;
    if (/^\+?\d{7,}$/.test(text.replace(/\s+/g, ""))) return true;
    return [
      "unknown lead",
      "website visitor",
      "visitor",
      "lead",
      "doctor",
      "crm",
      "nextgen",
      "next gen scholars",
      "nextgen scholars",
      "nextgen usmle",
    ].some((item) => text === item || text.includes(item));
  }

  function stageRank(status = "") {
    const key = String(status || "").toLowerCase().replace(/[^a-z0-9]+/g, "_");
    const map = {
      needs_reply: 90,
      interested_live_session: 80,
      mentor_call_scheduled: 78,
      payment_pending: 76,
      first_message_sent: 65,
      replied: 60,
      new_lead: 50,
      new: 50,
      no_reply: 40,
      not_interested: 5,
      paid_enrolled: 1,
      paid: 1,
      enrolled: 1,
    };
    return map[key] || 10;
  }

  const rows = leads.map((lead) => {
    const leadId = getStableLeadId(lead);
    const leadMessages = typeof ngLeadConversationMessages === "function"
      ? ngLeadConversationMessages(db, leadId)
      : ensureCrmArray(db, "conversations")
        .filter((message) => String(message.lead_id || "") === String(leadId))
        .sort((a, b) => String(a.created_at || a.timestamp || "").localeCompare(String(b.created_at || b.timestamp || "")));

    const newestFirst = [...leadMessages].sort((a, b) => {
      const at = new Date(a.created_at || a.received_at || a.sent_at || a.timestamp || a.updated_at || 0).getTime();
      const bt = new Date(b.created_at || b.received_at || b.sent_at || b.timestamp || b.updated_at || 0).getTime();
      return bt - at;
    });

    const lastMessage = newestFirst[0] || null;
    const unreadCount = ngInboxUnreadCountForLead({ lead, messages: leadMessages });

    return {
      conversation_id: lead.conversation_id || leadId,
      lead_id: leadId,
      lead_name: lead.name || lead.display_name || "Unknown Lead",
      contact: lead.email || lead.phone || lead.whatsapp || lead.whatsapp_phone || lead.platform_contact_id || "",
      platform: normalizeLeadSourcePlatform(lead),
      source_platform: normalizeLeadSourcePlatform(lead),
      platform_icon: normalizeLeadSourcePlatform(lead),
      messages: leadMessages,
      message_count: leadMessages.length,
      last_message: lastMessage?.message_text || lastMessage?.text || lastMessage?.body || lastMessage?.message || lead.last_message || "",
      last_message_at: lastMessage?.created_at || lastMessage?.received_at || lastMessage?.sent_at || lastMessage?.timestamp || lead.last_message_at || lead.updated_at || lead.created_at || null,
      unread_count: unreadCount,
      status: lead.status || lead.lead_status || "new",
      lead_status: lead.lead_status || lead.status || "new",
      assigned_agent: lead.assigned_agent_name || lead.assigned_agent || lead.assigned_agent_id || "Unassigned",
      direction: lead.conversation_direction || (lastMessage?.direction || "inbound"),
      client_reached_out: lead.client_reached_out !== false,
      agent_initiated: Boolean(lead.agent_initiated),
      ai_mode: lead.ai_mode || lead.automation_mode || "auto",
      duplicate_contact_key: inboxContactKey(lead),
    };
  });

  const merged = new Map();

  for (const row of rows) {
    const key = row.duplicate_contact_key || `lead:${row.lead_id}`;
    const existing = merged.get(key);
    if (!existing) {
      merged.set(key, { ...row, duplicate_lead_ids: [row.lead_id].filter(Boolean), duplicate_count: 1 });
      continue;
    }

    const rowTime = new Date(row.last_message_at || 0).getTime();
    const existingTime = new Date(existing.last_message_at || 0).getTime();
    const newest = rowTime >= existingTime ? row : existing;
    const older = rowTime >= existingTime ? existing : row;
    const betterName = !genericInboxName(row.lead_name) && (genericInboxName(existing.lead_name) || rowTime >= existingTime)
      ? row.lead_name
      : existing.lead_name;
    const betterStatus = stageRank(row.status) > stageRank(existing.status) ? row.status : existing.status;
    const betterLeadStatus = stageRank(row.lead_status) > stageRank(existing.lead_status) ? row.lead_status : existing.lead_status;
    const preferredPlatform = [row.platform, existing.platform].includes("whatsapp") ? "whatsapp" : (newest.platform || existing.platform || row.platform);
    const allMessages = [...(existing.messages || []), ...(row.messages || [])]
      .filter((message, index, arr) => {
        const id = String(message.id || message.message_id || message.provider_message_id || "");
        if (!id) return true;
        return arr.findIndex((candidate) => String(candidate.id || candidate.message_id || candidate.provider_message_id || "") === id) === index;
      })
      .sort((a, b) => String(a.created_at || a.received_at || a.sent_at || a.timestamp || "").localeCompare(String(b.created_at || b.received_at || b.sent_at || b.timestamp || "")));

    merged.set(key, {
      ...older,
      ...newest,
      conversation_id: newest.conversation_id || existing.conversation_id || row.conversation_id,
      lead_id: existing.lead_id || row.lead_id,
      lead_name: betterName || newest.lead_name || existing.lead_name,
      contact: existing.contact || row.contact,
      platform: preferredPlatform,
      source_platform: preferredPlatform,
      platform_icon: preferredPlatform,
      messages: allMessages,
      message_count: allMessages.length,
      unread_count: ngInboxUnreadCountForLead({ lead: newest, messages: allMessages }),
      status: betterStatus,
      lead_status: betterLeadStatus,
      ai_mode: newest.ai_mode || existing.ai_mode || row.ai_mode || "auto",
      duplicate_contact_key: key,
      duplicate_count: Number(existing.duplicate_count || 1) + 1,
      duplicate_lead_ids: Array.from(new Set([...(existing.duplicate_lead_ids || []), existing.lead_id, row.lead_id].filter(Boolean))),
    });
  }

  return Array.from(merged.values()).sort((a, b) => String(b.last_message_at || "").localeCompare(String(a.last_message_at || "")));
}

function parseInboundSocialPayload({ platform, payload = {}, integration = null }) {
  let cleanPlatform = normalizeSocialPlatform(platform);
  const body = payload || {};

  if (cleanPlatform === "facebook" && (String(body.object || "").toLowerCase().includes("instagram"))) {
    cleanPlatform = "instagram";
  }

  let text = "";
  let externalUserId = "";
  let username = "";
  let displayName = "";
  let chatId = "";
  let email = "";
  let phone = "";
  let platformMessageId = "";
  let recipientId = "";

  if (cleanPlatform === "telegram") {
    const message = body.message || body.edited_message || body.channel_post || {};
    const from = message.from || {};
    const chat = message.chat || {};
    text = message.text || message.caption || body.text || "";
    externalUserId = String(from.id || chat.id || body.user_id || "");
    username = from.username || body.username || "";
    displayName = [from.first_name, from.last_name].filter(Boolean).join(" ") || username || chat.title || externalUserId;
    chatId = String(chat.id || externalUserId || "");
    platformMessageId = message.message_id || body.update_id || "";
  } else if (cleanPlatform === "whatsapp") {
    const value = body.entry?.[0]?.changes?.[0]?.value || body.value || body;
    const message = value.messages?.[0] || body.message || {};
    const contact = value.contacts?.[0] || {};
    text =
      message.text?.body ||
      message.button?.text ||
      message.interactive?.button_reply?.title ||
      message.interactive?.list_reply?.title ||
      body.text ||
      "";
    externalUserId = message.from || contact.wa_id || body.from || body.phone || "";
    phone = externalUserId;
    displayName = contact.profile?.name || body.name || externalUserId;
    chatId = externalUserId;
    platformMessageId = message.id || body.message_id || "";
  } else if (cleanPlatform === "facebook" || cleanPlatform === "instagram") {
    const meta = extractMetaText({ platform: cleanPlatform, payload: body });
    text = meta.messageText;
    externalUserId = meta.senderId;
    username = meta.username;
    displayName = meta.displayName;
    chatId = meta.senderId;
    recipientId = meta.recipientId;
    platformMessageId = meta.platformMessageId;
  } else if (cleanPlatform === "email") {
    text = body.text || body.html || body.subject || body.message || "";
    email = body.from || body.email || body.sender || body.reply_to || "";
    externalUserId = email;
    displayName = body.name || body.from_name || email;
    chatId = body.message_id || body.thread_id || email;
    platformMessageId = body.message_id || "";
  } else if (cleanPlatform === "discord") {
    text = body.content || body.text || "";
    externalUserId = body.author?.id || body.user_id || "";
    username = body.author?.username || body.username || "";
    displayName = body.author?.global_name || username || externalUserId;
    chatId = body.channel_id || "";
    platformMessageId = body.id || body.message_id || "";
  } else {
    text = body.text || body.message || body.comment || body.body || body.content || "";
    externalUserId = body.user_id || body.id || body.author_id || body.sender_id || body.profile_id || body.username || body.email || "";
    username = body.username || body.handle || body.author || "";
    email = body.email || "";
    phone = body.phone || body.whatsapp || "";
    displayName = body.name || username || email || phone || externalUserId || `${getPlatformConfig(cleanPlatform).label} Lead`;
    chatId = body.chat_id || body.thread_id || body.conversation_id || "";
    platformMessageId = body.message_id || body.id || "";
  }

  const platformContactId = String(getPlatformContactIdForLead(cleanPlatform, {
    platform_contact_id: externalUserId || chatId || email || phone,
    [`${cleanPlatform}_id`]: externalUserId,
    [`${cleanPlatform}_chat_id`]: chatId,
    email,
    phone,
  }) || "").trim();

  return compactDefined({
    name: displayName,
    display_name: displayName,
    email,
    phone,
    whatsapp: cleanPlatform === "whatsapp" ? phone : undefined,
    whatsapp_phone: cleanPlatform === "whatsapp" ? phone : undefined,
    wa_id: cleanPlatform === "whatsapp" ? externalUserId : undefined,

    [`${cleanPlatform}_id`]: externalUserId,
    [`${cleanPlatform}_username`]: username,
    [`${cleanPlatform}_chat_id`]: chatId,

    telegram_id: cleanPlatform === "telegram" ? externalUserId : undefined,
    telegram_username: cleanPlatform === "telegram" ? username : undefined,
    telegram_chat_id: cleanPlatform === "telegram" ? chatId : undefined,

    facebook_sender_id: cleanPlatform === "facebook" ? externalUserId : undefined,
    facebook_page_id: cleanPlatform === "facebook" ? (recipientId || process.env.FACEBOOK_PAGE_ID || "") : undefined,

    instagram_sender_id: cleanPlatform === "instagram" ? externalUserId : undefined,
    instagram_business_account_id: cleanPlatform === "instagram" ? (recipientId || process.env.INSTAGRAM_BUSINESS_ACCOUNT_ID || "") : undefined,

    platform_contact_id: platformContactId,
    platform_username: username,
    platform_display_name: displayName,
    platform_message_id: platformMessageId,
    source_platform: cleanPlatform,
    platform: cleanPlatform,
    source_channel: "social_integration",
    source_integration_id: integration?.id || null,
    source_integration_name: integration?.account_name || integration?.name || getPlatformConfig(cleanPlatform).label,
    source_text: String(text || "").trim(),
    last_message: String(text || "").trim(),
    last_message_at: nowIso(),
    conversation_summary: String(text || "").trim().slice(0, 300),
    conversation_direction: "inbound",
    client_reached_out: true,
    agent_initiated: false,
    opt_in_status: cleanPlatform === "whatsapp" ? "platform_inbound" : "platform_inbound",
    status: "new",
    lead_status: "new",
  });
}

function findExistingSocialLead(db, platform, payload = {}) {
  const cleanPlatform = normalizeSocialPlatform(platform);
  const leads = ensureCrmArray(db, "leads");
  const possibleIds = [
    payload.email,
    payload.phone,
    payload.whatsapp,
    payload.whatsapp_phone,
    payload.wa_id,
    payload.platform_contact_id,
    payload.telegram_id,
    payload.facebook_id,
    payload.instagram_id,
    payload.linkedin_id,
    payload.reddit_id,
    payload.youtube_id,
    payload.tiktok_id,
    payload.twitter_id,
    payload.discord_id,
    payload[`${cleanPlatform}_id`],
    payload[`${cleanPlatform}_username`],
    payload[`${cleanPlatform}_chat_id`],
  ].map((item) => String(item || "").trim()).filter(Boolean);

  return leads.find((lead) => {
    if (payload.email && normalizeEmail(lead.email) === normalizeEmail(payload.email)) return true;
    return possibleIds.some((value) => {
      return [
        lead.phone,
        lead.whatsapp,
        lead.whatsapp_phone,
        lead.wa_id,
        lead.platform_contact_id,
        lead.telegram_id,
        lead.facebook_id,
        lead.instagram_id,
        lead.linkedin_id,
        lead.reddit_id,
        lead.youtube_id,
        lead.tiktok_id,
        lead.twitter_id,
        lead.discord_id,
        lead[`${cleanPlatform}_id`],
        lead[`${cleanPlatform}_username`],
        lead[`${cleanPlatform}_chat_id`],
      ].map((x) => String(x || "").trim()).includes(value);
    });
  }) || null;
}

function upsertSocialLead(db, platform, payload = {}) {
  const cleanPlatform = normalizeSocialPlatform(platform);
  const previous = findExistingSocialLead(db, cleanPlatform, payload);
  const leads = ensureCrmArray(db, "leads");
  const now = nowIso();
  const inboundText = String(payload.last_message || payload.source_text || "").trim();

  if (previous) {
    Object.assign(previous, compactDefined(payload), {
      id: getStableLeadId(previous) || uuid(),
      lead_id: previous.lead_id || getStableLeadId(previous) || uuid(),
      source_platform: cleanPlatform,
      platform: cleanPlatform,
      source_channel: previous.source_channel || "social_integration",
      conversation_direction: previous.conversation_direction || "inbound",
      client_reached_out: previous.client_reached_out !== false,
      agent_initiated: Boolean(previous.agent_initiated),
      last_message: inboundText || previous.last_message || previous.last_message_text || "",
      last_message_at: inboundText ? now : previous.last_message_at || previous.updated_at || now,
      last_inbound_at: now,
      updated_at: now,
      status: previous.status || previous.lead_status || payload.status || "new",
      lead_status: previous.lead_status || previous.status || payload.lead_status || "new",
    });
    ensureLeadIdentityFields(previous);
    return { lead: previous, created: false };
  }

  const leadId = uuid();
  const lead = withTimestamps({
    id: leadId,
    lead_id: leadId,
    brand_id: payload.brand_id || null,
    name: payload.name || payload.display_name || `${getPlatformConfig(cleanPlatform).label} Lead`,
    status: payload.status || "new",
    lead_status: payload.lead_status || payload.status || "new",
    lead_score: Number(payload.lead_score || 10),
    source_platform: cleanPlatform,
    platform: cleanPlatform,
    source_channel: "social_integration",
    conversation_direction: "inbound",
    client_reached_out: true,
    agent_initiated: false,
    created_from: `${cleanPlatform}_webhook`,
    last_message: inboundText,
    last_message_at: inboundText ? now : null,
    last_inbound_at: now,
    ...compactDefined(payload),
  });

  ensureLeadIdentityFields(lead);
  leads.push(lead);
  return { lead, created: true };
}

function appendSocialConversation(db, { lead, platform, direction = "inbound", text = "", payload = {}, integration = null }) {
  const cleanPlatform = normalizeSocialPlatform(platform);
  const now = nowIso();
  const leadId = getStableLeadId(lead);
  const msgText = String(text || payload?.text || payload?.message || "").trim();

  const message = withTimestamps({
    id: uuid(),
    conversation_id: lead?.conversation_id || leadId || uuid(),
    brand_id: lead?.brand_id || integration?.brand_id || null,
    lead_id: leadId || null,
    platform: cleanPlatform,
    source_platform: cleanPlatform,
    integration_id: integration?.id || null,
    direction: normalizeLeadDirection(direction, "inbound"),
    message_text: msgText,
    text: msgText,
    platform_message_id: payload?.message_id || payload?.platform_message_id || payload?.entry?.[0]?.messaging?.[0]?.message?.mid || null,
    platform_contact_id: lead?.platform_contact_id || lead?.[`${cleanPlatform}_id`] || null,
    raw_payload: payload || {},
    sent_by: normalizeLeadDirection(direction, "inbound") === "outbound" ? "system" : "lead",
    status: normalizeLeadDirection(direction, "inbound") === "outbound" ? "sent" : "received",
    timestamp: now,
    created_at: now,
  });

  ensureCrmArray(db, "conversations").push(message);
  if (typeof ngMirrorConversationMessageToStores === "function") {
    ngMirrorConversationMessageToStores(db, message, lead);
  }

  if (lead) {
    lead.id = leadId || lead.id || uuid();
    lead.lead_id = lead.lead_id || lead.id;
    lead.last_message = msgText || lead.last_message || "";
    lead.last_message_at = now;
    if (normalizeLeadDirection(direction, "inbound") === "inbound") {
      lead.last_inbound_at = now;
      lead.client_reached_out = true;
      lead.conversation_direction = lead.conversation_direction || "inbound";
    } else {
      lead.last_outbound_at = now;
      lead.agent_initiated = true;
    }
    lead.updated_at = now;
  }

  return message;
}


function ngMirrorConversationMessageToStores(db, message = {}, lead = {}) {
  const text = String(message.message_text || message.text || message.body || message.message || "").trim();
  if (!text) return null;

  const direction = normalizeLeadDirection(message.direction || message.message_direction || "inbound", "inbound");
  const channel = normalizeSocialPlatform(message.platform || message.source_platform || message.channel || lead?.source_platform || "whatsapp");
  const leadId = message.lead_id || lead?.id || lead?.lead_id || null;
  const providerMessageId = message.platform_message_id || message.provider_message_id || message.message_id || null;
  const createdAt = message.created_at || message.received_at || message.sent_at || message.timestamp || nowIso();

  const sameTextRecent = (item = {}) => {
    const itemText = String(item.message_text || item.text || item.body || item.message || "").trim();
    if (!itemText || itemText !== text) return false;
    const sameLead = String(item.lead_id || "") === String(leadId || "");
    const sameProvider = providerMessageId && String(item.provider_message_id || item.platform_message_id || item.message_id || "") === String(providerMessageId);
    const sameDirection = normalizeLeadDirection(item.direction || item.message_direction || "", "") === direction;
    const itemTime = new Date(item.created_at || item.received_at || item.sent_at || item.timestamp || 0).getTime();
    const msgTime = new Date(createdAt || 0).getTime();
    const closeTime = Number.isFinite(itemTime) && Number.isFinite(msgTime) && Math.abs(itemTime - msgTime) <= 5000;
    return Boolean((sameProvider || (sameLead && closeTime)) && sameDirection);
  };

  const logs = ensureCrmArray(db, "message_logs");
  if (!logs.some(sameTextRecent)) {
    logs.push(withTimestamps({
      id: uuid(),
      brand_id: message.brand_id || lead?.brand_id || null,
      channel,
      provider: channel,
      direction,
      lead_id: leadId,
      from: direction === "inbound" ? (message.from || lead?.phone || lead?.whatsapp || lead?.platform_contact_id || "") : "NextGen",
      to: direction === "outbound" ? (message.to || lead?.phone || lead?.whatsapp || lead?.platform_contact_id || "") : "NextGen",
      text,
      message_text: text,
      provider_message_id: providerMessageId,
      status: direction === "inbound" ? "received" : "sent",
      received_at: direction === "inbound" ? createdAt : null,
      sent_at: direction === "outbound" ? createdAt : null,
      created_at: createdAt,
      metadata: { source: "conversation_mirror", conversation_id: message.id || message.conversation_id || null },
    }));
  }

  const bucketName = direction === "inbound" ? "inbound_messages" : "outbound_messages";
  const bucket = ensureCrmArray(db, bucketName);
  if (!bucket.some(sameTextRecent)) {
    bucket.push(withTimestamps({
      id: uuid(),
      brand_id: message.brand_id || lead?.brand_id || null,
      channel,
      provider: channel,
      direction,
      lead_id: leadId,
      text,
      message_text: text,
      provider_message_id: providerMessageId,
      status: direction === "inbound" ? "received" : "sent",
      received_at: direction === "inbound" ? createdAt : null,
      sent_at: direction === "outbound" ? createdAt : null,
      created_at: createdAt,
      metadata: { source: "conversation_mirror", conversation_id: message.id || message.conversation_id || null },
    }));
  }

  return true;
}

function createSocialClientDataEvent(db, { lead, platform, payload = {}, integration = null }) {
  const event = withTimestamps({
    id: uuid(),
    lead_id: lead?.id || null,
    brand_id: lead?.brand_id || integration?.brand_id || null,
    agent_id: null,
    event_type: `${normalizeSocialPlatform(platform)}_inbound_capture`,
    source: normalizeSocialPlatform(platform),
    client_data: compactDefined(payload),
  });
  ensureCrmArray(db, "client_data_events").push(event);
  return event;
}

async function testSocialIntegration(integration = {}) {
  const platform = normalizeSocialPlatform(integration.platform);
  const config = getPlatformConfig(platform);

  if (platform === "telegram") {
    const telegramResult = await telegramApi("getMe", {}, integration);
    return {
      message: `Telegram live connection passed for @${telegramResult.result?.username || "bot"}`,
      platform,
      live_connected: true,
      safe_metadata: { bot_username: telegramResult.result?.username || null, bot_id: telegramResult.result?.id || null },
      bot: telegramResult.result,
    };
  }

  if (platform === "email") {
    const hasResend = Boolean(process.env.RESEND_API_KEY);
    const hasSendGrid = Boolean(process.env.SENDGRID_API_KEY);
    const hasSmtp = Boolean(process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS);
    if (!hasResend && !hasSendGrid && !hasSmtp && !integration.api_key) {
      const e = new Error("Email provider is not configured. Add RESEND_API_KEY, SENDGRID_API_KEY, SMTP_* or save an integration API key.");
      e.statusCode = 400;
      throw e;
    }
    return { message: "Email integration configuration found", platform, live_connected: Boolean(hasResend || hasSendGrid), mode: hasResend ? "resend" : hasSendGrid ? "sendgrid" : "smtp_or_saved_credentials", safe_metadata: { provider: hasResend ? "resend" : hasSendGrid ? "sendgrid" : "smtp_or_saved_credentials" } };
  }

  if (platform === "whatsapp") {
    const token = getIntegrationCredential(integration, "api_key", "WHATSAPP_ACCESS_TOKEN") || process.env.WHATSAPP_ACCESS_TOKEN;
    const phoneNumberId = integration.phone_number_id || integration.account_id || process.env.WHATSAPP_PHONE_NUMBER_ID;
    if (!token || !phoneNumberId) {
      const e = new Error("WhatsApp is missing WHATSAPP_ACCESS_TOKEN or WHATSAPP_PHONE_NUMBER_ID.");
      e.statusCode = 400;
      throw e;
    }
    const response = await axios.get(`https://graph.facebook.com/v19.0/${phoneNumberId}`, { params: { access_token: token }, timeout: 20000 });
    return { message: "WhatsApp Cloud API connection passed", platform, live_connected: true, safe_metadata: { phone_number_id: phoneNumberId, display_phone_number: response.data?.display_phone_number || null }, meta: response.data };
  }

  if (platform === "facebook" || platform === "instagram") {
    const token = getMetaTokenForPlatform(platform, integration);
    if (!token) {
      const e = new Error(platform === "instagram"
        ? "Instagram integration is missing INSTAGRAM_PAGE_ACCESS_TOKEN or META_PAGE_ACCESS_TOKEN."
        : "Facebook integration is missing META_PAGE_ACCESS_TOKEN.");
      e.statusCode = 400;
      throw e;
    }

    const id = getMetaAccountIdForPlatform(platform, integration);
    const fields = platform === "instagram" ? "id,username,name" : "id,name";

    try {
      const response = await axios.get(`https://graph.facebook.com/v19.0/${id}`, {
        params: { access_token: token, fields },
        timeout: 20000,
      });

      return {
        message: `${config.label} API connection passed`,
        platform,
        live_connected: true,
        configured: true,
        mode: "graph_verified",
        safe_metadata: {
          id: response.data?.id || id,
          name: response.data?.name || response.data?.username || null,
          graph_verified: true,
        },
        meta: response.data,
      };
    } catch (error) {
      const metaError = error.response?.data?.error || {};
      const metaMessage = String(metaError.message || error.message || "Meta Graph API test failed");
      const metaCode = metaError.code || error.response?.status || null;

      const isPermissionOrReviewBlock =
        error.response?.status === 400 &&
        (
          metaCode === 100 ||
          metaCode === 10 ||
          metaCode === 190 ||
          /missing permission|reviewable feature|does not exist|pages_read_engagement|permission/i.test(metaMessage)
        );

      if (!isPermissionOrReviewBlock) {
        const e = new Error(metaMessage);
        e.statusCode = error.response?.status || 500;
        throw e;
      }

      return {
        message: `${config.label} token is stored, webhook can be configured, but Meta profile lookup is blocked by permission/app review.`,
        platform,
        live_connected: false,
        configured: true,
        mode: "configured_permission_limited",
        warning: metaMessage,
        safe_metadata: {
          id,
          graph_verified: false,
          meta_error_code: metaCode,
          required_review_or_permission: true,
          note: platform === "facebook"
            ? "Facebook Page messaging can be configured for development, but Page metadata lookup may need pages_read_engagement/app review."
            : "Instagram messaging can be configured for development, but IG metadata lookup may need Instagram permissions/app review.",
        },
      };
    }
  }

  if (platform === "discord") {
    const webhookUrl = integration.webhook_url || (process.env.DISCORD_DAILY_MCQ_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL);
    const botToken = getIntegrationCredential(integration, "api_key", "DISCORD_BOT_TOKEN") || process.env.DISCORD_BOT_TOKEN;
    if (!webhookUrl && !botToken) {
      const e = new Error("Discord is missing DISCORD_WEBHOOK_URL or DISCORD_BOT_TOKEN.");
      e.statusCode = 400;
      throw e;
    }
    return { message: "Discord configuration found", platform, live_connected: Boolean(webhookUrl || botToken), safe_metadata: { mode: webhookUrl ? "webhook" : "bot_token" } };
  }

  const configured = Boolean(integration.api_key || integration.access_token || integration.account_id || integration.webhook_url);
  return {
    message: `${config.label} settings are stored. Live API execution is manual/approval-first until OAuth/API access is completed.`,
    platform,
    live_connected: false,
    configured,
    mode: configured ? "configured_manual_first" : "not_configured",
    required_env: config.env,
    safe_metadata: { required_env: config.env, manual_first: true },
  };
}

async function syncSocialIntegration({ db, integration, body = {} }) {
  const platform = normalizeSocialPlatform(integration.platform);
  if (platform === "telegram") {
    const result = await telegramApi("getMe", {}, integration);
    return { message: `Telegram sync checked bot @${result.result?.username || "bot"}`, platform, live_connected: true, leads_captured: 0, safe_metadata: { bot_username: result.result?.username || null } };
  }
  if (["whatsapp", "facebook", "instagram", "email", "discord"].includes(platform)) {
    const test = await testSocialIntegration(integration);
    return { ...test, message: `${getPlatformConfig(platform).label} configuration synced`, leads_captured: 0 };
  }
  return { message: `${getPlatformConfig(platform).label} sync saved as manual-first. Inbound webhooks/imports can still capture leads.`, platform, live_connected: false, leads_captured: 0, safe_metadata: { manual_first: true } };
}

async function sendSocialMessage({ db, integration, body = {} }) {
  const platform = normalizeSocialPlatform(integration.platform);
  const to = body.to || body.chat_id || body.phone || body.email || body.recipient || body.channel_id;
  const text = String(body.text || body.message || body.body || "").trim();
  if (!text) {
    const e = new Error("Message text is required");
    e.statusCode = 400;
    throw e;
  }

  if (platform === "telegram") {
    const result = await telegramApi("sendMessage", { chat_id: to, text }, integration);
    return { message: "Telegram message sent", platform, live_sent: true, raw: result };
  }

  if (platform === "email") {
    const from = body.from || process.env.EMAIL_FROM || process.env.RESEND_FROM_EMAIL || "NextGen USMLE <noreply@nextgenusmlelms.com>";
    const subject = body.subject || "NextGen USMLE";
    if (process.env.RESEND_API_KEY) {
      const response = await axios.post("https://api.resend.com/emails", { from, to: Array.isArray(to) ? to : [to], subject, text }, { headers: { Authorization: `Bearer ${process.env.RESEND_API_KEY}`, "Content-Type": "application/json" }, timeout: 30000 });
      return { message: "Email sent through Resend", platform, live_sent: true, raw: response.data };
    }
    if (process.env.SENDGRID_API_KEY) {
      const response = await axios.post("https://api.sendgrid.com/v3/mail/send", { personalizations: [{ to: [{ email: to }] }], from: { email: String(from).match(/<([^>]+)>/)?.[1] || from }, subject, content: [{ type: "text/plain", value: text }] }, { headers: { Authorization: `Bearer ${process.env.SENDGRID_API_KEY}`, "Content-Type": "application/json" }, timeout: 30000 });
      return { message: "Email sent through SendGrid", platform, live_sent: true, raw: { status: response.status } };
    }
    const e = new Error("Email sending requires RESEND_API_KEY or SENDGRID_API_KEY.");
    e.statusCode = 400;
    throw e;
  }

  if (platform === "whatsapp") {
    const token = getIntegrationCredential(integration, "api_key", "WHATSAPP_ACCESS_TOKEN") || process.env.WHATSAPP_ACCESS_TOKEN;
    const phoneNumberId = integration.phone_number_id || integration.account_id || process.env.WHATSAPP_PHONE_NUMBER_ID;
    if (!token || !phoneNumberId) {
      const e = new Error("WhatsApp is missing WHATSAPP_ACCESS_TOKEN or WHATSAPP_PHONE_NUMBER_ID.");
      e.statusCode = 400;
      throw e;
    }
    const mediaUrl = normalizeCrmString(body.media_url || body.mediaUrl || body.image_url || body.imageUrl || "");
    const mediaId = normalizeCrmString(body.media_id || body.mediaId || body.whatsapp_media_id || "");
    const mediaType = normalizeCrmLower(body.media_type || body.mediaType || "image", "image");
    const waPayload = { messaging_product: "whatsapp", to };
    if (mediaUrl || mediaId) {
      const cleanType = ["image", "video", "document", "audio"].includes(mediaType) ? mediaType : "image";
      waPayload.type = cleanType;
      const mediaPayload = mediaId ? { id: mediaId } : { link: mediaUrl };
      if (text && ["image", "video", "document"].includes(cleanType)) mediaPayload.caption = text;
      waPayload[cleanType] = mediaPayload;
    } else {
      waPayload.type = "text";
      waPayload.text = { preview_url: false, body: text };
    }
    const response = await axios.post(`https://graph.facebook.com/v19.0/${phoneNumberId}/messages`, waPayload, { headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, timeout: 30000 });
    return { message: "WhatsApp message sent", platform, live_sent: true, raw: response.data };
  }

  if (platform === "facebook" || platform === "instagram") {
    const token = getMetaTokenForPlatform(platform, integration);
    if (!token) {
      const e = new Error(platform === "instagram"
        ? "Instagram sending requires INSTAGRAM_PAGE_ACCESS_TOKEN or META_PAGE_ACCESS_TOKEN."
        : "Facebook sending requires META_PAGE_ACCESS_TOKEN.");
      e.statusCode = 400;
      throw e;
    }

    const recipientId = to;
    if (!recipientId) {
      const e = new Error("Recipient ID is required for Meta messaging.");
      e.statusCode = 400;
      throw e;
    }

    const response = await axios.post(
      `https://graph.facebook.com/v19.0/me/messages`,
      {
        recipient: { id: recipientId },
        message: { text },
        messaging_type: body.messaging_type || "RESPONSE",
      },
      {
        params: { access_token: token },
        headers: { "Content-Type": "application/json" },
        timeout: 30000,
      }
    );

    return {
      message: `${getPlatformConfig(platform).label} message sent`,
      platform,
      live_sent: true,
      raw: response.data,
    };
  }

  if (platform === "discord") {
    const webhookUrl = integration.webhook_url || (process.env.DISCORD_DAILY_MCQ_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL);
    if (!webhookUrl) {
      const e = new Error("Discord webhook URL is required for live send.");
      e.statusCode = 400;
      throw e;
    }
    const response = await axios.post(webhookUrl, { content: text }, { timeout: 30000 });
    return { message: "Discord webhook message sent", platform, live_sent: true, raw: { status: response.status } };
  }

  const draft = withTimestamps({
    id: uuid(),
    brand_id: integration.brand_id || null,
    integration_id: integration.id,
    platform,
    action_type: `${platform}_manual_send_draft`,
    input_text: text,
    output_text: text,
    status: "draft",
    approval_status: "needs_approval",
    metadata: { to },
  });
  ensureCrmArray(db, "approval_queue").push(draft);
  return { message: `${getPlatformConfig(platform).label} is manual-first. Message saved to approval queue as a draft.`, platform, live_sent: false, approval_item: draft };
}

function verifyMetaWebhook(req, res) {
  const mode = req.query["hub.mode"];
  const token = req.query["hub.verify_token"];
  const challenge = req.query["hub.challenge"];
  const expected = process.env.META_VERIFY_TOKEN || process.env.WHATSAPP_WEBHOOK_VERIFY_TOKEN;
  if (mode === "subscribe" && token && expected && token === expected) return res.status(200).send(challenge);
  return res.status(403).send("Forbidden");
}

function verifyTelegramSecretHeader(req) {
  const expectedSecret = getTelegramWebhookSecret();
  if (!expectedSecret) return true;
  const receivedSecret = req.headers["x-telegram-bot-api-secret-token"];
  return String(receivedSecret || "") === String(expectedSecret);
}

async function handleUniversalWebhook({ req, res, platform, integrationId = null }) {
  try {
    const db = await readCrmDb();
    const requestedPlatform = normalizeSocialPlatform(platform);
    const cleanPlatform = (requestedPlatform === "facebook" || requestedPlatform === "instagram")
      ? (String(req.body?.object || "").toLowerCase().includes("instagram") ? "instagram" : requestedPlatform)
      : requestedPlatform;
    const integration = integrationId
      ? ensureCrmArray(db, "integrations").find((item) => String(item.id) === String(integrationId))
      : getIntegrationByPlatform(db, cleanPlatform);

    const leadPayload = parseInboundSocialPayload({ platform: cleanPlatform, payload: req.body || {}, integration });
    const inboundText = leadPayload.source_text || "";
    const { lead, created } = upsertSocialLead(db, cleanPlatform, leadPayload);
    const conversation = appendSocialConversation(db, { lead, platform: cleanPlatform, direction: "inbound", text: inboundText, payload: req.body || {}, integration });
    createSocialClientDataEvent(db, { lead, platform: cleanPlatform, payload: leadPayload, integration });
    createIntegrationLog(db, { brand_id: integration?.brand_id || lead.brand_id || null, integration_id: integration?.id || null, platform: cleanPlatform, action: "inbound_webhook", status: "success", message: created ? `Created lead from ${cleanPlatform} inbound webhook` : `Updated lead from ${cleanPlatform} inbound webhook`, metadata: { lead_id: lead.id, conversation_id: conversation.id } });

    let aiAutoResult = null;
    try {
      ngNormalizeLeadAiMode(lead);
      const aiMode = String(lead.ai_mode || lead.automation_mode || "auto").toLowerCase();
      const explicitlyManualOrDraft =
        (lead.ai_mode_set === true || lead.automation_mode_set === true || lead.mode_locked === true || lead.ai_mode_manually_set === true) &&
        (aiMode === "manual" || aiMode === "draft" || aiMode === "ai_draft");

      if (!explicitlyManualOrDraft && String(inboundText || "").trim()) {
        const messages = ngLeadConversationMessages(db, lead.id);
        const latestInbound = conversation;
        const channel = resolveCrmChannelForConversation({
          requestedChannel: lead.current_channel || lead.last_channel || lead.source_platform || lead.platform || cleanPlatform || "auto",
          lead,
          latestInbound,
          fallback: cleanPlatform || "whatsapp",
        });

        const duplicateGuard = ngShouldSkipAiAutoForInbound(lead, latestInbound, { channel });
        if (duplicateGuard.skip) {
          aiAutoResult = { sent: false, skipped: true, reason: duplicateGuard.reason, channel, wait_ms: duplicateGuard.wait_ms || 0 };
        } else if (channel === "whatsapp" && !ngWithinHours(latestInbound.created_at || latestInbound.received_at || latestInbound.timestamp, 24)) {
          ngReleaseAiAutoLock(duplicateGuard.lock_key);
          aiAutoResult = { sent: false, skipped: true, reason: "whatsapp_template_required", channel, requires_template: true };
          ngAffArray(db, "ai_actions").unshift({ id: uuid(), title: "WhatsApp template required for Full AI Auto", area: "whatsapp", type: "template_required", status: "pending_approval", lead_id: lead.id, payload: { lead_id: lead.id, channel }, created_at: ngAffNow(), updated_at: ngAffNow() });
        } else {
          const ai = await ngGenerateStudentAutoReply({ db, lead, messages, channel });
          const replyDelayMs = await ngAylaWaitBeforeAutoSend(db);
          const to = getBestRecipientForChannel({ channel, lead, message: latestInbound });
          const sendResult = await sendCrmMessage({
            db,
            brandId: lead.brand_id || integration?.brand_id || null,
            channel,
            to,
            text: ai.reply,
            leadId: lead.id,
            metadata: {
              source: "social_webhook_full_ai_auto",
              ai_auto: true,
              latest_inbound_id: latestInbound.id || null,
              inbound_message_id: ngAiAutoMessageFingerprint(latestInbound),
              messaging_type: ["facebook", "instagram"].includes(channel) ? "RESPONSE" : undefined,
            },
          });
          const delivered = ngAylaMarkProcessedOnlyIfDelivered({ lead, inbound: latestInbound, channel, reply: ai.reply, sendResult });
          ngReleaseAiAutoLock(duplicateGuard.lock_key);
          aiAutoResult = { sent: delivered, queued: Boolean(sendResult.queued), channel, to, result: sendResult };
          ngAffArray(db, "ai_auto_runs").unshift({ id: uuid(), lead_id: lead.id, inbound_message_id: ngAiAutoMessageFingerprint(latestInbound), channel, reply: ai.reply, sent: delivered, queued: Boolean(sendResult.queued), result: sendResult, model: ai.model, usage: ai.usage, reply_delay_ms: replyDelayMs || 0, created_by: "webhook", created_at: ngAffNow() });
        }
      }
    } catch (aiError) {
      createIntegrationLog(db, { brand_id: integration?.brand_id || lead.brand_id || null, integration_id: integration?.id || null, platform: cleanPlatform, action: "full_ai_auto_webhook", status: "failed", message: aiError.message, metadata: { lead_id: lead.id, conversation_id: conversation.id } });
      aiAutoResult = { sent: false, error: aiError.message };
    }

    await writeCrmDb(db);
    res.json({ success: true, platform: cleanPlatform, lead_id: lead.id, created, conversation_id: conversation.id, ai_auto: aiAutoResult });
    // v94 safety: if the inline webhook AI path skipped or returned before sending, wake Ayla once after response.
    // Duplicate/outbound guards prevent double replies if the inline path already sent.
    ngScheduleAylaAutoReplyAfterInbound({ leadId: lead.id, source: "universal_social_webhook_wakeup", delayMs: 1000 });
  } catch (error) {
    console.error("Universal social webhook error:", error.message);
    res.status(error.statusCode || 500).json({ success: false, error: error.message || "Webhook failed" });
  }
}

app.get("/webhooks/social/:platform/:integrationId?", (req, res) => {
  const platform = normalizeSocialPlatform(req.params.platform);
  if (["whatsapp", "facebook", "instagram"].includes(platform)) return verifyMetaWebhook(req, res);
  res.json({ success: true, platform, message: `${getPlatformConfig(platform).label} webhook endpoint is online. Send POST requests here.` });
});

app.post("/webhooks/social/:platform/:integrationId?", async (req, res) => {
  const platform = normalizeSocialPlatform(req.params.platform);
  if (platform === "telegram" && !verifyTelegramSecretHeader(req)) return res.status(403).json({ success: false, error: "Invalid Telegram webhook secret" });
  return handleUniversalWebhook({ req, res, platform, integrationId: req.params.integrationId || null });
});

