function ngDailySessionDateKey(date = new Date(), timezone = "America/New_York") {
  try {
    const parts = new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(date);
    const values = {};
    for (const p of parts) if (p.type !== "literal") values[p.type] = p.value;
    return `${values.year}-${values.month}-${values.day}`;
  } catch {
    return new Date(date).toISOString().slice(0, 10);
  }
}

function ngDailySessionTimeParts(date = new Date(), timezone = "America/New_York") {
  try {
    const parts = new Intl.DateTimeFormat("en-US", { timeZone: timezone, weekday: "short", hour: "2-digit", minute: "2-digit", hour12: false }).formatToParts(date);
    const values = {};
    for (const p of parts) if (p.type !== "literal") values[p.type] = p.value;
    return { weekday: values.weekday || "", hour: Number(values.hour || 0), minute: Number(values.minute || 0) };
  } catch {
    const d = new Date(date);
    return { weekday: ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][d.getUTCDay()], hour: d.getUTCHours(), minute: d.getUTCMinutes() };
  }
}


function ngNormalizeSessionOverrideStatus(value = "") {
  const clean = String(value || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  if (["cancelled", "canceled", "no_session", "doctor_not_available", "mentor_not_available", "unavailable"].includes(clean)) return "cancelled";
  if (["live", "live_today", "available", "normal", "resume"].includes(clean)) return "live";
  return clean || "live";
}

function ngGetLiveSessionOverrideForDate(db = {}, dateKey = "", brandId = null) {
  const targetDate = String(dateKey || ngDailySessionDateKey(new Date())).slice(0, 10);
  return ensureCrmArray(db, "session_overrides")
    .filter((item) => String(item.date || item.session_date || "").slice(0, 10) === targetDate)
    .filter((item) => !brandId || !item.brand_id || String(item.brand_id) === String(brandId))
    .sort((a, b) => String(b.updated_at || b.created_at || "").localeCompare(String(a.updated_at || a.created_at || "")))[0] || null;
}

function ngLiveSessionOverrideIsCancelled(override = null) {
  if (!override) return false;
  if (override.cancelled === true || override.is_cancelled === true || override.no_session_today === true || override.doctor_not_available === true) return true;
  return ngNormalizeSessionOverrideStatus(override.status || override.session_status) === "cancelled";
}

function ngBuildNoSessionRecordingFallbackText({ db = {}, settings = {}, assets = {}, override = {}, lead = {} } = {}) {
  const custom = normalizeCrmString(override.message || override.no_session_message || settings.no_session_today_message || settings.doctor_not_available_message || "");
  if (custom) {
    return custom
      .replace(/{{\s*student_name\s*}}/gi, ng41LeadName(lead) || "Doctor")
      .replace(/{{\s*recording_link\s*}}/gi, assets.recordingLink || "")
      .replace(/{{\s*session_time\s*}}/gi, assets.sessionTime || "1 PM EST")
      .replace(/{{\s*demo_link\s*}}/gi, assets.uworldLink || "")
      .trim();
  }

  const recordingLine = assets.recordingLink
    ? `\n\nYou can watch this recent session recording for now:\n${assets.recordingLink}`
    : "\n\nYou can continue with the recent recording/demo for now, and I’ll share the recording link as soon as it is available.";

  return `Doctor, today’s ${assets.sessionTime || "1 PM EST"} live session is not available because the mentor/doctor is not available today.${recordingLine}\n\nIf you like the teaching style, I can arrange a Google Meet mentor consultation for guidance. Or if you prefer to wait for tomorrow’s live session, I’ll update you tomorrow.`;
}

async function ngRunNoSessionRecordingFallback({ db = {}, brandId = null, limit = 50, dryRun = false, source = "session_override", override = null, dateKey = ngDailySessionDateKey(new Date()) } = {}) {
  const settings = ngAylaPickSettings(db);
  const assets = ngAylaGetSalesAssets(db);
  const action = "no_session_recording_fallback";
  const templateIdDefault = settings.no_session_recording_template_key || settings.no_session_today_template_key || "no_session_recording_fallback";
  const leads = ensureCrmArray(db, "leads")
    .filter((lead) => !brandId || String(lead.brand_id || "") === String(brandId || ""))
    .filter((lead) => ngDailyLiveSessionEligibleLead(db, lead, settings))
    .slice(0, Math.max(1, Math.min(300, Number(limit || 50))));

  const results = [];
  for (const lead of leads) {
    if (ngDailyLiveSessionAlreadySent(db, lead, action, dateKey)) {
      results.push({ lead_id: lead.id, skipped: true, reason: "no_session_update_already_sent_today" });
      continue;
    }
    const recentCooldownMinutes = Math.max(1, Number(settings.daily_session_recent_send_cooldown_minutes || 10));
    if (ngRecentlyContactedMinutesAgo(lead, recentCooldownMinutes)) {
      results.push({ lead_id: lead.id, skipped: true, reason: "recent_outbound_cooldown", cooldown_minutes: recentCooldownMinutes });
      continue;
    }

    const channel = resolveCrmChannelForConversation({ requestedChannel: lead.current_channel || lead.last_channel || lead.source_platform || lead.platform || "whatsapp", lead, fallback: "whatsapp" });
    const latestInbound = ngLatestInbound(ngLeadConversationMessages(db, lead.id));
    const whatsappWindowOpen = channel !== "whatsapp" || ngWithinHours(latestInbound?.created_at || latestInbound?.received_at || latestInbound?.timestamp, 24);
    const templateId = channel === "whatsapp" && !whatsappWindowOpen ? templateIdDefault : null;
    const text = ngBuildNoSessionRecordingFallbackText({ db, settings, assets, override, lead });

    if (dryRun) {
      results.push({ lead_id: lead.id, dry_run: true, action, template_id: templateId, text });
      continue;
    }

    try {
      const result = await sendCrmMessage({
        db,
        brandId: lead.brand_id || brandId || db.settings?.default_brand_id || null,
        channel,
        to: getBestRecipientForChannel({ channel, lead }),
        text,
        templateId,
        templateVariables: {
          lead,
          student_name: ng41LeadName(lead) || "Doctor",
          exam_type: ng41LeadExamType(lead) || "USMLE",
          session_time: assets.sessionTime,
          recording_link: assets.recordingLink,
          demo_link: assets.uworldLink,
        },
        leadId: lead.id,
        metadata: {
          source: "no_session_today_override",
          daily_live_session_action: action,
          daily_live_session_date: dateKey,
          template_key: templateId,
          scheduler_source: source,
          session_override_id: override?.id || null,
          session_status: "cancelled",
        },
      });

      if (result.skipped || result.duplicate_blocked) {
        results.push({ lead_id: lead.id, skipped: true, reason: result.reason || "duplicate_message_blocked", action, template_id: templateId });
        continue;
      }
      lead.last_no_session_update_sent_at = nowIso();
      lead.no_session_update_date = dateKey;
      lead.next_action = "wait_for_recording_feedback_google_meet_or_tomorrow_live_session";
      lead.updated_at = nowIso();
      results.push({ lead_id: lead.id, sent: Boolean(result.success || result.queued), action, template_id: templateId, message_id: result.log?.id || null });
    } catch (error) {
      results.push({ lead_id: lead.id, sent: false, error: error.message, action, template_id: templateId });
    }
  }

  if (override && !dryRun) {
    override.no_session_update_sent_at = override.no_session_update_sent_at || nowIso();
    override.no_session_update_last_run_at = nowIso();
    override.no_session_update_sent_count = Number(override.no_session_update_sent_count || 0) + results.filter((r) => r.sent).length;
    override.updated_at = nowIso();
  }

  return { action, processed: results.length, sent: results.filter((r) => r.sent).length, skipped: results.filter((r) => r.skipped).length, results, override };
}

function ngDailyLiveSessionActionNow(settings = {}, date = new Date()) {
  const tz = "America/New_York";
  const { weekday, hour, minute } = ngDailySessionTimeParts(date, tz);
  const day = String(weekday || "").toLowerCase();
  if (day.startsWith("sat") || day.startsWith("sun")) return null;
  const reminderMinutes = Number(settings.session_reminder_minutes || settings.default_session_reminder_minutes || 5);
  const sessionHour = 13;
  const sessionMinute = 0;
  const total = hour * 60 + minute;
  const sessionTotal = sessionHour * 60 + sessionMinute;
  if (total >= 7 * 60 && total < sessionTotal - reminderMinutes) return "daily_session_invite";
  if (total >= sessionTotal - reminderMinutes && total < sessionTotal) return "five_minute_reminder";
  if (total >= sessionTotal && total <= sessionTotal + 15) return "session_link";
  if (total >= sessionTotal + Number(settings.post_session_followup_delay_minutes || 120) && total <= sessionTotal + Number(settings.post_session_followup_delay_minutes || 120) + 90) return "post_session_recording";
  return null;
}


function ngLeadIsPaidOrGroupAddedForLiveSession(lead = {}) {
  const blob = JSON.stringify({
    stage: lead.stage,
    lead_stage: lead.lead_stage,
    status: lead.status,
    payment_status: lead.payment_status,
    enrollment_status: lead.enrollment_status,
    student_status: lead.student_status,
    tags: lead.tags,
  }).toLowerCase();

  const explicitTrue = [
    lead.manual_paid,
    lead.marked_paid,
    lead.is_paid,
    lead.paid,
    lead.payment_completed,
    lead.has_active_enrollment,
    lead.enrolled,
    lead.is_enrolled,
    lead.group_added,
    lead.added_to_group,
    lead.added_to_paid_group,
    lead.paid_group_added,
    lead.whatsapp_group_added,
    lead.student_group_added,
    lead.live_session_automation_excluded,
    lead.exclude_from_live_session_flow,
    lead.exclude_daily_live_session,
  ].some(Boolean);

  if (explicitTrue) return true;

  return /(paid_enrolled|paid|enrolled|converted|closed_won|student_active|active_student|group_added|added_to_paid_group|paid_group_added|manual_paid)/i.test(blob);
}

function ngDailyLiveSessionEligibleLead(db = {}, lead = {}, settings = {}) {
  if (!lead?.id) return false;
  const stage = normalizeCrmLeadStageValue(lead.stage || lead.lead_stage || lead.status || "new_lead", "new_lead");
  if (settings.daily_session_exclude_paid !== false && (["paid", "paid_enrolled", "enrolled", "converted"].includes(stage) || ngLeadIsPaidOrGroupAddedForLiveSession(lead))) return false;
  if (settings.daily_session_exclude_group_added !== false && (lead.group_added || lead.added_to_group || lead.added_to_paid_group || lead.paid_group_added || lead.whatsapp_group_added || lead.student_group_added)) return false;
  if (lead.live_session_automation_excluded || lead.exclude_from_live_session_flow || lead.exclude_daily_live_session) return false;
  if (settings.daily_session_exclude_active_google_meet !== false && (lead.live_session_automation_paused_until_google_meet || ngAylaLeadGoogleMeetState(lead, ngAylaFindActiveGoogleMeetAppointment(db, lead)))) return false;
  if (settings.daily_session_exclude_not_interested !== false && ["not_interested", "lost", "unsubscribed"].includes(stage)) return false;
  if (settings.daily_session_exclude_suppressed !== false && (lead.suppressed || lead.ai_suppressed || ng41IsSuppressed(db, lead))) return false;
  if (!ng41LeadPhone(lead) && !lead.email) return false;
  if (["new_lead", "first_message_sent"].includes(stage) && settings.daily_session_send_to_new_leads === false) return false;
  if (["interested", "session_today", "hot_lead", "google_meet_requested"].includes(stage) && settings.daily_session_send_to_interested === false) return false;
  if (["no_reply", "warm", "follow_up"].includes(stage) && settings.daily_session_send_to_no_reply === false) return false;
  return true;
}

function ngDailyLiveSessionAlreadySent(db = {}, lead = {}, action = "", dateKey = "") {
  return ensureCrmArray(db, "message_logs").some((log) => {
    return String(log.lead_id || "") === String(lead.id || "") &&
      String(log.metadata?.daily_live_session_action || "") === String(action) &&
      String(log.metadata?.daily_live_session_date || "") === String(dateKey) &&
      !["failed", "error"].includes(String(log.status || ""));
  });
}

function ngDailyLiveSessionText(action = "", assets = {}, lead = {}) {
  const name = ng41LeadName(lead) || "Doctor";
  if (action === "no_session_recording_fallback") {
    return ngBuildNoSessionRecordingFallbackText({ assets, lead });
  }
  if (action === "five_minute_reminder") {
    return `Doctor, our live USMLE guidance session starts in 5 minutes.\n\nPlease join even for 5-10 minutes to see the mentor’s teaching style. I’ll share the link at session time.`;
  }
  if (action === "session_link") {
    const link = assets.liveSessionLink || "I’ll share the Zoom link as soon as it is available.";
    return `Doctor, the live session is starting now.\n\nJoin here:\n${link}\n\nEven 5-10 minutes is enough to understand the teaching style.`;
  }
  const rec = assets.recordingLink ? `\n\nRecording:\n${assets.recordingLink}` : "";
  return `Doctor, I’m sharing the recent live-session recording so you can check the teaching quality.${rec}\n\nDid you like the teaching style? Are you interested in joining the live sessions, or would you like a Google Meet mentor consultation for guidance?`;
}

async function ngRunDailyLiveSessionScheduler({ db = {}, brandId = null, limit = 50, dryRun = false, source = "run_due" } = {}) {
  const settings = ngAylaPickSettings(db);
  if (settings.daily_live_session_flow_enabled === false) return { action: null, processed: 0, sent: 0, skipped: 0, results: [], reason: "disabled" };
  const nowDate = new Date();
  const dateKey = ngDailySessionDateKey(nowDate);
  const override = ngGetLiveSessionOverrideForDate(db, dateKey, brandId);
  if (ngLiveSessionOverrideIsCancelled(override)) {
    return ngRunNoSessionRecordingFallback({ db, brandId, limit, dryRun, source, override, dateKey });
  }
  const action = ngDailyLiveSessionActionNow(settings, nowDate);
  if (!action) return { action: null, processed: 0, sent: 0, skipped: 0, results: [], reason: "not_due_now" };
  const assets = ngAylaGetSalesAssets(db);
  const templateMap = {
    daily_session_invite: settings.daily_session_invite_template_key || "daily_live_session_invite",
    five_minute_reminder: settings.session_reminder_template_key || "five_minute_reminder",
    session_link: settings.session_link_template_key || "live_session_link_now",
    post_session_recording: settings.post_session_recording_template_key || "recording_followup_after_session",
  };
  const leads = ensureCrmArray(db, "leads")
    .filter((lead) => !brandId || String(lead.brand_id || "") === String(brandId || ""))
    .filter((lead) => ngDailyLiveSessionEligibleLead(db, lead, settings))
    .slice(0, Math.max(1, Math.min(200, Number(limit || 50))));
  const results = [];
  for (const lead of leads) {
    if (ngDailyLiveSessionAlreadySent(db, lead, action, dateKey)) {
      results.push({ lead_id: lead.id, skipped: true, reason: "already_sent_today" });
      continue;
    }
    const recentCooldownMinutes = Math.max(1, Number(settings.daily_session_recent_send_cooldown_minutes || 10));
    if (ngRecentlyContactedMinutesAgo(lead, recentCooldownMinutes)) {
      results.push({ lead_id: lead.id, skipped: true, reason: "recent_outbound_cooldown", cooldown_minutes: recentCooldownMinutes });
      continue;
    }
    const channel = resolveCrmChannelForConversation({ requestedChannel: lead.current_channel || lead.last_channel || lead.source_platform || lead.platform || "whatsapp", lead, fallback: "whatsapp" });
    const latestInbound = ngLatestInbound(ngLeadConversationMessages(db, lead.id));
    const whatsappWindowOpen = channel !== "whatsapp" || ngWithinHours(latestInbound?.created_at || latestInbound?.received_at || latestInbound?.timestamp, 24);
    const templateId = channel === "whatsapp" && !whatsappWindowOpen ? templateMap[action] : null;
    const text = ngDailyLiveSessionText(action, assets, lead);
    if (dryRun) {
      results.push({ lead_id: lead.id, dry_run: true, action, template_id: templateId, text });
      continue;
    }
    try {
      const result = await sendCrmMessage({
        db,
        brandId: lead.brand_id || brandId || db.settings?.default_brand_id || null,
        channel,
        to: getBestRecipientForChannel({ channel, lead }),
        text,
        templateId,
        templateVariables: {
          lead,
          student_name: ng41LeadName(lead) || "Doctor",
          exam_type: ng41LeadExamType(lead) || "USMLE",
          session_time: assets.sessionTime,
          live_session_link: assets.liveSessionLink,
          recording_link: assets.recordingLink,
          demo_link: assets.uworldLink,
        },
        leadId: lead.id,
        metadata: {
          source: "daily_live_session_scheduler",
          daily_live_session_action: action,
          daily_live_session_date: dateKey,
          template_key: templateId,
          scheduler_source: source,
        },
      });
      if (result.skipped || result.duplicate_blocked) {
        results.push({ lead_id: lead.id, skipped: true, reason: result.reason || "duplicate_message_blocked", action, template_id: templateId });
        continue;
      }
      ngUpdateNoReplyLeadStatus(db, lead);
      if (action === "daily_session_invite") { lead.last_session_invite_sent_at = nowIso(); lead.live_session_invited = true; ngEnsureLeadFlowLabels(lead, ["daily_session_invited", "live_session_invited"]); }
      if (action === "five_minute_reminder") { lead.last_session_reminder_sent_at = nowIso(); lead.five_min_reminder_sent = true; ngEnsureLeadFlowLabels(lead, ["five_min_reminder_sent"]); }
      if (action === "session_link") { lead.last_session_link_sent_at = nowIso(); lead.session_link_sent = true; ngEnsureLeadFlowLabels(lead, ["session_link_sent"]); }
      if (action === "post_session_recording") {
        lead.last_recording_followup_sent_at = nowIso();
        lead.recording_followup_sent_once = true;
        lead.recording_sent = true;
        ngEnsureLeadFlowLabels(lead, ["recording_sent"]);
      }
      lead.next_action = action === "post_session_recording" ? "await_recording_feedback_or_google_meet_interest" : "daily_live_session_flow";
      lead.updated_at = nowIso();
      ng41EnsureDailySessionRecovery(db, lead);
      results.push({ lead_id: lead.id, sent: Boolean(result.success || result.queued), action, template_id: templateId, message_id: result.log?.id || null });
    } catch (error) {
      results.push({ lead_id: lead.id, sent: false, error: error.message, action, template_id: templateId });
    }
  }
  return { action, processed: results.length, sent: results.filter((r) => r.sent).length, skipped: results.filter((r) => r.skipped).length, results };
}



function ngGoogleMeetAppointmentDateTime(appointment = {}) {
  const date = normalizeCrmString(appointment.date || appointment.appointment_date || appointment.scheduled_date || "");
  const time = normalizeCrmString(appointment.time || appointment.appointment_time || appointment.scheduled_time || "");
  const start = normalizeCrmString(appointment.start_time || appointment.starts_at || appointment.scheduled_at || "");
  if (start) {
    const d = new Date(start);
    if (!Number.isNaN(d.getTime())) return d;
  }
  if (date && time) {
    const d = new Date(`${date}T${time.length === 5 ? `${time}:00` : time}`);
    if (!Number.isNaN(d.getTime())) return d;
  }
  return null;
}

function ngGoogleMeetAppointmentLink(appointment = {}) {
  return normalizeCrmString(
    appointment.google_meet_link ||
    appointment.meeting_link ||
    appointment.zoom_link ||
    appointment.join_url ||
    appointment.location ||
    appointment.booking_link ||
    ""
  );
}

function ngGoogleMeetAppointmentLead(db = {}, appointment = {}) {
  return appointment.lead_id ? getLeadByAnyId(db, appointment.lead_id) : null;
}

function ngGoogleMeetAppointmentStudentName(db = {}, appointment = {}) {
  const lead = ngGoogleMeetAppointmentLead(db, appointment);
  return normalizeCrmString(
    appointment.student_name || appointment.lead_name || appointment.name ||
    lead?.student_name || lead?.lead_name || lead?.name || lead?.full_name ||
    "Doctor"
  ) || "Doctor";
}

function ngGoogleMeetAppointmentDisplayDate(appointment = {}) {
  const rawDate = normalizeCrmString(appointment.date || appointment.scheduled_date || String(appointment.start_time || "").slice(0, 10));
  if (!rawDate) return "the selected date";
  const parsed = new Date(`${rawDate}T12:00:00`);
  if (Number.isNaN(parsed.getTime())) return rawDate;
  return parsed.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });
}

function ngGoogleMeetAppointmentDisplayTime(appointment = {}) {
  const rawTime = normalizeCrmString(appointment.time || appointment.scheduled_time || String(appointment.start_time || "").slice(11, 16));
  if (!rawTime) return "";
  const match = rawTime.match(/^(\d{1,2})(?::(\d{2}))?/);
  if (!match) return rawTime;
  let hour = Number(match[1]);
  const minute = String(match[2] || "00").padStart(2, "0");
  if (!Number.isFinite(hour)) return rawTime;
  const suffix = hour >= 12 ? "PM" : "AM";
  const hour12 = hour % 12 || 12;
  return `${hour12}:${minute} ${suffix}`;
}

function ngGoogleMeetAppointmentDisplayDateTime(appointment = {}, timezone = "EST") {
  const date = ngGoogleMeetAppointmentDisplayDate(appointment);
  const time = ngGoogleMeetAppointmentDisplayTime(appointment);
  return `${date}${time ? ` at ${time} ${timezone}` : ""}`;
}

function ngGoogleMeetAppointmentText(action = "link_now", appointment = {}, db = {}) {
  const name = ngGoogleMeetAppointmentStudentName(db, appointment);
  const link = ngGoogleMeetAppointmentLink(appointment);
  const displayDateTime = ngGoogleMeetAppointmentDisplayDateTime(appointment, "EST");
  if (action === "confirmation") {
    return `Great Doctor, your Google Meet mentor consultation is confirmed for ${displayDateTime}.\n\nWe’ll share the Google Meet link at the meeting time.`;
  }
  if (action === "five_minute_reminder") {
    return `Doctor, your Google Meet mentor consultation starts in 5 minutes.\n\nPlease be ready. I will send the Google Meet link at the meeting time.`;
  }
  return `Doctor, your Google Meet mentor consultation is starting now.\n\nPlease join here:\n${link}`;
}

function ngGoogleMeetAppointmentAlreadySent(db = {}, appointment = {}, action = "") {
  return ensureCrmArray(db, "message_logs").some((log) => {
    return String(log.metadata?.google_meet_appointment_id || "") === String(appointment.id || "") &&
      String(log.metadata?.google_meet_action || "") === String(action || "") &&
      !["failed", "error"].includes(String(log.status || ""));
  });
}

async function ngSendGoogleMeetAppointmentMessage({ db = {}, appointment = {}, action = "link_now", brandId = null, dryRun = false } = {}) {
  const lead = ngGoogleMeetAppointmentLead(db, appointment);
  const channel = resolveCrmChannelForConversation({
    requestedChannel: appointment.channel || lead?.current_channel || lead?.last_channel || lead?.source_platform || lead?.platform || "whatsapp",
    lead,
    fallback: "whatsapp",
  });
  const latestInbound = lead ? ngLatestInbound(ngLeadConversationMessages(db, lead.id)) : null;
  const whatsappWindowOpen = channel !== "whatsapp" || ngWithinHours(latestInbound?.created_at || latestInbound?.received_at || latestInbound?.timestamp, 24);
  const settings = ngAylaPickSettings(db);
  const templateMap = {
    confirmation: settings.google_meet_confirmation_template_key || "google_meet_confirmation",
    five_minute_reminder: settings.google_meet_5min_reminder_template_key || "google_meet_5min_reminder",
    link_now: settings.google_meet_link_now_template_key || "google_meet_link_now",
  };
  const templateId = channel === "whatsapp" && !whatsappWindowOpen ? templateMap[action] : null;
  const text = ngGoogleMeetAppointmentText(action, appointment, db);
  if (dryRun) return { dry_run: true, text, template_id: templateId, channel };
  const result = await sendCrmMessage({
    db,
    brandId: appointment.brand_id || brandId || lead?.brand_id || db.settings?.default_brand_id || null,
    channel,
    to: getBestRecipientForChannel({ channel, lead }) || appointment.phone || appointment.student_phone || appointment.email || appointment.student_email || "",
    text,
    templateId,
    templateVariables: {
      lead,
      appointment,
      student_name: ngGoogleMeetAppointmentStudentName(db, appointment),
      google_meet_link: ngGoogleMeetAppointmentLink(appointment),
      appointment_date: appointment.date || appointment.scheduled_date || String(appointment.start_time || "").slice(0, 10),
      appointment_time: appointment.time || appointment.scheduled_time || String(appointment.start_time || "").slice(11, 16),
      appointment_display_date: ngGoogleMeetAppointmentDisplayDate(appointment),
      appointment_display_time: ngGoogleMeetAppointmentDisplayTime(appointment),
      appointment_display_datetime: ngGoogleMeetAppointmentDisplayDateTime(appointment, "EST"),
    },
    leadId: appointment.lead_id || lead?.id || null,
    metadata: {
      source: "google_meet_command_center",
      google_meet_action: action,
      google_meet_appointment_id: appointment.id || null,
      template_key: templateId,
    },
  });
  return { sent: true, message_id: result.log?.id || null, template_id: templateId, channel };
}

async function ngRunGoogleMeetAppointmentScheduler({ db = {}, brandId = null, limit = 50, dryRun = false, source = "run_due" } = {}) {
  const now = new Date();
  const items = ensureCrmArray(db, "appointments")
    .filter((item) => !brandId || String(item.brand_id || "") === String(brandId || ""))
    .filter((item) => ["scheduled", "rescheduled", "missing_link", "needs_link", "link_ready"].includes(String(item.status || "scheduled").toLowerCase()))
    .filter((item) => String(item.appointment_type || item.type || "").toLowerCase().includes("google") || String(item.appointment_type || item.type || "").toLowerCase().includes("mentor") || item.google_meet_requested || item.link_send_scheduled || item.google_meet_link_send_scheduled)
    .slice(0, Math.max(1, Math.min(200, Number(limit || 50))));
  const results = [];
  for (const item of items) {
    const start = ngGoogleMeetAppointmentDateTime(item);
    const link = ngGoogleMeetAppointmentLink(item);
    if (!start) { results.push({ appointment_id: item.id, skipped: true, reason: "missing_time" }); continue; }
    const minutesUntil = (start.getTime() - now.getTime()) / 60000;
    const actions = [];
    const reminderMinutes = Number(item.reminder_minutes_before || item.google_meet_reminder_minutes || 5);
    if (link && item.google_meet_reminder_scheduled !== false && minutesUntil <= reminderMinutes && minutesUntil > 0 && !item.google_meet_5min_reminder_sent_at && !ngGoogleMeetAppointmentAlreadySent(db, item, "five_minute_reminder")) {
      actions.push("five_minute_reminder");
    }
    if (link && (item.link_send_scheduled || item.google_meet_link_send_scheduled || item.schedule_link_send_at_meeting_time) && minutesUntil <= 0 && minutesUntil >= -30 && !item.google_meet_link_sent_at && !ngGoogleMeetAppointmentAlreadySent(db, item, "link_now")) {
      actions.push("link_now");
    }
    if (!actions.length) { results.push({ appointment_id: item.id, skipped: true, reason: link ? "not_due" : "missing_link" }); continue; }
    for (const action of actions) {
      try {
        const sent = await ngSendGoogleMeetAppointmentMessage({ db, appointment: item, action, brandId, dryRun });
        if (!dryRun) {
          if (action === "five_minute_reminder") item.google_meet_5min_reminder_sent_at = nowIso();
          if (action === "link_now") {
            item.google_meet_link_sent_at = nowIso();
            item.link_send_status = "sent";
          }
          item.last_google_meet_action_at = nowIso();
          item.updated_at = nowIso();
        }
        results.push({ appointment_id: item.id, action, ...sent });
      } catch (error) {
        results.push({ appointment_id: item.id, action, sent: false, error: error.message });
      }
    }
  }
  return { processed: results.length, sent: results.filter((r) => r.sent).length, results, source };
}

function ngGoogleMeetCommandCenterQueues(db = {}, brandId = null) {
  const appointments = ensureCrmArray(db, "appointments")
    .filter((item) => !brandId || String(item.brand_id || "") === String(brandId || ""));
  const leads = ensureCrmArray(db, "leads")
    .filter((item) => !brandId || String(item.brand_id || "") === String(brandId || ""));
  const hotQueue = ensureCrmArray(db, "hot_call_queue")
    .filter((item) => !brandId || String(item.brand_id || "") === String(brandId || ""));
  const handoffs = ensureCrmArray(db, "handoffs")
    .filter((item) => !brandId || String(item.brand_id || "") === String(brandId || ""));

  const leadById = new Map(leads.map((lead) => [String(lead.id || lead._id || ""), lead]));
  const activeAppointmentsByLead = new Map();
  appointments.forEach((appointment) => {
    const leadId = String(appointment.lead_id || "");
    if (!leadId) return;
    const status = String(appointment.status || "").toLowerCase();
    const typeBlob = [appointment.appointment_type, appointment.type, appointment.title, appointment.name, appointment.source].join(" ").toLowerCase();
    const isGoogle = typeBlob.includes("google") || typeBlob.includes("mentor") || appointment.google_meet_requested;
    if (!isGoogle || ["completed", "attended", "done", "cancelled", "canceled", "converted"].includes(status)) return;
    const previous = activeAppointmentsByLead.get(leadId);
    if (!previous || String(appointment.updated_at || appointment.created_at || "") > String(previous.updated_at || previous.created_at || "")) {
      activeAppointmentsByLead.set(leadId, appointment);
    }
  });

  const makeRequest = (sourceItem, source = "lead") => {
    const leadId = String(sourceItem.lead_id || sourceItem.leadId || sourceItem.id || sourceItem._id || "");
    const lead = leadById.get(leadId) || (source === "lead" ? sourceItem : null) || {};
    const appointment = activeAppointmentsByLead.get(leadId) || null;
    const name = sourceItem.lead_name || sourceItem.student_name || sourceItem.name || ng41LeadName(lead) || appointment?.student_name || "Student";
    const phone = sourceItem.phone || sourceItem.whatsapp || sourceItem.student_phone || sourceItem.lead_phone || ng41LeadPhone(lead) || appointment?.phone || appointment?.student_phone || "";
    const email = sourceItem.email || sourceItem.student_email || sourceItem.lead_email || ng41LeadEmail(lead) || appointment?.email || appointment?.student_email || "";
    return {
      id: `${source}_${leadId || sourceItem.id || uuid()}`,
      type: source,
      lead_id: leadId,
      appointment_id: appointment?.id || sourceItem.appointment_id || sourceItem.google_meet_appointment_id || lead.google_meet_appointment_id || null,
      name,
      student_name: name,
      phone,
      whatsapp: phone,
      email,
      status: appointment?.status || sourceItem.status || lead.stage || lead.lead_stage || "pending_google_meet_booking",
      date: appointment?.date || appointment?.scheduled_date || sourceItem.date || sourceItem.scheduled_date || lead.google_meet_date || "",
      time: appointment?.time || appointment?.scheduled_time || sourceItem.time || sourceItem.scheduled_time || lead.google_meet_time || "",
      meeting_link: ngGoogleMeetAppointmentLink(appointment || {}) || "",
      link_status: appointment?.link_status || (ngGoogleMeetAppointmentLink(appointment || {}) ? "ready" : "missing_link"),
      source,
      raw: { ...lead, ...sourceItem, appointment },
    };
  };

  const rawRequests = [];
  leads.forEach((lead) => {
    const blob = JSON.stringify(lead || {}).toLowerCase();
    if (blob.includes("google_meet") || blob.includes("mentor_requested") || blob.includes("schedule_google_meet") || activeAppointmentsByLead.has(String(lead.id || ""))) rawRequests.push(makeRequest(lead, "lead"));
  });
  hotQueue.forEach((item) => {
    if (String(item.request_type || item.status || item.reason || "").toLowerCase().includes("google") || String(item.next_best_action || "").toLowerCase().includes("google")) rawRequests.push(makeRequest(item, "queue"));
  });
  handoffs.forEach((item) => {
    if (String(item.handoff_type || item.requested_action || item.status || "").toLowerCase().includes("google")) rawRequests.push(makeRequest(item, "handoff"));
  });

  const deduped = new Map();
  rawRequests.forEach((item) => {
    const key = String(item.lead_id || item.phone || item.email || item.id);
    const existing = deduped.get(key);
    if (!existing) deduped.set(key, item);
    else {
      deduped.set(key, {
        ...existing,
        ...item,
        name: existing.name !== "Student" ? existing.name : item.name,
        student_name: existing.student_name !== "Student" ? existing.student_name : item.student_name,
        phone: existing.phone || item.phone,
        whatsapp: existing.whatsapp || item.whatsapp,
        email: existing.email || item.email,
        appointment_id: existing.appointment_id || item.appointment_id,
        meeting_link: existing.meeting_link || item.meeting_link,
        date: existing.date || item.date,
        time: existing.time || item.time,
      });
    }
  });

  const requests = Array.from(deduped.values()).sort((a, b) => String(b.raw?.updated_at || b.raw?.created_at || "").localeCompare(String(a.raw?.updated_at || a.raw?.created_at || "")));
  const googleAppointments = appointments.filter((item) => {
    const typeBlob = [item.appointment_type, item.type, item.title, item.name, item.source].join(" ").toLowerCase();
    return typeBlob.includes("google") || typeBlob.includes("mentor") || item.google_meet_requested || item.google_meet_link_send_scheduled || item.link_send_scheduled;
  });

  return {
    requests,
    appointments: googleAppointments,
    missing_link: googleAppointments.filter((item) => !ngGoogleMeetAppointmentLink(item) && ["scheduled", "rescheduled", "missing_link", "needs_link"].includes(String(item.status || "").toLowerCase() || "scheduled")),
    link_ready: googleAppointments.filter((item) => ngGoogleMeetAppointmentLink(item) && !item.google_meet_link_sent_at),
    sent: googleAppointments.filter((item) => item.google_meet_link_sent_at),
  };
}

