// NEXTGEN v12 COMMUNITY CONTENT ENGINE
// Platform-wide weekly content calendar, clean professional formatting, Reddit
// adapter placeholder/OAuth support, contextual replies, and cost guardrails.
// This section intentionally overrides selected v11 helpers without changing
// LMS, CRM, Telegram, WhatsApp, Email, AI Training, or approval flows.
// -----------------------------------------------------------------------------

const NG_WEEKLY_CONTENT_CALENDAR = [
  {
    day: "monday",
    content_type: "daily_mcq",
    label: "Daily UWorld-style MCQ",
    split_answer: true,
    default_time: "10:00",
    answer_delay_hours: 4,
  },
  {
    day: "tuesday",
    content_type: "first_aid_retention_tip",
    label: "First Aid retention tip",
    split_answer: false,
    default_time: "10:00",
  },
  {
    day: "wednesday",
    content_type: "nbme_mistake_breakdown",
    label: "NBME mistake breakdown",
    split_answer: false,
    default_time: "10:00",
  },
  {
    day: "thursday",
    content_type: "poll_exam_weak_area",
    label: "Poll: exam date / weak area",
    split_answer: false,
    default_time: "10:00",
  },
  {
    day: "friday",
    content_type: "mini_case",
    label: "Mini case + explanation",
    split_answer: true,
    default_time: "10:00",
    answer_delay_hours: 4,
  },
  {
    day: "saturday",
    content_type: "study_strategy_old_graduate",
    label: "Study strategy / old graduate guidance",
    split_answer: false,
    default_time: "10:00",
  },
  {
    day: "sunday",
    content_type: "soft_demo_invite",
    label: "Soft free 2-day LMS demo invite",
    split_answer: false,
    default_time: "10:00",
  },
];

function ngNormalizeContentType(value = "daily_mcq") {
  return String(value || "daily_mcq")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "") || "daily_mcq";
}

function ngPostRequiresAnswerFollowup(type = "", post = {}) {
  const t = ngNormalizeContentType(type || post.content_type || post.post_type);
  if (String(post.post_kind || "").toLowerCase() === "answer") return false;
  return ["daily_mcq", "mcq", "uworld_style_mcq", "mini_case", "mini_case_question", "case_question"].includes(t);
}

function ngPostIsAnswer(post = {}) {
  const t = ngNormalizeContentType(post.content_type || post.post_type);
  return String(post.post_kind || "").toLowerCase() === "answer" || t.includes("answer") || t.includes("explanation_followup");
}

function ngContentTypeIsStandaloneAnswer(type = "") {
  const t = ngNormalizeContentType(type);
  return [
    "answer",
    "answers",
    "answer_explanation",
    "explanation",
    "explanation_answer",
    "answer_followup",
    "explanation_followup",
  ].includes(t) || (t.includes("answer") && !["question_answer_pair"].includes(t));
}

function ngWeeklyCalendarItemForIndex(index = 0, roadmap = {}) {
  const rawCustom = Array.isArray(roadmap.content_mix)
    ? roadmap.content_mix.map(ngNormalizeContentType).filter(Boolean)
    : [];

  // answer_explanation is never allowed as a standalone day in the roadmap.
  // It is a paired follow-up created automatically only when the main post is
  // an MCQ/mini-case question. This prevents Day 2/Day 3 from becoming an
  // answer-only post with no question.
  const custom = rawCustom.filter((type) => !ngContentTypeIsStandaloneAnswer(type));
  const oldMcqOnlyDefault = rawCustom.length === 2 && rawCustom.includes("daily_mcq") && rawCustom.includes("answer_explanation");
  const useCustom = custom.length && !oldMcqOnlyDefault;

  if (useCustom) {
    const contentType = custom[index % custom.length];
    return {
      day: `day_${index + 1}`,
      content_type: contentType,
      label: ngContentTypeLabel(contentType),
      split_answer: ngPostRequiresAnswerFollowup(contentType),
      default_time: roadmap.post_time || roadmap.question_time || "10:00",
      answer_delay_hours: Number(roadmap.answer_delay_hours || 4),
    };
  }

  return NG_WEEKLY_CONTENT_CALENDAR[index % NG_WEEKLY_CONTENT_CALENDAR.length];
}

function ngContentTypeLabel(type = "daily_mcq") {
  const t = ngNormalizeContentType(type);
  const found = NG_WEEKLY_CONTENT_CALENDAR.find((item) => item.content_type === t);
  if (found) return found.label;
  return t.split("_").map((part) => part ? part[0].toUpperCase() + part.slice(1) : "").join(" ").trim() || "Community post";
}

function ngProfessionalTextClean(text = "") {
  let clean = String(text || "");

  clean = clean
    .replace(/\*\*/g, "")
    .replace(/\*/g, "")
    .replace(/^#{1,6}\s*/gm, "")
    .replace(/`{1,3}/g, "")
    .replace(/__([^_]+)__/g, "$1")
    .replace(/^\s*>\s?/gm, "")
    .replace(/^\s*[-–—]\s*\*?/gm, "- ")
    .replace(/\bAI[-\s]?generated\b/gi, "")
    .replace(/\bAs an AI\b/gi, "")
    .replace(/\bCommunity Content on\b/gi, "")
    .replace(/\bStay tuned for more high-yield questions!?\b/gi, "")
    .replace(/\s+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  // Keep normal medical commas because they are grammatically necessary. The goal
  // is to remove raw markdown punctuation, not to damage professional sentences.
  return clean;
}

function ngCleanHeadingLine(line = "") {
  return ngProfessionalTextClean(line)
    .replace(/\s*:\s*$/g, "")
    .trim();
}

function ngStripCommunityMarkdown(text = "") {
  return ngProfessionalTextClean(text);
}

function ngLooksLikeAnswerHeader(line = "") {
  const clean = ngCleanHeadingLine(String(line || "").replace(/^[-–—\s]+/, ""));
  return /^(correct\s+answer|answer|explanation|key\s+distractor|distractor\s+explanation|why\s+the\s+other|teaching\s+point|note|community\s+post\s+version|tutor\s+explanation|suggested\s+mcq|medical\s+safety)/i.test(clean);
}

function ngCommunityQuestionFooter() {
  return "Reply with A, B, C, D, or E. The answer and explanation will be posted later.";
}

function ngExtractQuestionOnlyContent(text = "") {
  const clean = ngProfessionalTextClean(text);
  const lines = clean.split("\n");
  const kept = [];
  for (const line of lines) {
    if (ngLooksLikeAnswerHeader(line)) break;
    kept.push(line);
  }
  let question = kept.join("\n").trim() || clean;
  question = question
    .replace(/\n?Correct\s+Answer\s*:[\s\S]*$/i, "")
    .replace(/\n?Answer\s*:[\s\S]*$/i, "")
    .replace(/\n?Explanation\s*:[\s\S]*$/i, "")
    .trim();
  const footer = ngCommunityQuestionFooter();
  if (!question.toLowerCase().includes(footer.toLowerCase())) question = `${question}\n\n${footer}`.trim();
  return ngProfessionalTextClean(question);
}

function ngExtractAnswerOnlyContent(text = "") {
  const clean = ngProfessionalTextClean(text);
  const answerIndex = clean.search(/(^|\n)(Correct\s+Answer|Answer\s*:|Explanation\s*:)/i);
  const answer = (answerIndex >= 0 ? clean.slice(answerIndex).trim() : clean) || clean;
  return ngProfessionalTextClean(answer);
}

function ngFormatCommunityGeneratedContent(text = "", { answerOnly = false, contentType = "daily_mcq", post = null } = {}) {
  const t = ngNormalizeContentType(contentType || post?.content_type || post?.post_type);
  const family = ngContentTypeFamily(t);
  if (answerOnly || ngPostIsAnswer(post || { content_type: t })) return ngExtractAnswerOnlyContent(text);
  if (ngPostRequiresAnswerFollowup(t, post || {})) return ngExtractQuestionOnlyContent(text);
  return ngCleanNonQuestionCommunityContent(text, { contentType: t, family });
}

function ngPlatformTextLimit(platform = "telegram") {
  const p = ngCommunityPlatform(platform || "telegram");
  if (p === "whatsapp") return 1800;
  if (p === "telegram") return 3900;
  if (p === "reddit") return 9500;
  if (p === "facebook" || p === "instagram") return 2200;
  return 3000;
}

function ngFormatForPlatform({ platform = "telegram", post = {}, text = "" } = {}) {
  const p = ngCommunityPlatform(platform || post.platform || "telegram");
  const t = ngNormalizeContentType(post.content_type || post.post_type || "daily_mcq");
  const answerOnly = ngPostIsAnswer(post);
  let body = ngFormatCommunityGeneratedContent(text || post.message || post.draft_content || "", { answerOnly, contentType: t, post });
  const limit = ngPlatformTextLimit(p);

  if (p === "discord") {
    return body.slice(0, limit);
  }

  if (p === "whatsapp") {
    body = body
      .replace(/\n{3,}/g, "\n\n")
      .replace(/\n-\s+/g, "\n• ")
      .trim();
  }

  if (p === "reddit") {
    const titleBase = ngProfessionalTextClean(post.title || post.topic || ngContentTypeLabel(t) || "USMLE Study Post")
      .replace(/\n+/g, " ")
      .slice(0, 280);
    const bodyText = body.slice(0, limit);
    return { title: titleBase || "USMLE Study Post", body: bodyText };
  }

  return body.slice(0, limit);
}


function ngScheduledPostIsQuestion(post = {}) {
  if (ngPostIsAnswer(post)) return false;
  return ngPostRequiresAnswerFollowup(post.content_type || post.post_type, post);
}

function ngExtractChoiceFromStudentText(text = "") {
  const clean = String(text || "").trim().toUpperCase();
  if (!clean) return "";
  const match = clean.match(/(?:^|\s|[\(\[])([A-E])(?:[\)\].,\s]|$)/);
  return match ? match[1] : "";
}

function ngExtractCorrectChoiceFromAnswerText(text = "") {
  const clean = String(text || "");
  const patterns = [
    /correct\s+answer\s*[:\-]?\s*([A-E])/i,
    /answer\s*[:\-]?\s*([A-E])/i,
    /\b([A-E])\s*(?:is|=)\s*(?:the\s+)?correct/i,
  ];
  for (const pattern of patterns) {
    const match = clean.match(pattern);
    if (match?.[1]) return String(match[1]).toUpperCase();
  }
  return "";
}

function ngTelegramMessageIdFromResult(item = {}) {
  const candidates = [
    item?.message_id,
    item?.result?.message_id,
    item?.result?.result?.message_id,
    item?.result?.telegram?.message_id,
    item?.provider_message_id,
    item?.platform_message_id,
  ];
  for (const value of candidates) {
    const clean = String(value || "").trim();
    if (clean) return clean;
  }
  return "";
}

function ngTelegramChatIdFromResult(item = {}) {
  const candidates = [
    item?.target?.telegram_chat_id,
    item?.target?.chat_id,
    item?.target?.to,
    item?.target?.recipient,
    item?.result?.result?.chat?.id,
    item?.result?.chat?.id,
    item?.telegram_chat_id,
    item?.chat_id,
  ];
  for (const value of candidates) {
    const clean = ngNormalizeTelegramChatId(value || "", { assumeGroup: true });
    if (clean) return clean;
  }
  return "";
}

function ngPostWasSentToTelegramChat(post = {}, chatId = "") {
  const targetChat = ngNormalizeTelegramChatId(chatId || "", { assumeGroup: true });
  if (!targetChat) return false;
  const results = Array.isArray(post.publish_results) ? post.publish_results : [];
  return results.some((item) => {
    const platform = ngCommunityPlatform(item.platform || item.target?.platform || "");
    if (platform !== "telegram") return false;
    if (item.success !== true && !item.result?.skipped) return false;
    return ngTelegramChatIdFromResult(item) === targetChat;
  });
}

function ngPostWasSentAsTelegramMessage(post = {}, messageId = "") {
  const targetMessageId = String(messageId || "").trim();
  if (!targetMessageId) return false;
  const results = Array.isArray(post.publish_results) ? post.publish_results : [];
  return results.some((item) => {
    const platform = ngCommunityPlatform(item.platform || item.target?.platform || "");
    if (platform !== "telegram") return false;
    return ngTelegramMessageIdFromResult(item) === targetMessageId;
  });
}

function ngFindActiveQuestionPostForTelegramMessage(db, message = {}) {
  const posts = ngContentArray(db, "community_scheduled_posts");
  const chatId = ngNormalizeTelegramChatId(message?.chat?.id || "", { assumeGroup: true });
  const replyToMessageId = String(message?.reply_to_message?.message_id || "").trim();
  if (replyToMessageId) {
    const replyMatched = posts.find((post) => ngScheduledPostIsQuestion(post) && ngPostPublished(post) && ngPostWasSentAsTelegramMessage(post, replyToMessageId));
    if (replyMatched) return replyMatched;
  }
  if (!chatId) return null;
  const nowMs = Date.now();
  const activeWindowHours = Number(process.env.COMMUNITY_RESPONSE_WINDOW_HOURS || 8);
  const activeWindowMs = Math.max(1, activeWindowHours) * 60 * 60 * 1000;
  const candidates = posts
    .filter((post) => ngScheduledPostIsQuestion(post) && ngPostPublished(post) && ngPostWasSentToTelegramChat(post, chatId))
    .filter((post) => {
      const publishedAt = new Date(post.posted_at || post.updated_at || post.scheduled_at || 0).getTime();
      if (!publishedAt || Number.isNaN(publishedAt)) return true;
      return nowMs - publishedAt <= activeWindowMs;
    })
    .sort((a, b) => new Date(b.posted_at || b.updated_at || b.scheduled_at || 0).getTime() - new Date(a.posted_at || a.updated_at || a.scheduled_at || 0).getTime());
  return candidates[0] || null;
}

function ngRecordCommunityAnswerResponse(db, { post = {}, message = {}, text = "", choice = "" } = {}) {
  if (!post?.id || !choice) return null;
  const responses = ngContentArray(db, "community_post_responses");
  const chatId = ngNormalizeTelegramChatId(message?.chat?.id || "", { assumeGroup: true });
  const user = message?.from || {};
  const userId = String(user.id || message?.sender_chat?.id || "unknown");
  const messageId = String(message?.message_id || "");
  const duplicate = responses.find((item) => {
    if (messageId && String(item.platform_message_id || "") === messageId && String(item.telegram_chat_id || "") === chatId) return true;
    return String(item.scheduled_post_id || "") === String(post.id) && String(item.telegram_chat_id || "") === chatId && String(item.telegram_user_id || "") === userId && String(item.choice || "").toUpperCase() === choice && (Date.now() - new Date(item.created_at || 0).getTime()) < 2 * 60 * 1000;
  });
  if (duplicate) return duplicate;
  const record = withTimestamps({
    id: uuid(),
    scheduled_post_id: post.id,
    roadmap_id: post.roadmap_id || null,
    parent_post_id: post.parent_post_id || null,
    exam_track: post.exam_track || null,
    exam_track_label: post.exam_track ? ngExamTrackLabel(post.exam_track) : null,
    platform: "telegram",
    telegram_chat_id: chatId || null,
    telegram_user_id: userId,
    telegram_username: user.username || "",
    student_name: [user.first_name, user.last_name].filter(Boolean).join(" ") || user.username || "Telegram student",
    platform_message_id: messageId,
    choice,
    text: ngProfessionalTextClean(text).slice(0, 1000),
    created_by: "telegram_scout_webhook",
  });
  responses.push(record);
  return record;
}

function ngCommunityResponseAnalyticsForPost(db, post = {}) {
  const questionPostId = ngPostIsAnswer(post) ? (post.parent_post_id || post.question_post_id || "") : post.id;
  if (!questionPostId) return { total: 0, counts: {}, majority_choice: "", correct_choice: "" };
  const rows = ngContentArray(db, "community_post_responses").filter((item) => String(item.scheduled_post_id || "") === String(questionPostId));
  const counts = { A: 0, B: 0, C: 0, D: 0, E: 0 };
  const uniqueUsers = new Set();
  for (const row of rows) {
    const choice = String(row.choice || "").toUpperCase();
    if (counts[choice] === undefined) continue;
    counts[choice] += 1;
    if (row.telegram_user_id) uniqueUsers.add(String(row.telegram_user_id));
  }
  const entries = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  const majority = entries[0] && entries[0][1] > 0 ? entries[0][0] : "";
  const total = Object.values(counts).reduce((sum, n) => sum + Number(n || 0), 0);
  const answerText = post.message || post.draft_content || "";
  const correct = ngExtractCorrectChoiceFromAnswerText(answerText);
  return {
    total,
    unique_students: uniqueUsers.size || total,
    counts,
    majority_choice: majority,
    majority_count: majority ? counts[majority] : 0,
    correct_choice: correct,
    responses: rows.slice(-50),
  };
}

function ngBuildMajorityInsightForAnswer(db, answerPost = {}) {
  if (!ngPostIsAnswer(answerPost)) return "";
  const analytics = ngCommunityResponseAnalyticsForPost(db, answerPost);
  if (!analytics.total) return "";
  const parts = [];
  parts.push("Community response snapshot:");
  parts.push(`Many students selected ${analytics.majority_choice || "an option"} (${analytics.majority_count}/${analytics.total} responses).`);
  if (analytics.correct_choice) {
    if (analytics.majority_choice && analytics.majority_choice !== analytics.correct_choice) {
      parts.push(`Correct answer is ${analytics.correct_choice}, so the common trap was choosing ${analytics.majority_choice} before matching the key clue to the mechanism.`);
    } else {
      parts.push(`Correct answer is ${analytics.correct_choice}. Most responses were aligned with the correct option.`);
    }
  } else {
    parts.push("Use the explanation below to compare the most common answer with the correct reasoning.");
  }
  parts.push("This is a group-level summary only, not individual student tracking.");
  return parts.join("\n");
}

function ngApplyMajorityInsightToAnswerPost(db, post = {}) {
  if (!ngPostIsAnswer(post)) return post;
  const current = ngProfessionalTextClean(post.message || post.draft_content || "");
  if (!current || /community\s+response\s+snapshot/i.test(current)) return post;
  const insight = ngBuildMajorityInsightForAnswer(db, post);
  if (!insight) return post;
  const next = ngProfessionalTextClean(`${insight}\n\n${current}`);
  post.message = next;
  post.draft_content = next;
  post.response_analytics = ngCommunityResponseAnalyticsForPost(db, post);
  post.updated_at = nowIso();
  return post;
}

function ngBotMentionedInTelegramText(text = "") {
  const clean = String(text || "").toLowerCase();
  const configured = [
    process.env.TELEGRAM_SCOUT_BOT_USERNAME,
    process.env.TELEGRAM_COMMUNITY_BOT_USERNAME,
    process.env.TELEGRAM_BOT_USERNAME,
  ].filter(Boolean).map((item) => String(item).toLowerCase().replace(/^@/, ""));
  const names = new Set(["usmle_prep_partner_bot", "medical_exam_study_helper", "medical exam study helper", "study helper", ...configured]);
  for (const name of names) {
    if (!name) continue;
    if (clean.includes(`@${name}`) || clean.includes(name)) return true;
  }
  return false;
}

function ngTopicKeywordsFromPost(post = {}) {
  return String([post.topic, post.title, post.content_type].filter(Boolean).join(" "))
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((word) => word.length >= 5 && !["daily", "style", "question", "answer", "explanation", "community", "usmle", "nclex", "mccqe", "clinical"].includes(word))
    .slice(0, 12);
}

function ngTelegramCommentLooksTopicRelated(text = "", post = {}, message = {}) {
  if (!post?.id) return false;
  if (message?.reply_to_message?.message_id && ngPostWasSentAsTelegramMessage(post, message.reply_to_message.message_id)) return true;
  const clean = String(text || "").toLowerCase();
  if (ngExtractChoiceFromStudentText(clean)) return true;
  const keywords = ngTopicKeywordsFromPost(post);
  return keywords.some((word) => clean.includes(word));
}

function ngBuildLowCostTopicReply({ text = "", post = {}, choice = "" } = {}) {
  const topic = post.topic || post.title || "today's posted concept";
  const picked = choice ? `You selected ${choice}. ` : "";
  return ngProfessionalTextClean(`${picked}For this thread, I can help only with today's topic: ${topic}. Focus on the key clue in the stem, then match it with the mechanism before choosing an option. If you are confused, ask specifically about the clue, the mechanism, or why one option is wrong.`).slice(0, 900);
}


function ngContentTypeFamily(type = "daily_mcq") {
  const t = ngNormalizeContentType(type);
  if (["daily_mcq", "mcq", "uworld_style_mcq", "question", "case_question", "mini_case", "mini_case_question"].includes(t)) return "question";
  if (["answer", "answer_explanation", "explanation", "answer_followup", "explanation_followup"].includes(t) || t.includes("answer")) return "answer";
  if (["poll", "poll_exam_weak_area", "exam_poll", "weak_area_poll", "community_poll"].includes(t) || t.includes("poll")) return "poll";
  if (["strategy_tip", "study_strategy", "study_strategy_old_graduate", "exam_strategy", "tip", "study_tip"].includes(t) || t.includes("strategy") || t.includes("tip")) return "strategy";
  if (["education_post", "educational_post", "education", "teaching_post", "concept_review", "screening_recommendations", "first_aid_retention_tip", "nbme_mistake_breakdown"].includes(t) || t.includes("education") || t.includes("retention") || t.includes("breakdown")) return "education";
  if (["announcement", "soft_demo_invite", "demo_invite", "offer", "reminder"].includes(t) || t.includes("invite") || t.includes("announcement")) return "invite";
  return "education";
}

function ngContentTypeTitleForExam(type = "daily_mcq", trackOrExam = "") {
  const family = ngContentTypeFamily(type);
  const profile = ngExamGenerationProfile(trackOrExam);
  if (family === "question") return profile.title;
  if (family === "poll") return `${profile.label} Community Poll`;
  if (family === "strategy") return `${profile.label} Strategy Tip`;
  if (family === "invite") return `${profile.label} Free Demo Invitation`;
  return `${profile.label} Education Post`;
}

function ngContentLooksLikeMcq(text = "") {
  const clean = String(text || "");
  return /(^|\n)\s*A[\).:-]/i.test(clean) && /(^|\n)\s*B[\).:-]/i.test(clean) && /(^|\n)\s*(C|D)[\).:-]/i.test(clean);
}

function ngRemoveQuestionOnlyFooter(text = "") {
  return String(text || "")
    .replace(/\n?\s*Please\s+reply\s+with\s+(?:your\s+answer\s*)?\(?A\s*[-–,]?\s*E\)?\.?\s*/gi, "")
    .replace(/\n?\s*Reply\s+with\s+A\s*,?\s*B\s*,?\s*C\s*,?\s*D\s*,?\s*(?:or\s*)?E\.?\s*/gi, "")
    .replace(/\n?\s*The\s+answer\s+and\s+explanation\s+will\s+be\s+posted\s+later\.?\s*/gi, "")
    .replace(/\n?\s*Answer\s+and\s+explanation\s+will\s+be\s+posted\s+later\.?\s*/gi, "")
    .trim();
}

function ngCleanDanglingGeneratedEnding(text = "") {
  let clean = ngProfessionalTextClean(text);
  clean = clean
    .replace(/\s+(?:The|A|An|This|These|Those|Because|Therefore|Additionally|However|And|But)\s*$/i, "")
    .replace(/\s+\b(?:the|a|an|this|because)\s*$/i, "")
    .replace(/[\s.]*\b(?:The|A|An|This|These|Those|Because|Therefore|Additionally|However|And|But)\s*$/i, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return clean;
}

function ngCleanNonQuestionCommunityContent(text = "", { contentType = "education_post" } = {}) {
  const family = ngContentTypeFamily(contentType);
  let clean = ngProfessionalTextClean(text);

  clean = clean
    .replace(/\s*This\s+is\s+a\s+poll\s*,?\s*so\s+there\s+is\s+no\s+correct\s+answer\.?/gi, "")
    .replace(/\s*There\s+is\s+no\s+correct\s+answer\s*(?:for\s+this\s+poll)?\.?/gi, "")
    .replace(/\s*No\s+correct\s+answer\s*(?:for\s+this\s+poll)?\.?/gi, "")
    .replace(/\s*This\s+poll\s+has\s+no\s+correct\s+answer\.?/gi, "")
    .replace(/\s*so\s+there\s+is\s+no\s+correct\s+answer\.?/gi, "")
    .replace(/\s*Answer\s+and\s+explanation\s+will\s+be\s+posted\s+later\.?/gi, "")
    .replace(/\s*The\s+answer\s+and\s+explanation\s+will\s+be\s+posted\s+later\.?/gi, "")
    .replace(/\s*Correct\s+Answer\s*:[\s\S]*$/i, "")
    .replace(/\s*Correct\s+answer\s*:[\s\S]*$/i, "");

  if (family !== "question" && family !== "poll") {
    clean = clean
      .replace(/\n\s*Reply\s+with\s+A\s*,?\s*B\s*,?\s*C\s*,?\s*D\s*,?\s*(?:or\s*)?E\.?/gi, "")
      .replace(/\n\s*Vote\s+with\s+A\s*,?\s*B\s*,?\s*C\s*,?\s*D\s*,?\s*(?:or\s*)?E\.?/gi, "");
  }

  clean = clean
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[\s.]*\b(?:The|A|An|This|These|Those|Because|Therefore|Additionally|However|And|But)\s*$/i, "")
    .trim();

  if (family === "poll" && clean.length > 0 && !/\b(vote|reply|choose|select)\b/i.test(clean)) {
    clean = `${clean}\n\nReply with your choice and share what you want reviewed next.`;
  }

  return ngCleanDanglingGeneratedEnding(clean);
}

function ngContentBuildFallbackFromSources({ type = "daily_mcq", topic = "Medical exam concept", sources = [], exam = "Step 1", exam_track = "", answerOnly = false } = {}) {
  const t = ngNormalizeContentType(type);
  const family = ngContentTypeFamily(t);
  const key = ngNormalizeExamTrack(exam_track || exam, "usmle_step1") || "usmle_step1";
  const profile = ngExamGenerationProfile(key);
  const cleanTopic = ngContentClean(topic || profile.label, profile.label);
  const sourceTitle = sources[0]?.title || sources[0]?.name || `${profile.label} template`;

  if (answerOnly || family === "answer") {
    if (key === "nclex") {
      return `Correct answer: See the priority nursing action below.\n\nExplanation:\nFor NCLEX, identify the safest nursing priority first: airway/breathing/circulation, acute risk, medication safety, infection control, delegation limits, client teaching, or escalation. The correct option is the action that protects the client now and fits nursing scope. Review why the tempting distractor is less safe or less urgent.`;
    }
    return `Correct answer: Review the ${profile.label} explanation for ${cleanTopic}.\n\nExplanation:\nThe key is to connect the stem clue with the exam task. For ${profile.label}, focus on ${profile.style}. Use ${sourceTitle} only if it matches this exam track; otherwise use the locked ${profile.label} template.`;
  }

  if (family === "question") {
    if (key === "nclex") {
      return `${profile.title}\n\nTopic: ${cleanTopic}\n\nA nurse is caring for a client with findings related to ${cleanTopic}. Which nursing action should the nurse prioritize first?\n\nA. Delay assessment until routine rounds\nB. Assess the client's immediate safety and highest-risk finding\nC. Delegate all assessment to assistive personnel\nD. Provide discharge teaching before stabilizing the client\nE. Document the finding without further action\n\n${ngCommunityQuestionFooter()}`;
    }
    if (key === "usmle_step2_ck") {
      return `${profile.title}\n\nTopic: ${cleanTopic}\n\nA patient presents with findings related to ${cleanTopic}. After initial stabilization, what is the most appropriate next step in diagnosis or management?\n\nA. Reassurance only\nB. Immediate broad intervention without confirming severity\nC. Select the next step based on the key clinical clue and acuity\nD. Ignore risk factors and treat later\nE. Choose the least urgent outpatient option\n\n${ngCommunityQuestionFooter()}`;
    }
    if (key === "mccqe") {
      return `${profile.title}\n\nTopic: ${cleanTopic}\n\nA patient in a Canadian clinical setting presents with a concern related to ${cleanTopic}. Which clinical decision is most appropriate?\n\nA. Ignore prevention and follow-up\nB. Apply a safe evidence-based approach including risk assessment and patient communication\nC. Delay care without safety-net advice\nD. Choose an intervention outside the clinical context\nE. Avoid shared decision-making\n\n${ngCommunityQuestionFooter()}`;
    }
    if (key === "amc") {
      return `${profile.title}\n\nTopic: ${cleanTopic}\n\nA patient presents in an Australian clinical setting with a problem related to ${cleanTopic}. What is the safest and most appropriate management decision?\n\nA. Discharge without assessment\nB. Escalate or manage based on acuity, safety, and clinical context\nC. Ignore public health and follow-up considerations\nD. Provide treatment unrelated to the presentation\nE. Delay urgent care until routine review\n\n${ngCommunityQuestionFooter()}`;
    }
    return `${profile.title}\n\nTopic: ${cleanTopic}\n\nA student is reviewing this concept from an approved Step 1 source. Which approach best turns this topic into a testable mechanism-based point?\n\nA. Memorize isolated facts without context\nB. Skip the mechanism and only read the answer\nC. Identify the clinical clue, mechanism, and common distractor pattern\nD. Review only the title of the topic\nE. Avoid practice questions\n\n${ngCommunityQuestionFooter()}`;
  }

  if (family === "poll") {
    return `${profile.label} Community Poll\n\nWhat should we focus on next for ${profile.label}?\n\nA. Weak topic review\nB. Question-solving strategy\nC. Time management\nD. High-yield clinical reasoning\nE. Exam-day confidence\n\nReply with A, B, C, D, or E. Vote and share what you want reviewed next.`;
  }

  if (family === "strategy") {
    return `${profile.label} Strategy Tip\n\nToday's focus: ${cleanTopic}.\n\nUse this 3-step approach:\n1. Identify the exam task first.\n2. Match the key clue to the safest or highest-yield decision.\n3. Review why the most tempting distractor is wrong.\n\nKeep your review active: write one sentence explaining the clue before moving to the next question.`;
  }

  if (family === "invite") {
    return `${profile.label} Free Demo Invitation\n\nIf you are preparing for ${profile.label}, you can request a free 2-day LMS demo to see whether the teaching style, roadmap, and community support fit your preparation. Join for a short session first, then decide whether you want guidance from a mentor.`;
  }

  return `${profile.label} Education Post\n\nTopic: ${cleanTopic}\n\nKey idea: focus on the exact exam task for ${profile.label}.\n\nWhy it matters: students often miss this topic when they memorize facts without connecting them to the clinical clue, safety issue, screening rule, or management decision.\n\nHow to review today: summarize the core point, do one related practice question, and write down the distractor that confused you most.`;
}

function ngPromptInstructionsForContentType({ type = "daily_mcq", answerOnly = false, platform = "telegram" } = {}) {
  const t = ngNormalizeContentType(type);
  const family = ngContentTypeFamily(t);
  const base = [
    "Use plain professional text only.",
    "Do not use markdown stars, hash headings, code fences, emojis, or exaggerated sales language.",
    "Do not write AI-generated or mention that an AI made the post.",
    "Keep the post educational, concise, and suitable for public medical exam communities.",
  ];

  if (answerOnly || family === "answer") {
    return [...base, "Create only the answer and explanation follow-up. Include correct answer, why it is correct, and concise distractor explanations. Do not repeat the full question unless needed."].join(" ");
  }

  if (family === "question") {
    return [...base, "Create a question post only. Include a content-appropriate title, stem, and A-E options. Do not include the correct answer, explanation, teaching point, or distractor explanations. End by asking students to reply A-E and saying the answer will be posted later."].join(" ");
  }

  if (family === "poll") {
    return [...base, "Create a true community poll, not an MCQ. It should ask about weak area, exam date, confidence, study obstacle, or what topic students want next. Use A-E or 1-5 options. Do not write any line about correct answer/no correct answer. Do not include a medical stem, diagnosis question, correct answer, explanation, or answer-will-be-posted-later line."].join(" ");
  }

  if (family === "strategy") {
    return [...base, "Create one practical strategy tip. Do not create a stem, A-E options, correct answer, or answer-will-be-posted-later line. Use 2-4 short action points."].join(" ");
  }

  if (family === "education") {
    return [...base, "Create one educational explanation post. Do not create a multiple-choice question, A-E options, correct answer, or answer-will-be-posted-later line. Use a clear key idea, why it matters, and how to review it."].join(" ");
  }

  if (family === "invite") {
    return [...base, "Create one soft invitation or announcement. Do not create a medical MCQ or answer/explanation split. Make it helpful, not pushy. Do not overpromise results."].join(" ");
  }

  return [...base, "Create one clean educational community post. Do not split into answer/explanation unless it is an MCQ or mini case."].join(" ");
}

function ngEnforceContentTypeAfterGeneration(text = "", { type = "daily_mcq", topic = "", sources = [], exam = "", exam_track = "", answerOnly = false } = {}) {
  const t = ngNormalizeContentType(type);
  const family = ngContentTypeFamily(t);
  const key = ngNormalizeExamTrack(exam_track || exam, "usmle_step1") || "usmle_step1";
  let clean = ngCleanDanglingGeneratedEnding(ngRemoveQuestionOnlyFooter(text));

  if (answerOnly || family === "answer") return ngCleanDanglingGeneratedEnding(text);

  if (family === "question") {
    return ngExtractQuestionOnlyContent(text);
  }

  const looksMcq = ngContentLooksLikeMcq(clean) || /\b(correct answer|answer and explanation will be posted later|please reply with your answer)\b/i.test(clean);
  const forcedQuestionTitle = /\bDaily\s+(USMLE|NCLEX|MCCQE|AMC).*\b(Question|MCQ|Clinical Case)\b/i.test(clean.split("\n")[0] || "");
  const tooShortOrDangling = clean.length < 80 || /\b(The|A|An|This|Because|Therefore|Additionally)\s*$/i.test(clean);

  if (family === "poll" || (family !== "question" && (looksMcq || forcedQuestionTitle || tooShortOrDangling))) {
    clean = ngContentBuildFallbackFromSources({ type: t, topic, sources, exam, exam_track: key, answerOnly: false });
  }

  clean = ngRemoveQuestionOnlyFooter(clean);
  clean = ngCleanNonQuestionCommunityContent(clean, { contentType: t });
  clean = ngCleanDanglingGeneratedEnding(clean);
  return clean;
}

async function ngGenerateContentFromApprovedSources({ db, body = {}, sources = [], answerOnly = false } = {}) {
  const type = ngNormalizeContentType(body.content_type || body.post_type || (answerOnly ? "answer_explanation" : "daily_mcq"));
  const examTrack = ngStrictExamTrackFromGenerationBody(body);
  const profile = ngExamGenerationProfile(examTrack);
  const exam = profile.label;
  const topic = ngContentClean(body.topic || body.title || `${profile.label} preparation`, `${profile.label} preparation`);
  const platform = ngCommunityPlatform(body.platform || body.channel || "telegram");
  const audience = ngContentClean(body.audience || profile.audience, profile.audience);
  const extraInstruction = ngContentClean(body.instructions || body.cta || "", "");
  const allowGeneral = body.allow_general_knowledge === true || body.ai_generated_without_source === true || body.source_mode === "ai_exam_template";

  if (!sources.length && allowGeneral !== true) {
    const error = new Error("No approved medical training source selected. Approve/select a source first, or explicitly allow general knowledge.");
    error.statusCode = 422;
    throw error;
  }

  if (!isAIConfigured()) {
    const fallback = ngContentBuildFallbackFromSources({ type, topic, sources, exam, exam_track: examTrack, answerOnly });
    const cleanedFallback = ngSanitizeGeneratedContentForExamTrack(fallback, examTrack);
    const typedFallback = ngEnforceContentTypeAfterGeneration(cleanedFallback, { type, topic, sources, exam, exam_track: examTrack, answerOnly });
    return { content: ngFormatCommunityGeneratedContent(typedFallback, { answerOnly, contentType: type }), model: "local-exam-locked-fallback", usage: {}, ai_configured: false };
  }

  const sourceContext = sources.length ? ngSourceContextForGeneration(sources) : "No approved source context selected. Use the locked exam template and standard medical knowledge only.";
  const systemPrompt = `You are NextGen Medical Exam Community Content AI. Generate original, medically careful educational content for ${profile.label}. You must obey the HARD EXAM LOCK. Never label this content as another exam. Use clean professional plain text.`;
  const userPrompt = [
    ngStrictExamInstruction(examTrack),
    ngLearningRulesPromptBlock(db, "community"),
    `Approved source context:\n${sourceContext}`,
    `Platform: ${platform}`,
    `Content type: ${type}`,
    `Hard exam track: ${examTrack}`,
    `Exam label to display: ${profile.label}`,
    `Audience: ${audience}`,
    `Topic: ${topic}`,
    `Mode: ${answerOnly ? "answer/explanation follow-up" : "community post"}`,
    `Forbidden labels/phrases for this exam: ${(profile.forbidden || []).join(", ") || "none"}`,
    `Instructions: ${extraInstruction || "Create concise, high-yield community content."}`,
    ngPromptInstructionsForContentType({ type, answerOnly, platform }),
  ].join("\n\n");

  const result = await callOpenAIResponsesAPI({
    model: getAIModel(process.env.AI_CONTENT_MODEL || "gpt-4o-mini"),
    systemPrompt,
    userPrompt,
    maxOutputTokens: answerOnly ? 1300 : 1600,
  });

  const generatedContent = result.text || ngContentBuildFallbackFromSources({ type, topic, sources, exam, exam_track: examTrack, answerOnly });
  const cleanedContent = ngSanitizeGeneratedContentForExamTrack(generatedContent, examTrack);
  const typedContent = ngEnforceContentTypeAfterGeneration(cleanedContent, { type, topic, sources, exam, exam_track: examTrack, answerOnly });
  return {
    content: ngFormatCommunityGeneratedContent(typedContent, { answerOnly, contentType: type }),
    model: result.model,
    usage: result.usage || {},
    ai_configured: true,
  };
}

function ngRedditPostingEnabled() {
  return String(process.env.REDDIT_POSTING_ENABLED || "false").trim().toLowerCase() === "true";
}

function ngRedditCredentialsReady() {
  return Boolean(process.env.REDDIT_CLIENT_ID && process.env.REDDIT_CLIENT_SECRET && process.env.REDDIT_USERNAME && process.env.REDDIT_PASSWORD);
}

let ngRedditTokenCache = { token: "", expires_at: 0 };

async function ngGetRedditAccessToken() {
  if (!ngRedditPostingEnabled()) {
    const error = new Error("Reddit posting is disabled. Set REDDIT_POSTING_ENABLED=true after Reddit API approval.");
    error.statusCode = 503;
    throw error;
  }
  if (!ngRedditCredentialsReady()) {
    const error = new Error("Reddit credentials are incomplete. Add REDDIT_CLIENT_ID, REDDIT_CLIENT_SECRET, REDDIT_USERNAME, and REDDIT_PASSWORD after Reddit approval.");
    error.statusCode = 503;
    throw error;
  }
  if (ngRedditTokenCache.token && ngRedditTokenCache.expires_at > Date.now() + 60000) return ngRedditTokenCache.token;

  const auth = Buffer.from(`${process.env.REDDIT_CLIENT_ID}:${process.env.REDDIT_CLIENT_SECRET}`).toString("base64");
  const params = new URLSearchParams();
  params.set("grant_type", "password");
  params.set("username", process.env.REDDIT_USERNAME);
  params.set("password", process.env.REDDIT_PASSWORD);

  const response = await axios.post("https://www.reddit.com/api/v1/access_token", params.toString(), {
    headers: {
      Authorization: `Basic ${auth}`,
      "Content-Type": "application/x-www-form-urlencoded",
      "User-Agent": process.env.REDDIT_USER_AGENT || `nextgen-usmle-community/1.0 by u/${process.env.REDDIT_USERNAME || "NextGenUSMLEHelper"}`,
    },
    timeout: 30000,
  });

  if (!response.data?.access_token) {
    const error = new Error("Reddit access token was not returned.");
    error.statusCode = 502;
    error.reddit_response = response.data;
    throw error;
  }

  ngRedditTokenCache = {
    token: response.data.access_token,
    expires_at: Date.now() + (Number(response.data.expires_in || 3600) * 1000),
  };
  return ngRedditTokenCache.token;
}

async function ngPostToReddit({ subreddit = "", title = "", body = "" } = {}) {
  const targetSubreddit = String(subreddit || process.env.REDDIT_DEFAULT_SUBREDDIT || "").replace(/^r\//i, "").trim();
  if (!targetSubreddit) throw Object.assign(new Error("Reddit target subreddit is missing."), { statusCode: 400 });

  const token = await ngGetRedditAccessToken();
  const params = new URLSearchParams();
  params.set("sr", targetSubreddit);
  params.set("kind", "self");
  params.set("title", ngProfessionalTextClean(title).slice(0, 280) || "USMLE Study Post");
  params.set("text", ngProfessionalTextClean(body).slice(0, 9500));
  params.set("api_type", "json");

  const response = await axios.post("https://oauth.reddit.com/api/submit", params.toString(), {
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/x-www-form-urlencoded",
      "User-Agent": process.env.REDDIT_USER_AGENT || `nextgen-usmle-community/1.0 by u/${process.env.REDDIT_USERNAME || "NextGenUSMLEHelper"}`,
    },
    timeout: 30000,
  });

  const errors = response.data?.json?.errors || [];
  if (errors.length) {
    const error = new Error(`Reddit post failed: ${errors.map((e) => e.join(" ")).join("; ")}`);
    error.statusCode = 400;
    error.reddit_response = response.data;
    throw error;
  }

  return response.data;
}



