app.post("/admin/crm/media-library/upload", async (req, res) => {
  try {
    await requireCrmAdmin(req);
    const db = await readCrmDb();
    const brandId = getCrmBrandId(req, db);
    const { mime, base64 } = ngStripDataUrl(req.body.data_url || req.body.base64 || req.body.file_base64 || "");
    if (!base64) return res.status(400).json({ success: false, error: "data_url or base64 image is required" });
    const buffer = Buffer.from(base64, "base64");
    if (!buffer.length) return res.status(400).json({ success: false, error: "Invalid base64 media" });
    await fs.mkdir(MEDIA_DIR, { recursive: true });
    const ext = ngSafeFileExtension(req.body.mime_type || mime, req.body.file_name || req.body.filename || "");
    const safeTitle = normalizeCrmString(req.body.title || req.body.name || "media").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 50) || "media";
    const fileName = `${Date.now()}-${safeTitle}-${crypto.randomBytes(4).toString("hex")}.${ext}`;
    const absPath = path.join(MEDIA_DIR, fileName);
    await fs.writeFile(absPath, buffer);
    const relativeUrl = `/media/${fileName}`;
    const publicUrl = `${ngPublicBaseUrl(req)}${relativeUrl}`;
    const asset = normalizeCrmCollectionPayload("media_assets", {
      title: req.body.title || req.body.name || fileName,
      asset_type: req.body.asset_type || req.body.type || "image",
      usage_area: req.body.usage_area || req.body.usage || "general",
      aspect_ratio: req.body.aspect_ratio || "",
      public_url: publicUrl,
      relative_url: relativeUrl,
      file_name: fileName,
      mime_type: req.body.mime_type || mime || `image/${ext}`,
      size_bytes: buffer.length,
      tags: req.body.tags || [],
      ai_send_enabled: req.body.ai_send_enabled === true || req.body.auto_send_with_ayla === true || req.body.send_when_explaining === true,
      auto_send_with_ayla: req.body.auto_send_with_ayla === true || req.body.ai_send_enabled === true,
      send_when_explaining: req.body.send_when_explaining === true || req.body.ai_send_enabled === true,
      trigger_keywords: req.body.trigger_keywords || req.body.keywords || [],
      ai_usage_context: req.body.ai_usage_context || req.body.context || req.body.description || "",
      caption_template: req.body.caption_template || req.body.caption || "",
      testimonial_category: normalizeCrmString(req.body.testimonial_category || req.body.category || "Student Feedback"),
      testimonial_quote: normalizeCrmString(req.body.testimonial_quote || req.body.quote || req.body.caption_template || req.body.caption || ""),
      student_label: normalizeCrmString(req.body.student_label || req.body.student_name || "USMLE Step 1 Student"),
      homepage_visible: req.body.homepage_visible !== false,
      is_featured: req.body.is_featured === true || req.body.featured === true,
      sort_order: Number(req.body.sort_order || 0) || 0,
      priority: Number(req.body.priority || 0) || 0,
      status: "active",
    }, null, brandId);
    ensureCrmArray(db, "media_assets").push(asset);
    await writeCrmDb(db);
    res.json({ success: true, asset, public_url: publicUrl, relative_url: relativeUrl });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});


function ngIsStudentTestimonialAsset(asset = {}) {
  const values = [
    asset.usage_area,
    asset.type,
    asset.asset_type,
    asset.ai_usage_context,
  ].map((value) => String(value || "").trim().toLowerCase());

  return values.some((value) => [
    "student_testimonial",
    "student_testimonials",
    "testimonial",
    "testimonials",
    "student_feedback",
    "homepage_testimonial",
  ].includes(value));
}

function ngPublicMediaUrl(req, asset = {}) {
  const direct = String(asset.public_url || asset.url || asset.file_url || asset.media_url || asset.image_url || "").trim();
  if (direct) return direct;

  const relative = String(asset.relative_url || "").trim();
  if (relative) return `${ngPublicBaseUrl(req)}${relative.startsWith("/") ? relative : `/${relative}`}`;

  return "";
}

function ngSanitizePublicTestimonial(req, asset = {}) {
  const imageUrl = ngPublicMediaUrl(req, asset);
  return {
    id: asset.id,
    title: asset.title || asset.name || "Student Feedback",
    category: asset.testimonial_category || asset.category || "Student Feedback",
    quote: asset.testimonial_quote || asset.quote || asset.caption_template || "",
    student_label: asset.student_label || asset.student_name || "USMLE Step 1 Student",
    image_url: imageUrl,
    public_url: imageUrl,
    aspect_ratio: asset.aspect_ratio || "9:16",
    featured: Boolean(asset.is_featured || asset.featured),
    sort_order: Number(asset.sort_order || 0) || 0,
    created_at: asset.created_at || null,
  };
}

app.get("/public/testimonials", async (req, res) => {
  try {
    const db = await readCrmDb();
    const limitRaw = Number(req.query.limit || 24);
    const limit = Number.isFinite(limitRaw) ? Math.min(Math.max(limitRaw, 1), 60) : 24;
    const category = String(req.query.category || "").trim().toLowerCase();

    const testimonials = ensureCrmArray(db, "media_assets")
      .filter((asset) => ngIsStudentTestimonialAsset(asset))
      .filter((asset) => asset.status !== "deleted" && asset.status !== "archived" && asset.status !== "inactive")
      .filter((asset) => asset.homepage_visible !== false)
      .map((asset) => ngSanitizePublicTestimonial(req, asset))
      .filter((asset) => asset.image_url)
      .filter((asset) => !category || String(asset.category || "").trim().toLowerCase() === category)
      .sort((a, b) => {
        if (a.featured !== b.featured) return a.featured ? -1 : 1;
        if (Number(a.sort_order || 0) !== Number(b.sort_order || 0)) return Number(a.sort_order || 0) - Number(b.sort_order || 0);
        return String(b.created_at || "").localeCompare(String(a.created_at || ""));
      })
      .slice(0, limit);

    const categories = Array.from(new Set(testimonials.map((item) => item.category).filter(Boolean)));

    res.json({ success: true, testimonials, categories, count: testimonials.length });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message || "Failed to load testimonials" });
  }
});


function ngIsUworldVideoLibraryAsset(asset = {}) {
  const values = [
    asset.usage_area,
    asset.type,
    asset.asset_type,
    asset.media_type,
    asset.ai_usage_context,
    asset.title,
    asset.name,
  ].map((value) => String(value || "").trim().toLowerCase());

  return values.some((value) => [
    "uworld_video_library",
    "u_world_video_library",
    "uworld library",
    "uworld video library",
    "video_library",
    "complete_uworld_mastery",
    "uworld_mastery",
  ].includes(value)) || values.some((value) => value.includes("uworld") && value.includes("video"));
}

function ngIsPublicVideoAsset(asset = {}) {
  const values = [
    asset.asset_type,
    asset.media_type,
    asset.mime_type,
    asset.file_name,
    asset.public_url,
    asset.relative_url,
  ].join(" ").toLowerCase();

  return values.includes("video/") || /\.(mp4|webm|mov)(\?|#|$)/i.test(String(asset.public_url || asset.relative_url || asset.file_name || ""));
}

function ngSanitizePublicMediaAsset(req, asset = {}) {
  const publicUrl = ngPublicMediaUrl(req, asset);
  const isVideo = ngIsPublicVideoAsset(asset);

  return {
    id: asset.id,
    title: asset.title || asset.name || "Media Asset",
    type: asset.type || asset.usage_area || "media",
    usage_area: asset.usage_area || asset.ai_usage_context || asset.type || "",
    ai_usage_context: asset.ai_usage_context || asset.usage_area || asset.type || "",
    asset_type: asset.asset_type || asset.media_type || (isVideo ? "video" : "image"),
    media_type: asset.media_type || asset.asset_type || (isVideo ? "video" : "image"),
    mime_type: asset.mime_type || "",
    public_url: publicUrl,
    url: publicUrl,
    file_url: publicUrl,
    relative_url: asset.relative_url || "",
    aspect_ratio: asset.aspect_ratio || (isVideo ? "16:9" : "auto"),
    caption_template: asset.caption_template || asset.caption || "",
    homepage_visible: asset.homepage_visible !== false,
    featured: Boolean(asset.is_featured || asset.featured),
    is_featured: Boolean(asset.is_featured || asset.featured),
    sort_order: Number(asset.sort_order || 0) || 0,
    priority: Number(asset.priority || 0) || 0,
    created_at: asset.created_at || null,
    updated_at: asset.updated_at || null,
  };
}

