app.post("/admin/crm/leads/:id/flow-status", async (req, res) => {
  try {
    await requireCrmAdmin(req);
    const db = await readCrmDb();
    const lead = getLeadByAnyId(db, req.params.id);
    if (!lead) return res.status(404).json({ success: false, error: "Lead not found" });
    const allowed = ["pending_payment", "payment_promise_date", "payment_promise_note", "payment_followup_status", "added_to_free_community", "free_community_invited", "program_explained", "website_link_sent", "demo_link_sent", "live_session_invited", "session_attended", "session_missed", "recording_sent", "google_meet_requested", "google_meet_booked", "mentor_handoff_needed", "paid", "manual_paid", "unpaid_active", "opted_out", "do_not_message", "admin_suppressed"];
    for (const key of allowed) if (req.body[key] !== undefined) lead[key] = req.body[key];
    if (req.body.labels) ngEnsureLeadFlowLabels(lead, Array.isArray(req.body.labels) ? req.body.labels : normalizeArray(req.body.labels));
    if (lead.payment_promise_date) {
      lead.pending_payment = true;
      lead.payment_followup_status = lead.payment_followup_status || "pending_payment";
      ngEnsureLeadFlowLabels(lead, ["pending_payment", "payment_promise_date", "payment_followup_due"]);
      ensureCrmArray(db, "tasks").push(normalizeCrmCollectionPayload("tasks", {
        title: `Payment follow-up: ${ng41LeadName(lead) || "Student"}`,
        description: lead.payment_promise_note || "Student promised payment. Follow up on promised date.",
        due_at: lead.payment_promise_date,
        lead_id: lead.id,
        task_type: "payment_promise_followup",
        status: "open",
        priority: "high",
      }, null, lead.brand_id || db.settings?.default_brand_id || null));
    }
    if (lead.added_to_free_community) ngEnsureLeadFlowLabels(lead, ["added_to_free_community"]);
    if (lead.paid || lead.manual_paid) {
      lead.stage = "paid_enrolled";
      lead.lead_stage = "paid_enrolled";
      lead.unpaid_active = false;
      lead.exclude_daily_live_session = true;
      ngEnsureLeadFlowLabels(lead, ["paid"]);
    }
    if (lead.opted_out || lead.do_not_message || lead.admin_suppressed) {
      lead.unsubscribe_status = "suppressed";
      lead.suppressed = true;
      ngEnsureLeadFlowLabels(lead, [lead.opted_out ? "opted_out" : "do_not_message"]);
    }
    lead.updated_at = nowIso();
    await writeCrmDb(db);
    res.json({ success: true, lead: ensureLeadIdentityFields(lead) });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});


const NEXTGEN_MASTER_MAP_TEMPLATE_KEY = "nextgen_120_day_usmle_step_1_marathon";

function ngNormalizeMasterMapSystemName(value = "") {
  const raw = String(value || "").trim();
  const clean = raw.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
  if (!clean) return "General";
  if (clean.includes("cardio") || clean.includes("heart")) return "Cardiology";
  if (clean === "msk" || clean.includes("musculoskeletal") || clean.includes("bone") || clean.includes("joint")) return "MSK";
  if (clean.includes("central nervous") || clean === "cns" || clean.includes("neuro")) return "Central Nervous System";
  if (clean.includes("repro")) return "Reproductive";
  if (clean.includes("endo")) return "Endocrinology";
  if (clean === "git" || clean.includes("gastro") || clean.includes("gi ") || clean === "gi") return "GIT";
  if (clean.includes("renal") || clean.includes("kidney")) return "Renal";
  if (clean.includes("pulm") || clean.includes("resp")) return "Pulmonology";
  if (clean.includes("immun")) return "Immunology";
  if (clean.includes("hem") || clean.includes("heme")) return "Hematology";
  if (clean.includes("psych")) return "Psychiatry";
  return raw;
}

function ngSystemOrderIndex(system = "") {
  const normalized = ngNormalizeMasterMapSystemName(system);
  const index = NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE.findIndex((item) => item === normalized);
  return index >= 0 ? index : 999;
}

function ngSafeJsonArrayFromBody(value) {
  if (Array.isArray(value)) return value;
  if (value && Array.isArray(value.rows)) return value.rows;
  if (value && Array.isArray(value.days)) return value.days;
  if (typeof value === "string") {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed;
    if (parsed && Array.isArray(parsed.rows)) return parsed.rows;
    if (parsed && Array.isArray(parsed.days)) return parsed.days;
  }
  return [];
}

function ngNormalizeMasterMapRows(value) {
  const rows = ngSafeJsonArrayFromBody(value);
  return rows.map((row, index) => {
    const dayNumber = Number(row.day_number ?? row.day ?? row.day_no ?? row.order ?? row.sequence ?? index + 1) || (index + 1);
    const system = ngNormalizeMasterMapSystemName(row.system ?? row.chapter ?? row.subject ?? row.organ_system ?? "");
    const topic = String(row.topic ?? row.daily_topic ?? row.title_topic ?? row.focus ?? row.first_aid_topics ?? row.fa_topic ?? "").trim();
    const qids = ngNormalizeQidList(row.uworld_qids ?? row.qids ?? row.question_ids ?? row.qid_list ?? row.uworld_target ?? "");
    const firstAidPages = String(row.first_aid_pages ?? row.fa_pages ?? row.pages ?? row.page_range ?? "").trim();
    const firstAidTopics = String(row.first_aid_topics ?? row.fa_topics ?? row.fa_topic ?? topic ?? "").trim();
    const lectureTitle = String(row.video_library_lecture ?? row.lecture_title ?? row.video_lecture ?? row.library_lecture ?? row.recorded_lecture ?? "").trim();
    const title = String(row.title ?? row.day_title ?? "").trim() || `${system} Day ${dayNumber} — ${topic || firstAidTopics || "Daily Review"}`;
    return {
      ...row,
      source_index: index + 1,
      day_number: dayNumber,
      week_number: Number(row.week_number ?? row.week ?? Math.ceil(dayNumber / 7)) || Math.ceil(dayNumber / 7),
      system,
      chapter: String(row.chapter ?? system ?? "").trim() || system,
      topic,
      title,
      description: String(row.description ?? row.summary ?? "").trim(),
      first_aid_pages: firstAidPages || null,
      first_aid_topics: firstAidTopics,
      live_teaching_topic: String(row.live_teaching_topic ?? row.live_topic ?? topic ?? firstAidTopics ?? "").trim(),
      lecture_id: row.lecture_id || row.video_library_lecture_id || row.video_id || null,
      lecture_title: lectureTitle,
      video_library_lecture: lectureTitle,
      uworld_qids: qids,
      mapped_uworld_qids: qids,
      qid_count: Number(row.qid_count ?? qids.length) || qids.length,
      uworld_target: String(row.uworld_target ?? row.uworld_task ?? "").trim() || (qids.length ? `Complete mapped QIDs: ${qids.join(", ")}` : "Complete assigned mapped UWorld QIDs"),
      homework: String(row.homework ?? row.task ?? row.daily_task ?? "").trim(),
      flashcard_tags: normalizeArray(row.flashcard_tags ?? row.tags ?? [system, topic].filter(Boolean)),
      community_prompt: String(row.community_prompt ?? row.qna_prompt ?? "").trim(),
      assessment_task: String(row.assessment_task ?? row.assessment_type ?? "").trim(),
      assessment_day: row.assessment_day === true || String(row.assessment_type || "").toLowerCase().includes("assessment"),
      is_published: row.is_published !== false,
    };
  }).filter((row) => row.system && (row.topic || row.first_aid_topics || row.title || row.uworld_qids.length));
}

function ngNormalizeSystemSequence(values = []) {
  const list = Array.isArray(values) ? values : typeof values === "string" ? values.split(/[\n,>→]+/) : [];
  const normalized = list.map((item) => ngNormalizeMasterMapSystemName(item)).filter(Boolean);
  const unique = [];
  for (const item of normalized) if (!unique.includes(item)) unique.push(item);
  return unique.length ? unique : [...NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE];
}

function ngSystemOrderIndexFromSequence(system = "", sequence = NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE) {
  const normalized = ngNormalizeMasterMapSystemName(system);
  const list = ngNormalizeSystemSequence(sequence);
  const index = list.findIndex((item) => item === normalized);
  return index >= 0 ? index : 999;
}

function ngSortMasterRowsForSequence(rows = [], systemSequence = NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE) {
  return [...rows].sort((a, b) => {
    const ai = ngSystemOrderIndexFromSequence(a.system, systemSequence);
    const bi = ngSystemOrderIndexFromSequence(b.system, systemSequence);
    if (ai !== bi) return ai - bi;
    const ad = Number(a.system_day ?? a.day_in_system ?? a.source_index ?? a.day_number ?? 0) || 0;
    const bd = Number(b.system_day ?? b.day_in_system ?? b.source_index ?? b.day_number ?? 0) || 0;
    return ad - bd;
  });
}

function ngExtractMasterMapSystemSequence(body = {}, rows = []) {
  const explicit = body.system_order || body.system_sequence || body.sequence || body.systems_order;
  if (explicit) return ngNormalizeSystemSequence(explicit);
  const seen = [];
  for (const row of rows || []) {
    const system = ngNormalizeMasterMapSystemName(row.system || row.chapter || row.subject || "");
    if (system && !seen.includes(system)) seen.push(system);
  }
  return seen.length ? seen : [...NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE];
}

function ngGetStoredMasterMapItem(db, template = NEXTGEN_MASTER_MAP_TEMPLATE_KEY) {
  const store = db.roadmapMasterMaps || {};
  return store[String(template || NEXTGEN_MASTER_MAP_TEMPLATE_KEY)] || store[NEXTGEN_MASTER_MAP_TEMPLATE_KEY] || null;
}

function ngGetStoredMasterRows(db, template = NEXTGEN_MASTER_MAP_TEMPLATE_KEY) {
  const item = ngGetStoredMasterMapItem(db, template);
  return ngNormalizeMasterMapRows(item?.rows || []);
}

function ngGetStoredMasterSystemSequence(db, template = NEXTGEN_MASTER_MAP_TEMPLATE_KEY) {
  const item = ngGetStoredMasterMapItem(db, template);
  return ngNormalizeSystemSequence(item?.system_sequence || item?.system_order || NEXTGEN_STEP1_ROADMAP_SYSTEM_SEQUENCE);
}

function ngBuildStudyDates(startDateRaw, count, skipSundays = true) {
  const dates = [];
  let cursor = ngNextStudyDate(new Date(`${startDateRaw}T00:00:00`), skipSundays);
  while (dates.length < Number(count || 0)) {
    cursor = ngNextStudyDate(cursor, skipSundays);
    dates.push(dateOnly(cursor));
    cursor.setDate(cursor.getDate() + 1);
  }
  return dates;
}

function ngBuildTaskItemsForMasterDay(row = {}) {
  const base = ngBuildDefaultTaskItems(row);
  const descriptions = {
    live_attendance: "Attend the scheduled live class for this day.",
    video_library_watch: row.video_library_lecture ? `Watch: ${row.video_library_lecture}.` : "Watch the matching video-library lecture when assigned.",
    assigned_qids_completed: row.uworld_qids?.length ? `Complete QIDs: ${row.uworld_qids.join(", ")}.` : "Complete the assigned mapped QIDs.",
    weak_concepts_logged: "Log wrong QIDs or weak concepts after review.",
    flashcards_reviewed: "Review the daily review cards prepared for this topic.",
    community_confusion_post: row.community_prompt || "Post one confusing point in Community Q&A.",
    daily_task_submitted: "Submit the daily task after the study work is finished.",
    assessment_completed: row.assessment_task || "Complete the assigned assessment or correction task.",
  };
  return base.map((item) => ({ ...item, description: descriptions[item.key] || item.description || "" }));
}

function ngBuildMarathonDayFromMasterRow({ courseId, courseName, row, dayNumber, date, classTime, template }) {
  const qids = Array.isArray(row.uworld_qids) ? row.uworld_qids : ngNormalizeQidList(row.uworld_qids || row.mapped_uworld_qids || []);
  const topic = row.topic || row.first_aid_topics || row.system || "Daily Review";
  const readLine = row.first_aid_pages ? `Read assigned book pages: ${row.first_aid_pages}.` : "Read the assigned book pages for today’s topic.";
  const watchLine = row.video_library_lecture ? `Watch matching video-library lecture: ${row.video_library_lecture}.` : "Watch the matching video-library lecture if assigned.";
  const qidLine = qids.length ? `Complete mapped QIDs: ${qids.join(", ")}.` : "Complete the mapped UWorld QIDs assigned for this topic.";
  const description = row.description || `${readLine} ${watchLine} ${qidLine} Review cards and post one confusion point in Community Q&A.`;
  return {
    id: `${courseId}:day:${dayNumber}:${uuid()}`,
    course_id: courseId,
    week_number: Math.ceil(dayNumber / 7),
    day_number: dayNumber,
    date,
    system: row.system,
    chapter: row.chapter || row.system,
    system_day: row.system_day || row.day_in_system || null,
    topic,
    title: row.title || `${row.system} Day ${dayNumber} — ${topic}`,
    description,
    first_aid_pages: row.first_aid_pages || null,
    first_aid_topics: row.first_aid_topics || topic,
    live_teaching_topic: row.live_teaching_topic || topic,
    lecture_id: row.lecture_id || null,
    lecture_title: row.lecture_title || row.video_library_lecture || "",
    video_library_lecture: row.video_library_lecture || row.lecture_title || "",
    uworld_qids: qids,
    mapped_uworld_qids: qids,
    qid_count: qids.length,
    uworld_target: row.uworld_target || (qids.length ? `Complete mapped QIDs: ${qids.join(", ")}` : "Complete assigned mapped UWorld QIDs"),
    resources: Array.isArray(row.resources) && row.resources.length ? row.resources : ["Assigned book pages", "Mapped UWorld QIDs", "Live class", "Video Library", "Class notes", "Review cards", "Community Q&A"],
    resource_links: Array.isArray(row.resource_links) ? row.resource_links : [],
    homework: row.homework || `${readLine} ${watchLine} ${qidLine}`,
    task_items: ngBuildTaskItemsForMasterDay(row),
    flashcard_tags: row.flashcard_tags || [row.system, topic].filter(Boolean),
    community_prompt: row.community_prompt || "Post one confusing concept from today’s topic.",
    assessment_task: row.assessment_task || "",
    assessment_day: Boolean(row.assessment_day),
    class_time: classTime,
    status: "scheduled",
    roadmap_status: "scheduled",
    is_published: row.is_published !== false,
    source_master_map_index: row.source_index || null,
    template,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
}

function ngRoadmapDayIsNoClass(day = {}) {
  const status = String(day.status || day.roadmap_status || "").trim().toLowerCase();
  return status === "holiday" || status === "cancelled" || day.is_schedule_placeholder === true;
}

function ngRoadmapCourseId(roadmap = {}) {
  return String(roadmap.course_id || roadmap.courseId || "").trim();
}

function ngRoadmapClassTime(roadmap = {}, day = {}) {
  return String(
    day.class_time ||
    day.scheduled_time ||
    roadmap.class_time ||
    roadmap.settings?.class_time ||
    "13:00"
  ).trim() || "13:00";
}

function ngRoadmapTimezone(roadmap = {}, day = {}) {
  return String(
    day.scheduled_timezone ||
    roadmap.scheduled_timezone ||
    roadmap.timezone ||
    roadmap.settings?.timezone ||
    DEFAULT_TIMEZONE
  ).trim() || DEFAULT_TIMEZONE;
}

function ngBuildLiveSessionTitleFromRoadmap(db, roadmap = {}, day = {}) {
  const courseId = ngRoadmapCourseId(roadmap);
  const courseName =
    db.courses?.[courseId]?.name ||
    roadmap.course_name ||
    roadmap.name ||
    "NextGen Live Course";

  const dayTitle = String(
    day.title ||
    day.topic ||
    day.first_aid_topics ||
    day.system ||
    `Day ${day.day_number || day.order || ""}`
  ).trim();

  if (!dayTitle) return `${courseName} — Live Class`;
  if (dayTitle.toLowerCase().startsWith(String(courseName).toLowerCase())) return dayTitle;
  return `${courseName} — ${dayTitle}`;
}

function ngCanMoveOrReuseLiveSession(session = {}) {
  const status = String(session.status || "scheduled").trim().toLowerCase();
  if (status === "completed") return false;
  if (session.recording_url || session.recording_id || session.transcript_url) return false;
  return true;
}

function ngGetSessionsByRoadmapDayId(db = {}, courseId = "") {
  const map = new Map();
  for (const session of Object.values(db.liveSessions || {})) {
    if (!session?.id) continue;
    if (courseId && String(session.course_id || "") !== String(courseId)) continue;
    const dayId = String(session.roadmap_day_id || "").trim();
    if (!dayId) continue;
    if (!map.has(dayId)) map.set(dayId, []);
    map.get(dayId).push(session);
  }
  return map;
}

function ngPickRoadmapSessionCandidate(db, roadmap, day, usedSessionIds = new Set(), byRoadmapDayId = new Map()) {
  const courseId = ngRoadmapCourseId(roadmap);
  const candidateIds = [
    day.live_session_id,
    day.session_id,
    day.pushed_live_session_id,
    day.pushed_from_live_session_id,
    day.original_day_snapshot?.live_session_id,
    day.original_day_snapshot?.session_id,
  ].map((value) => String(value || "").trim()).filter(Boolean);

  const pushedFromDayId = String(day.pushed_from_day_id || day.original_day_id || "").trim();
  const candidateSessions = [];

  for (const id of candidateIds) {
    if (db.liveSessions?.[id]) candidateSessions.push(db.liveSessions[id]);
  }

  for (const linkedDayId of [day.id, pushedFromDayId].map((value) => String(value || "").trim()).filter(Boolean)) {
    for (const session of byRoadmapDayId.get(linkedDayId) || []) candidateSessions.push(session);
  }

  const seen = new Set();
  for (const session of candidateSessions) {
    if (!session?.id) continue;
    if (seen.has(session.id)) continue;
    seen.add(session.id);
    if (usedSessionIds.has(session.id)) continue;
    if (courseId && String(session.course_id || "") !== courseId) continue;
    if (!ngCanMoveOrReuseLiveSession(session)) continue;
    return session;
  }

  return null;
}

function ngSyncLinkedLiveSessionsForRoadmap(db, roadmap, options = {}) {
  if (!roadmap || !Array.isArray(roadmap.days)) {
    return { synced: 0, created: 0, cancelled: 0, skipped: 0 };
  }

  db.liveSessions = db.liveSessions || {};

  const courseId = ngRoadmapCourseId(roadmap);
  const course = courseId ? db.courses?.[courseId] || null : null;
  const byRoadmapDayId = ngGetSessionsByRoadmapDayId(db, courseId);
  const usedSessionIds = new Set();
  const activeDayIds = new Set();
  const now = new Date().toISOString();
  const counts = { synced: 0, created: 0, cancelled: 0, skipped: 0 };

  // First pass: every scheduled roadmap day must have exactly one live session.
  for (const day of roadmap.days) {
    if (!day?.id) {
      counts.skipped += 1;
      continue;
    }

    if (ngRoadmapDayIsNoClass(day)) {
      day.live_session_id = null;
      day.session_id = null;
      continue;
    }

    activeDayIds.add(String(day.id));

    let session = ngPickRoadmapSessionCandidate(db, roadmap, day, usedSessionIds, byRoadmapDayId);

    if (!session) {
      const sessionId = uuid();
      session = {
        id: sessionId,
        course_id: courseId,
        created_by: options.actorId || options.userId || day.created_by || roadmap.created_by || null,
        created_at: now,
      };
      db.liveSessions[sessionId] = session;
      counts.created += 1;
    }

    const title = ngBuildLiveSessionTitleFromRoadmap(db, roadmap, day);
    const scheduledTime = ngRoadmapClassTime(roadmap, day);
    const timezone = ngRoadmapTimezone(roadmap, day);

    session.course_id = courseId;
    session.topic = title;
    session.title = title;
    session.description = day.description || day.homework || session.description || "";
    session.scheduled_date = day.date || session.scheduled_date || null;
    session.scheduled_time = scheduledTime;
    session.scheduled_timezone = timezone;
    session.duration_minutes = Number(session.duration_minutes || DEFAULT_ZOOM_DURATION_MINUTES) || DEFAULT_ZOOM_DURATION_MINUTES;
    session.instructor_id = session.instructor_id || null;
    session.instructor_name = session.instructor_name || course?.instructor_name || "Dr. Ahmad";
    session.status = String(session.status || "scheduled").toLowerCase() === "completed" ? session.status : "scheduled";
    session.roadmap_day_id = day.id;
    session.source = session.source || "roadmap_sync";
    session.updated_by = options.actorId || options.userId || session.updated_by || null;
    session.updated_at = now;

    day.live_session_id = session.id;
    day.session_id = session.id;
    day.scheduled_date = day.date || day.scheduled_date || null;
    day.scheduled_time = scheduledTime;
    day.class_time = scheduledTime;
    day.updated_at = now;

    usedSessionIds.add(session.id);
    counts.synced += 1;
  }

  // Second pass: holiday/cancelled placeholder days must not keep an active classroom.
  for (const day of roadmap.days) {
    if (!day?.id || !ngRoadmapDayIsNoClass(day)) continue;

    const candidateIds = [day.live_session_id, day.session_id]
      .map((value) => String(value || "").trim())
      .filter(Boolean);

    for (const linkedSession of byRoadmapDayId.get(String(day.id)) || []) {
      if (linkedSession?.id) candidateIds.push(linkedSession.id);
    }

    for (const sessionId of Array.from(new Set(candidateIds))) {
      const session = db.liveSessions?.[sessionId];
      if (!session?.id) continue;
      if (usedSessionIds.has(session.id)) continue;
      if (String(session.course_id || "") !== courseId) continue;
      if (!ngCanMoveOrReuseLiveSession(session)) continue;

      session.status = "cancelled";
      session.cancelled_reason = day.status === "holiday" ? "roadmap_holiday" : "roadmap_cancelled";
      session.roadmap_day_id = day.id;
      session.scheduled_date = day.date || session.scheduled_date || null;
      session.scheduled_time = ngRoadmapClassTime(roadmap, day);
      session.scheduled_timezone = ngRoadmapTimezone(roadmap, day);
      session.title = ngBuildLiveSessionTitleFromRoadmap(db, roadmap, day);
      session.topic = session.title;
      session.updated_by = options.actorId || options.userId || session.updated_by || null;
      session.updated_at = now;
      counts.cancelled += 1;
    }

    day.live_session_id = null;
    day.session_id = null;
    day.updated_at = now;
  }

  roadmap.updated_at = now;
  return counts;
}


function ngClearNoClassRoadmapFields(day = {}) {
  const clearValues = {
    resources: [],
    resource_links: [],
    uworld_qids: [],
    mapped_uworld_qids: [],
    qid_list: [],
    qids: [],
    uworld_target: "",
    homework: "",
    task_items: [],
    tasks: [],
    first_aid_topics: "",
    first_aid_pages: null,
    video_library_lecture: "",
    lecture_title: "",
    live_teaching_topic: "",
    assessment_task: "",
    assessment_day: false,
    assessment_id: null,
    weekly_assessment_id: null,
    weekly_assessment_ready: false,
    grand_assessment_id: null,
    grand_assessment_ready: false,
    live_session_id: null,
    session_id: null,
    session_notes_id: null,
    session_notes_ready: false,
    session_notes_draft_ready: false,
    notes_status: "",
    recording_link: "",
    notes_link: "",
    session_flashcards_ready: false,
    session_flashcards_draft_ready: false,
    session_flashcards_count: 0,
    session_flashcards_draft_count: 0,
    flashcard_tags: [],
    flashcards_enabled: false,
    community_prompt: "",
  };

  for (const [key, value] of Object.entries(clearValues)) {
    day[key] = Array.isArray(value) ? [...value] : value;
  }

  return day;
}

function ngReplaceRoadmapDayIdList(values, fromDayId, toDayId) {
  if (!Array.isArray(values)) return values;
  return Array.from(new Set(values.map((item) => String(item || "") === String(fromDayId) ? toDayId : item).filter(Boolean)));
}

function ngRelinkRoadmapDayDependencies(db, { courseId = "", fromDayId = "", toDay = null, actorId = null } = {}) {
  const cleanCourseId = String(courseId || "").trim();
  const oldDayId = String(fromDayId || "").trim();
  const newDayId = String(toDay?.id || "").trim();
  const now = new Date().toISOString();
  const counts = {
    flashcards: 0,
    flashcard_progress: 0,
    assessments: 0,
    assessment_attempts: 0,
    notes: 0,
    roadmap_progress: 0,
    daily_task_progress: 0,
    point_events: 0,
    weak_concepts: 0,
    leaderboards_rebuilt: 0,
  };
  const affectedUsers = new Set();

  if (!oldDayId || !newDayId || oldDayId === newDayId) return counts;

  const courseMatches = (item = {}) => {
    if (!cleanCourseId) return true;
    const itemCourseId = String(item.course_id || item.courseId || "").trim();
    return !itemCourseId || itemCourseId === cleanCourseId;
  };

  const relinkDayFields = (item = {}) => {
    let changed = false;
    if (String(item.roadmap_day_id || "") === oldDayId) {
      item.roadmap_day_id = newDayId;
      changed = true;
    }
    if (String(item.day_id || "") === oldDayId) {
      item.day_id = newDayId;
      changed = true;
    }
    if (Array.isArray(item.source_roadmap_day_ids)) {
      const next = ngReplaceRoadmapDayIdList(item.source_roadmap_day_ids, oldDayId, newDayId);
      if (JSON.stringify(next) !== JSON.stringify(item.source_roadmap_day_ids)) {
        item.source_roadmap_day_ids = next;
        changed = true;
      }
    }
    return changed;
  };

  for (const card of Object.values(db.flashcards || {})) {
    if (!card?.id || !courseMatches(card)) continue;
    if (!relinkDayFields(card)) continue;
    card.day_number = toDay.day_number || card.day_number || null;
    card.scheduled_date = toDay.date || card.scheduled_date || null;
    card.due_date = card.due_date && String(card.due_date) === String(toDay.original_day_snapshot?.date || "") ? toDay.date : (card.due_date || toDay.date || null);
    card.updated_by = actorId || card.updated_by || null;
    card.updated_at = now;
    counts.flashcards += 1;
  }

  for (const item of Object.values(db.flashcardProgress || {})) {
    if (!item || !courseMatches(item)) continue;
    if (!relinkDayFields(item)) continue;
    if (item.user_id) affectedUsers.add(String(item.user_id));
    item.updated_at = now;
    counts.flashcard_progress += 1;
  }

  for (const assessment of Object.values(db.assessments || {})) {
    if (!assessment?.id || !courseMatches(assessment)) continue;
    if (!relinkDayFields(assessment)) continue;
    assessment.day_number = toDay.day_number || assessment.day_number || null;
    assessment.system = assessment.system || toDay.system || "";
    assessment.updated_by = actorId || assessment.updated_by || null;
    assessment.updated_at = now;
    counts.assessments += 1;
  }

  for (const attempt of Object.values(db.assessmentAttempts || {})) {
    if (!attempt || !courseMatches(attempt)) continue;
    if (!relinkDayFields(attempt)) continue;
    if (attempt.user_id) affectedUsers.add(String(attempt.user_id));
    attempt.updated_at = now;
    counts.assessment_attempts += 1;
  }

  for (const note of Object.values(db.notes || {})) {
    if (!note || !courseMatches(note)) continue;
    if (!relinkDayFields(note)) continue;
    note.day_number = toDay.day_number || note.day_number || null;
    note.updated_by = actorId || note.updated_by || null;
    note.updated_at = now;
    counts.notes += 1;
  }

  const rekeyBucketByDay = (bucketName) => {
    const bucket = db[bucketName] || {};
    const nextEntries = [];
    for (const [id, item] of Object.entries(bucket)) {
      if (!item || !courseMatches(item)) continue;
      const matches = String(item.day_id || item.roadmap_day_id || "") === oldDayId || String(id).includes(oldDayId);
      if (!matches) continue;
      relinkDayFields(item);
      item.day_number = toDay.day_number || item.day_number || null;
      item.updated_at = now;
      if (item.user_id) affectedUsers.add(String(item.user_id));

      let nextId = String(item.id || id).replace(oldDayId, newDayId);
      if (nextId === String(item.id || id) && cleanCourseId && item.user_id) nextId = `${cleanCourseId}:${item.user_id}:${newDayId}`;
      item.id = nextId;
      nextEntries.push([id, nextId, item]);
    }

    for (const [oldKey, newKey, item] of nextEntries) {
      if (oldKey !== newKey) {
        if (bucket[newKey]) {
          bucket[newKey] = {
            ...bucket[newKey],
            ...item,
            tasks: { ...(bucket[newKey].tasks || {}), ...(item.tasks || {}) },
            updated_at: now,
          };
        } else {
          bucket[newKey] = item;
        }
        delete bucket[oldKey];
      } else {
        bucket[oldKey] = item;
      }
    }

    db[bucketName] = bucket;
    return nextEntries.length;
  };

  counts.roadmap_progress += rekeyBucketByDay("roadmapProgress");
  counts.daily_task_progress += rekeyBucketByDay("dailyTaskProgress");

  for (const event of Object.values(db.pointEvents || {})) {
    if (!event || !courseMatches(event)) continue;
    if (!relinkDayFields(event)) continue;
    event.day_number = toDay.day_number || event.day_number || null;
    event.updated_at = now;
    if (event.user_id) affectedUsers.add(String(event.user_id));
    counts.point_events += 1;
  }

  for (const weak of Object.values(db.weakConceptLogs || {})) {
    if (!weak || !courseMatches(weak)) continue;
    if (!relinkDayFields(weak)) continue;
    weak.day_number = toDay.day_number || weak.day_number || null;
    weak.system = weak.system || toDay.system || "";
    weak.updated_at = now;
    if (weak.user_id) affectedUsers.add(String(weak.user_id));
    counts.weak_concepts += 1;
  }

  if (cleanCourseId) {
    for (const userId of affectedUsers) {
      const user = db.users?.[userId] || null;
      updateLeaderboard(db, { courseId: cleanCourseId, userId, userName: user?.name || user?.email || "Student" });
      counts.leaderboards_rebuilt += 1;
    }
  }

  return counts;
}

function ngRecalculateRoadmapSchedule(db, roadmap, { startDate = "", skipSundays = true } = {}) {
  if (!roadmap || !Array.isArray(roadmap.days) || !roadmap.days.length) return roadmap;
  const firstDate = startDate || roadmap.start_date || roadmap.settings?.start_date || roadmap.days[0]?.date || todayKey();
  let cursor = ngNextStudyDate(new Date(`${firstDate}T00:00:00`), skipSundays);
  roadmap.days.forEach((day, index) => {
    cursor = ngNextStudyDate(cursor, skipSundays);
    day.day_number = index + 1;
    day.order = index + 1;
    day.week_number = Math.ceil((index + 1) / 7);
    day.date = dateOnly(cursor);
    day.updated_at = new Date().toISOString();
    cursor.setDate(cursor.getDate() + 1);
  });
  ngSyncLinkedLiveSessionsForRoadmap(db, roadmap);
  roadmap.updated_at = new Date().toISOString();
  return roadmap;
}

function ngResetObjectByCourse(db, key, courseId, shouldRemove = null) {
  const bucket = db[key] || {};
  let removed = 0;
  for (const [id, item] of Object.entries(bucket)) {
    const itemCourseId = String(item?.course_id || item?.courseId || "");
    const keyMatches = String(id).startsWith(`${courseId}:`) || String(id).includes(`:${courseId}:`);
    const courseMatches = itemCourseId === String(courseId) || keyMatches;
    if (!courseMatches) continue;
    if (typeof shouldRemove === "function" && !shouldRemove(item, id)) continue;
    delete bucket[id];
    removed += 1;
  }
  db[key] = bucket;
  return removed;
}

function ngResetCourseAcademicContent(db, options = {}) {
  const courseId = String(options.courseId || options.course_id || "").trim();
  if (!courseId) return { error: "course_id is required" };

  const counts = {
    roadmap_days_removed: 0,
    live_sessions_removed: 0,
    flashcards_archived: 0,
    assessments_removed: 0,
    daily_task_progress_removed: 0,
    weak_concepts_removed: 0,
    flashcard_progress_removed: 0,
    point_events_removed: 0,
  };

  const roadmap = db.roadmaps?.[courseId] || null;
  const roadmapDayIds = new Set((Array.isArray(roadmap?.days) ? roadmap.days : []).map((day) => String(day.id || "")).filter(Boolean));

  if (options.clearGeneratedLiveSessions !== false || options.clearAllCourseLiveSessions === true) {
    db.liveSessions = db.liveSessions || {};
    for (const [id, session] of Object.entries(db.liveSessions)) {
      const isCourseSession = String(session?.course_id || "") === courseId;
      const isLinkedToRoadmap = session?.roadmap_day_id && roadmapDayIds.has(String(session.roadmap_day_id));
      const isGenerated = isLinkedToRoadmap || String(session?.source || "").includes("roadmap") || String(session?.topic || "").includes("Day ");
      if (isCourseSession && (options.clearAllCourseLiveSessions === true || isGenerated)) {
        delete db.liveSessions[id];
        counts.live_sessions_removed += 1;
      }
    }
  }

  if (options.archiveGeneratedFlashcards !== false || options.archiveAllCourseFlashcards === true) {
    db.flashcards = db.flashcards || {};
    const systemFilter = String(options.system || "").trim();
    for (const card of Object.values(db.flashcards)) {
      if (!card || String(card.course_id || "") !== courseId) continue;
      if (systemFilter && ngNormalizeMasterMapSystemName(card.system || card.topic || "") !== ngNormalizeMasterMapSystemName(systemFilter)) continue;
      const isLinkedToRoadmap = card.roadmap_day_id && roadmapDayIds.has(String(card.roadmap_day_id));
      const isGenerated = isLinkedToRoadmap || /generated|roadmap|weak_area|daily_topic/i.test(String(card.source || card.scope || ""));
      if (options.archiveAllCourseFlashcards === true || isGenerated) {
        card.status = "archived";
        card.is_published = false;
        card.archived_reason = options.reason || "course_academic_reset";
        card.archived_at = nowIso();
        card.updated_by = options.actorId || card.updated_by || null;
        card.updated_at = nowIso();
        counts.flashcards_archived += 1;
      }
    }
  }

  if (options.clearAssessments !== false) {
    counts.assessments_removed = ngResetObjectByCourse(db, "assessments", courseId, (assessment) => {
      return options.clearAllCourseAssessments === true || (assessment?.roadmap_day_id && roadmapDayIds.has(String(assessment.roadmap_day_id))) || /roadmap|marathon|system_end/i.test(String(assessment?.source_type || assessment?.assessment_type || ""));
    });
  }

  if (options.clearProgress !== false) {
    counts.daily_task_progress_removed = ngResetObjectByCourse(db, "dailyTaskProgress", courseId);
    counts.weak_concepts_removed = ngResetObjectByCourse(db, "weakConceptLogs", courseId);
    counts.flashcard_progress_removed = ngResetObjectByCourse(db, "flashcardProgress", courseId);
    counts.point_events_removed = ngResetObjectByCourse(db, "pointEvents", courseId);
  }

  if (options.resetRoadmap === true && db.roadmaps?.[courseId]) {
    counts.roadmap_days_removed = Array.isArray(db.roadmaps[courseId].days) ? db.roadmaps[courseId].days.length : 0;
    delete db.roadmaps[courseId];
  }

  return counts;
}

function ngDefaultMarathonSystems() {
  return [
    { system: "Cardiology", days: 14, topics: ["cardiac physiology foundation", "murmurs and valvular disease", "ischemia and heart failure", "arrhythmias and pharmacology"] },
    { system: "MSK", days: 10, topics: ["bone and joint foundation", "muscle and connective tissue", "arthritis and bone pathology"] },
    { system: "Neurology / CNS", days: 15, topics: ["neuroanatomy and localization", "stroke/seizure/movement", "CNS pathology and pharmacology"] },
    { system: "Reproductive", days: 10, topics: ["female reproductive physiology", "pregnancy and pathology", "male reproductive and endocrine integration"] },
    { system: "Endocrinology", days: 9, topics: ["diabetes and thyroid", "adrenal and pituitary", "calcium/PTH and endocrine pharmacology"] },
    { system: "GIT", days: 13, topics: ["GI physiology", "liver/pancreas", "malabsorption/IBD/GI pathology"] },
    { system: "Renal", days: 11, topics: ["nephron physiology", "acid-base and electrolytes", "glomerular disease and diuretics"] },
    { system: "Pulmonology / Respiratory", days: 10, topics: ["pulmonary mechanics", "V/Q and gas exchange", "obstructive/restrictive lung disease"] },
    { system: "Immunology", days: 7, topics: ["immune cells and complement", "hypersensitivity and immunodeficiency", "autoimmunity and transplant"] },
    { system: "Hematology", days: 10, topics: ["RBC and anemia", "WBC malignancy", "platelets/coagulation/transfusion"] },
    { system: "Psychiatry", days: 7, topics: ["mood/anxiety/psychosis", "substance/personality", "psych pharmacology"] },
    { system: "Mixed Review + Final Correction", days: 4, topics: ["weak-area repair", "mixed QID correction", "final readiness review"] },
  ];
}

function ngNextStudyDate(date, skipSundays = true) {
  const d = new Date(date);
  while (skipSundays && d.getDay() === 0) d.setDate(d.getDate() + 1);
  return d;
}

function ngBuildMarathonDay({ courseId, dayNumber, weekNumber, date, system, systemDay, totalSystemDays, topic, qids = "" }) {
  const isAssessment = systemDay === totalSystemDays && !system.toLowerCase().includes("mixed");
  const title = isAssessment ? `${system} — System-End Assessment + Correction` : `${system} Day ${systemDay} — ${topic}`;
  const description = isAssessment
    ? `System-end assessment and correction day for ${system}. Students review incorrects, rewatch weak UWorld Video Library explanations, revise First Aid/Pathoma notes, and post one confusing concept in Community Q&A.`
    : `Live First Aid session with Dr. Ahmad for ${system}. After class, watch the matching UWorld Video Library QID explanations, complete the assigned UWorld QIDs externally, log weak concepts, review flashcards, earn leaderboard points, and post one confusing concept in Community Q&A.`;
  return {
    id: uuid(), course_id: courseId, week_number: weekNumber, day_number: dayNumber, date: dateOnly(date),
    system, system_day: systemDay, title, description,
    resources: isAssessment ? ["First Aid", "UWorld Video Library", "Assessment", "Incorrect Review", "Leaderboard", "Community Q&A"] : ["First Aid", "Pathoma", "UWorld Video Library", "Live Session Recording", "Class Notes", "Daily Flashcards", "Community Q&A", "Leaderboard"],
    resource_links: [],
    uworld_target: isAssessment ? `${system} system-end assessment + incorrect review` : (qids || `${system} mapped QIDs: 30-40 MCQs or assigned block`),
    uworld_qids: ngNormalizeQidList(qids),
    mapped_uworld_qids: ngNormalizeQidList(qids),
    video_library_lecture: `${system} Video Library — Day ${systemDay}`,
    first_aid_topics: topic,
    homework: isAssessment ? "Complete the system-end assessment, review incorrects, rewatch weak video-library explanations, and submit correction notes for leaderboard points." : "Attend Dr. Ahmad’s live First Aid session, watch the matching UWorld Video Library QID explanations, complete assigned UWorld QIDs externally, log wrongs/weak concepts, review daily flashcards, submit the daily task, earn leaderboard task points, and post one confusing concept in Community Q&A.",
    status: "scheduled",
    is_published: true,
    published: true,
    assessment_day: isAssessment,
    flashcards_enabled: true,
    task_items: ngBuildDefaultTaskItems({ assessment_day: isAssessment }),
  };
}

function ngBuildDailyFlashcardsForDay(day) {
  if (!day || day.assessment_day) return [];
  const topic = day.first_aid_topics || day.system || "today’s topic";
  return [
    { front: `What is the key concept for ${topic}?`, back: `Review the live class notes for ${topic}, then connect the mechanism to the assigned UWorld QIDs.`, explanation: "Use active recall before watching the video explanation." },
    { front: `Which mistake should you avoid in ${day.system}?`, back: "Do not memorize the answer only. Identify the mechanism, diagnosis clue, and wrong-option trap.", explanation: "This card is for correction-based revision." },
    { front: `What should you do after completing today’s ${day.system} QIDs?`, back: "Watch the matching UWorld Video Library QID explanations first, complete assigned UWorld QIDs externally, log wrongs/weak concepts, review notes/recording, post one confusing concept in Community Q&A, and submit the daily task.", explanation: "This links daily study work to leaderboard accountability." },
  ];
}


app.get("/admin/roadmap/master-map", async (req, res) => {
  try {
    await requireLmsPermission(req, "lms.roadmap.manage");
    const db = await readLiveDb();
    const template = String(req.query.template || NEXTGEN_MASTER_MAP_TEMPLATE_KEY).trim() || NEXTGEN_MASTER_MAP_TEMPLATE_KEY;
    const item = db.roadmapMasterMaps?.[template] || null;
    const rows = ngNormalizeMasterMapRows(item?.rows || []);
    const bySystem = {};
    for (const row of rows) bySystem[row.system] = (bySystem[row.system] || 0) + 1;
    res.json({ success: true, template, exists: Boolean(item), map: item ? { ...item, rows: req.query.with_rows === "true" ? rows : undefined } : null, count: rows.length, by_system: bySystem, systems: Object.keys(bySystem) });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});

app.post("/admin/roadmap/import-master-map", async (req, res) => {
  try {
    const { user } = await requireLmsPermission(req, "lms.roadmap.manage");
    const db = await readLiveDb();
    const template = String(req.body.template || NEXTGEN_MASTER_MAP_TEMPLATE_KEY).trim() || NEXTGEN_MASTER_MAP_TEMPLATE_KEY;
    const rawRows = req.body.rows || req.body.days || req.body.master_map || req.body.map || req.body.json_text || [];
    const normalizedRows = ngNormalizeMasterMapRows(rawRows);
    const systemSequence = ngExtractMasterMapSystemSequence(req.body || {}, normalizedRows);
    const rows = ngSortMasterRowsForSequence(normalizedRows, systemSequence);
    if (!rows.length) return res.status(400).json({ success: false, error: "Master map JSON must contain at least one valid row/day" });
    const bySystem = {};
    for (const row of rows) bySystem[row.system] = (bySystem[row.system] || 0) + 1;
    db.roadmapMasterMaps = db.roadmapMasterMaps || {};
    db.roadmapMasterMaps[template] = {
      id: template,
      template,
      name: String(req.body.name || "NextGen 120-Day Step 1 Master Map").trim(),
      rows,
      count: rows.length,
      by_system: bySystem,
      system_sequence: systemSequence,
      source: "admin_json_import",
      imported_by: user.id,
      imported_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };
    await writeLiveDb(db);
    res.json({ success: true, template, count: rows.length, by_system: bySystem, system_sequence: systemSequence, first_system: systemSequence[0] || rows[0]?.system || null, map: { ...db.roadmapMasterMaps[template], rows: undefined }, message: `Master map imported: ${rows.length} rows` });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});

app.post("/admin/roadmap/:dayId/push-status", async (req, res) => {
  try {
    const { user } = await requireLmsPermission(req, "lms.roadmap.manage");
    const db = await readLiveDb();
    const status = String(req.body.status || req.body.roadmap_status || "holiday").toLowerCase();
    if (!["holiday", "cancelled"].includes(status)) return res.status(400).json({ success: false, error: "status must be holiday or cancelled" });
    const ref = ngFindAdminRoadmapDayRef(db, { courseId: req.body.course_id || req.query.course_id, dayId: req.params.dayId });
    if (!ref.roadmap || !ref.day) return res.status(404).json({ success: false, error: "Roadmap item not found" });
    const originalDayId = String(ref.day.id || "").trim();
    const originalContent = {
      ...ref.day,
      id: `${ref.courseId}:day:pushed:${uuid()}`,
      pushed_from_day_id: originalDayId,
      status: "scheduled",
      roadmap_status: "scheduled",
      live_session_id: null,
      session_id: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      updated_by: user.id,
    };
    const placeholderTitle = status === "holiday" ? "Holiday / No Live Class" : "Cancelled / Content Pushed";
    ref.roadmap.days[ref.index] = ngClearNoClassRoadmapFields({
      ...ref.day,
      title: req.body.title || placeholderTitle,
      description: req.body.description || (status === "holiday" ? "No academic task today. The planned content has been pushed to the next teaching day." : "Class cancelled. The planned content has been pushed to the next teaching day."),
      status,
      roadmap_status: status,
      is_schedule_placeholder: true,
      pushed_content_day_id: originalContent.id,
      original_day_snapshot: req.body.keep_snapshot === false ? undefined : ref.day,
      updated_by: user.id,
      updated_at: new Date().toISOString(),
    });
    ref.roadmap.days.splice(ref.index + 1, 0, originalContent);
    const skipSundays = ref.roadmap.skip_sundays !== false && ref.roadmap.settings?.skip_sundays !== false;
    const startDate = ref.roadmap.start_date || ref.roadmap.settings?.start_date || ref.roadmap.days[0]?.date || todayKey();
    ngRecalculateRoadmapSchedule(db, ref.roadmap, { startDate, skipSundays });
    const movedContentDay = ref.roadmap.days.find((day) => String(day.id || "") === String(originalContent.id));
    const dependencySync = ngRelinkRoadmapDayDependencies(db, {
      courseId: ref.courseId,
      fromDayId: originalDayId,
      toDay: movedContentDay || originalContent,
      actorId: user.id,
    });
    const liveSessionSync = ngSyncLinkedLiveSessionsForRoadmap(db, ref.roadmap, { actorId: user.id });
    db.roadmaps[ref.courseId] = ref.roadmap;
    await writeLiveDb(db);
    res.json({ success: true, status, pushed: true, roadmap: ref.roadmap, days: ref.roadmap.days.map(sanitizeRoadmapDay), dependency_sync: dependencySync, live_session_sync: liveSessionSync, message: `${status} added and following content, live sessions, notes, flashcards, assessments, progress, and leaderboard links were pushed forward.` });
  } catch (error) { res.status(error.statusCode || 500).json({ success: false, error: error.message }); }
});

